INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde0348c-0a2f-49d4-b2aa-1a0625e7663c', '司馬承禎含象鑑文 一', '司马承禎含象鑑文 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["天地含象，日月貞明。","寫規萬物，洞鑒百靈。"]', '["天地含象，日月貞明。","寫規万物，洞鑒百靈。"]', '诗', 'shi', '', NULL, '司馬承禎含象鑑文 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aab021b1-1d2f-4393-8a83-962c78f718bf', '司馬承禎含象鑑文 二', '司马承禎含象鑑文 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["龜自卜，鏡自照。","吉可募，光不曜。"]', '["龟自卜，镜自照。","吉可募，光不曜。"]', '诗', 'shi', '', NULL, '司馬承禎含象鑑文 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96cc24bb-a878-421f-af61-0ad16aec3a98', '司馬承禎含象鑑文 三', '司马承禎含象鑑文 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["青蓋作鏡大吉昌，巧工刊之成文章。","左龍右虎辟不祥，朱鳥玄武順於旁，子孫富貴居中央。"]', '["青蓋作镜大吉昌，巧工刊之成文章。","左龙右虎辟不祥，朱鸟玄武順於旁，子孫富貴居中央。"]', '诗', 'shi', '', NULL, '司馬承禎含象鑑文 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19b28bd5-7c64-49b5-822b-879e5d8869e1', '景震劒文 一', '景震劒文 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["撝雷電，運玄星。","摧凶惡，亨利貞。"]', '["撝雷電，運玄星。","摧凶惡，亨利貞。"]', '诗', 'shi', '', NULL, '景震劒文 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ebd484-8ba0-4508-a88a-cf4fa9071f8a', '景震劒文 二', '景震劒文 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["乾降精，坤應靈。","日月象，岳瀆形。"]', '["乾降精，坤應靈。","日月象，岳瀆形。"]', '诗', 'shi', '', NULL, '景震劒文 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a08feced-2d31-4e1c-b7b4-13bec141385c', '高麗鏡文', '高丽镜文', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["三水中，四維下，上帝降子於辰馬。","先操雞，後搏鴨。","己年中，二龍見。","一則藏身青木中，一則見形黑金東。"]', '["三水中，四維下，上帝降子於辰马。","先操雞，後搏鴨。","己年中，二龙见。","一則藏身青木中，一則见形黑金东。"]', '诗', 'shi', '', NULL, '高麗鏡文 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c94992-f5dc-4fdc-b0eb-6d53dc734f62', '京西市放生池墓銘', '京西市放生池墓銘', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["龜言市，蓍言水。"]', '["龟言市，蓍言水。"]', '诗', 'shi', '', NULL, '京西市放生池墓銘 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20443250-ca50-45dc-9b3e-41f6b26bd16a', '古墓卜地詞', '古墓卜地词', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["爾後一千歲，此地化爲泉。","賴逢鄔侍御，移我向高原。"]', '["爾後一千歲，此地化爲泉。","賴逢鄔侍御，移我向高原。"]', '诗', 'shi', '', NULL, '古墓卜地詞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('816a3132-7972-4830-ba11-8046800e13a2', '衛先生墓銘', '衛先生墓銘', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["姜師度，更移向南三五步。"]', '["姜師度，更移向南三五步。"]', '诗', 'shi', '', NULL, '衛先生墓銘 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e95e238-e2f6-44ba-9a57-3c8e6bd8196e', '隱者瘞男銘', '隐者瘞男銘', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["神真鍊形年未足，化爲我子功相續。","丞相瘞之刻玄玉，仙路何長死何促。"]', '["神真鍊形年未足，化爲我子功相續。","丞相瘞之刻玄玉，仙路何长死何促。"]', '诗', 'shi', '', NULL, '隱者瘞男銘 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1da51193-6972-4fcf-871c-dc5cf4e28c62', '烏氏葬碑', '烏氏葬碑', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["牛領岡頭，紅簫籠下。","葬用兩日，手板相亞。"]', '["牛領岡头，紅簫籠下。","葬用兩日，手板相亞。"]', '诗', 'shi', '', NULL, '烏氏葬碑 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed564cbb-70e0-4c3d-b1cd-717d5694dbea', '巖腹棺銘', '巖腹棺銘', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["欲墮不墮逢王果，五百年中重收我。"]', '["欲墮不墮逢王果，五百年中重收我。"]', '诗', 'shi', '', NULL, '巖腹棺銘 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('758542b4-896b-41e7-832e-6df14f9f4502', '古棺石銘', '古棺石銘', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["欲陷不陷被藤縛，欲落不落被沙閣，五百年後遇熊博。"]', '["欲陷不陷被藤縛，欲落不落被沙閣，五百年後遇熊博。"]', '诗', 'shi', '', NULL, '古棺石銘 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7125f23e-e1aa-4ec9-9113-83be55fc7dcb', '漣水古冢缾文', '漣水古冢缾文', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一雙青烏子，飛來五兩頭。","借問船輕重，寄信到揚州。"]', '["一雙青烏子，飞来五兩头。","借问船轻重，寄信到揚州。"]', '诗', 'shi', '', NULL, '漣水古冢缾文 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4cca7ac-9514-4fb2-843f-6b75a67d8150', '沈彬壙篆', '沈彬壙篆', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["佳城今已開，雖開不葬埋。","漆燈猶未滅，留待沈彬來。"]', '["佳城今已开，雖开不葬埋。","漆灯猶未滅，留待沈彬来。"]', '诗', 'shi', '', NULL, '沈彬壙篆 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45304bf4-4738-461d-8428-5a44882200bb', '廣陵古冢石刻', '廣陵古冢石刻', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["日爲箭兮月爲弓，四時躬人兮無窮。","但得天將明月死，不覺人隨流水空。","山川秀兮碧穹窿，崇夫人墓兮直其中。","猨啼鳥嘯煙濛濛，千年萬年松柏風。"]', '["日爲箭兮月爲弓，四时躬人兮無窮。","但得天將明月死，不覺人隨流水空。","山川秀兮碧穹窿，崇夫人墓兮直其中。","猨啼鸟嘯煙濛濛，千年万年松柏风。"]', '诗', 'shi', '', NULL, '廣陵古冢石刻 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('906e243c-eb25-47d2-a783-a9831c53e313', '王承檢掘得墓銘', '王承檢掘得墓銘', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["車道之北，邽山之陽。","深深葬玉，鬱鬱埋香。","刻斯貞石，煥乎遺芳。","地變陵谷，嶮列城隍。","乾德丙年，壞者合郎。"]', '["车道之北，邽山之陽。","深深葬玉，鬱鬱埋香。","刻斯貞石，煥乎遺芳。","地变陵谷，嶮列城隍。","乾德丙年，壞者合郎。"]', '诗', 'shi', '', NULL, '王承檢掘得墓銘 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4408b69-7e0d-4811-97b5-b6243f171221', '馬希振葬地碣', '马希振葬地碣', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["亂石之壤，絕世之岡。","谷變庚戌，馬氏無王。"]', '["亂石之壤，絕世之岡。","谷变庚戌，马氏無王。"]', '诗', 'shi', '', NULL, '馬希振葬地碣 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a427556e-f30b-4f8e-b51a-2382d681c5e6', '二賀詩', '二賀诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["學行可師賀德基，文質彬彬賀德仁。"]', '["学行可師賀德基，文質彬彬賀德仁。"]', '诗', 'shi', '', NULL, '二賀詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90e814c9-f1aa-49d0-a401-9918ebe1965c', '四王語', '四王語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["寧向儋崖振白，不事江滕蔣虢。"]', '["寧向儋崖振白，不事江滕蔣虢。"]', '诗', 'shi', '', NULL, '四王語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd399f2c-dcff-47b2-9b50-36b955ae259f', '時人爲屈突語', '时人爲屈突語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["寧食三斗艾，不見屈突蓋。","寧服三斗蔥，不逢屈突通。"]', '["寧食三斗艾，不见屈突蓋。","寧服三斗蔥，不逢屈突通。"]', '诗', 'shi', '', NULL, '時人爲屈突語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4def2064-f3ac-479b-ade7-3ef39b62a618', '楊刺史語', '楊刺史語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["寧食三斗蒜，不逢楊德幹。"]', '["寧食三斗蒜，不逢楊德幹。"]', '诗', 'shi', '', NULL, '楊刺史語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('227e3497-be5a-44f4-9896-d29b1e57cf6e', '萬年人語', '万年人語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["寧食三斗塵，無逢權懷恩。"]', '["寧食三斗塵，無逢權懷恩。"]', '诗', 'shi', '', NULL, '萬年人語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfcec8df-e5fc-49ef-a8c5-e22e5d58f0da', '贊皇人語', '贊皇人語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["太沖無兄，孝端無弟。"]', '["太沖無兄，孝端無弟。"]', '诗', 'shi', '', NULL, '贊皇人語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a832b3f0-134d-44cc-8000-6972cf94d9eb', '高宗時語', '高宗时語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["左相宣威沙漠，右相馳譽丹青。","三館學生放散，五臺令史經明。"]', '["左相宣威沙漠，右相驰譽丹青。","三館学生放散，五台令史經明。"]', '诗', 'shi', '', NULL, '高宗時語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb128c4f-4ff6-481f-b07c-db6d6c003218', '時人爲李義甫語', '时人爲李義甫語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["今日巨唐年，還誅四凶族。"]', '["今日巨唐年，還誅四凶族。"]', '诗', 'shi', '', NULL, '時人爲李義甫語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a55d9d2-1617-4bfd-b6ef-cc94648626c9', '洛州語', '洛州語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["洛州有前賈後張，可敵京兆三王。"]', '["洛州有前賈後張，可敵京兆三王。"]', '诗', 'shi', '', NULL, '洛州語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36837636-3835-4510-b760-d1f0ee07b1d7', '江淮間語', '江淮间語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["貴如許郝，富若田彭。"]', '["貴如許郝，富若田彭。"]', '诗', 'shi', '', NULL, '江淮間語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f410c73e-f883-42dc-a9dc-50361cc5b0cc', '河北語', '河北語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["唯此兩何，殺人最多。"]', '["唯此兩何，殺人最多。"]', '诗', 'shi', '', NULL, '河北語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7edbc0d-0821-4742-b8b2-65f9ea1e5291', '李昭德爲王弘義語', '李昭德爲王弘義語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昔聞蒼鷹獄吏，今見白兔御史。"]', '["昔闻蒼鷹獄吏，今见白兔御史。"]', '诗', 'shi', '', NULL, '李昭德爲王弘義語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b16ebb-8c48-4282-888e-ba584a490b09', '京洛語', '京洛語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["衣裳好，儀貌惡。","不姓許，即姓郝。"]', '["衣裳好，儀貌惡。","不姓許，即姓郝。"]', '诗', 'shi', '', NULL, '京洛語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d00136a-29ce-4750-8e94-68bd62a786fe', '臺中語', '台中語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["侯知一不伏致仕，張悰自請起復。","高筠不肯作孝，張栖貞情願遭憂。"]', '["侯知一不伏致仕，張悰自請起复。","高筠不肯作孝，張栖貞情願遭憂。"]', '诗', 'shi', '', NULL, '臺中語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a082f88c-00aa-45ab-aa80-73394824ee1b', '吏人語', '吏人語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["不畏侯卿杖，惟畏尹卿筆。"]', '["不畏侯卿杖，惟畏尹卿笔。"]', '诗', 'shi', '', NULL, '吏人語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85c12118-a8fa-4972-9067-7b239f3469f1', '選人語 一', '選人語 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["有錢石上好，無錢劉下好，士大夫張下好。"]', '["有錢石上好，無錢劉下好，士大夫張下好。"]', '诗', 'shi', '', NULL, '選人語 一 不詳 shi');
