INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a219ac0-1ab5-4218-8632-c00125fd3dcf', '大明寺壁語', '大明寺壁語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一人堂堂，二曜同光。","泉深尺一，點去冰傍。","二人相連，不欠一邊。","三梁四柱烈火然，除却雙勾兩日全。"]', '["一人堂堂，二曜同光。","泉深尺一，点去冰傍。","二人相連，不欠一邊。","三梁四柱烈火然，除却雙勾兩日全。"]', '诗', 'shi', '', NULL, '大明寺壁語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa6f42f2-31e8-4613-910a-1f0dac8c52f2', '曹著與客謎 一', '曹著與客謎 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一物坐也坐，臥也坐，行也坐。"]', '["一物坐也坐，臥也坐，行也坐。"]', '诗', 'shi', '', NULL, '曹著與客謎 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceddeba7-786b-441b-a9ff-3a7b73e03df4', '曹著與客謎 二', '曹著與客謎 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一物坐也臥，立也臥，行也臥，走也臥，臥也臥。"]', '["一物坐也臥，立也臥，行也臥，走也臥，臥也臥。"]', '诗', 'shi', '', NULL, '曹著與客謎 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5276d1f-dbb9-4bd2-9b1d-a6208989ba24', '客題青龍寺門', '客題青龙寺门', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["龕龍去東海，時日隱西斜。","敬文今不在，碎石入流沙。"]', '["龕龙去东海，时日隐西斜。","敬文今不在，碎石入流沙。"]', '诗', 'shi', '', NULL, '客題青龍寺門 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb0c7f85-b2e9-4cbe-b489-02446d1e7175', '陶穀題南唐官舍壁', '陶穀題南唐官舍壁', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["西川狗，百姓眼。","馬包兒，御廚飯。"]', '["西川狗，百姓眼。","马包兒，御廚飯。"]', '诗', 'shi', '', NULL, '陶穀題南唐官舍壁 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43944f8a-2efc-42c0-a25e-d4057fe7da92', '謝小娥夢盜姓名', '謝小娥梦盜姓名', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["車中猴，門東草。","禾中走，一日夫。"]', '["车中猴，门东草。","禾中走，一日夫。"]', '诗', 'shi', '', NULL, '謝小娥夢盜姓名 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2e4bd78-f7b8-4468-914f-a1dc3f63ff69', '牛口謠', '牛口謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["豆入牛口，勢不得久。"]', '["豆入牛口，勢不得久。"]', '诗', 'shi', '', NULL, '牛口謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2ab25e2-b2f1-43a1-98a2-14e2ec501375', '高昌童謠', '高昌童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["高昌兵馬如霜雪，漢家兵馬如日月。","日月照霜雪，回首自消滅。"]', '["高昌兵马如霜雪，漢家兵马如日月。","日月照霜雪，回首自消滅。"]', '诗', 'shi', '', NULL, '高昌童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b27a7d-9ec3-4c03-81e7-eb65f40eaa57', '咸亨後謠', '咸亨後謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["莫浪語，阿婆嗔，三叔聞時笑殺人。"]', '["莫浪語，阿婆嗔，三叔闻时笑殺人。"]', '诗', 'shi', '', NULL, '咸亨後謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00f1a3df-92ff-4cb9-97ae-ea2f54f7229c', '調露初京城民謠', '調露初京城民謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["側堂堂，撓堂堂。"]', '["側堂堂，撓堂堂。"]', '诗', 'shi', '', NULL, '調露初京城民謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f21c0426-7336-4a24-bd48-f4b0ebe0a21e', '嵩嶽童謠', '嵩嶽童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["嵩山凡幾層，不畏登不得，只畏不得登。","三度徵兵馬，傍道打騰騰。"]', '["嵩山凡幾層，不畏登不得，只畏不得登。","三度徵兵马，傍道打腾腾。"]', '诗', 'shi', '', NULL, '嵩嶽童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('092fb0fa-81cc-4be7-8989-4023370d5540', '李敬玄謠', '李敬玄謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["洮河李阿婆，鄯州王伯母。","見賊不敢鬬，總由曹新婦。"]', '["洮河李阿婆，鄯州王伯母。","见賊不敢鬬，總由曹新婦。"]', '诗', 'shi', '', NULL, '李敬玄謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42ef80e7-3c26-461a-be31-6c2b04720d57', '永淳中童謠', '永淳中童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["新禾不入箱，新麥不入場。","迨及八九月，狗吠空垣墻。"]', '["新禾不入箱，新麦不入場。","迨及八九月，狗吠空垣墻。"]', '诗', 'shi', '', NULL, '永淳中童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a76a80c-f122-496b-ad02-3c9964f781c9', '楊柳謠', '楊柳謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["楊柳楊柳漫頭駝。"]', '["楊柳楊柳漫头駝。"]', '诗', 'shi', '', NULL, '楊柳謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ee1f245-912c-4b8c-8b06-9cba054eb19e', '裴炎謠', '裴炎謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一片火，兩片火，緋衣小兒當殿坐。"]', '["一片火，兩片火，緋衣小兒當殿坐。"]', '诗', 'shi', '', NULL, '裴炎謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10afb855-7015-471c-bd52-289e43c6c299', '武后長壽元年民間謠', '武后长壽元年民间謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["補闕連車載，拾遺平斗量。","欔槌侍御史，盌脫侍中郎。"]', '["補闕連车載，拾遺平斗量。","欔槌侍御史，盌脫侍中郎。"]', '诗', 'shi', '', NULL, '武后長壽元年民間謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d09e3b2-d257-4db4-800d-d4a94abd8cc5', '續謠', '續謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["評事不讀律，博士不尋章。","糊心宣撫使，眯目聖神皇。"]', '["評事不读律，博士不尋章。","糊心宣撫使，眯目聖神皇。"]', '诗', 'shi', '', NULL, '續謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58215d2f-9547-4984-88dd-7013ad00332e', '天樞謠', '天樞謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一條麻索挽，天樞絕去也。"]', '["一條麻索挽，天樞絕去也。"]', '诗', 'shi', '', NULL, '天樞謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e926848-8f42-4ab9-8a8b-f55ff5e05e47', '武后時謠', '武后时謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["張公喫酒李公醉。"]', '["張公喫酒李公醉。"]', '诗', 'shi', '', NULL, '武后時謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('161e871c-dafc-4e4f-bd6c-15303cdcba89', '武后時童謠', '武后时童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["紅綠複帬長，千里萬里猶香。"]', '["紅綠複帬长，千里万里猶香。"]', '诗', 'shi', '', NULL, '武后時童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('026d5b8e-5c52-4e0c-a553-3e9618dd716e', '神龍後烏鵲窠謠', '神龙後烏鵲窠謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["山南烏鵲窠，山北金駱駝。","鐮柯不鑿孔，斧子不施柯。"]', '["山南烏鵲窠，山北金駱駝。","鐮柯不鑿孔，斧子不施柯。"]', '诗', 'shi', '', NULL, '神龍後烏鵲窠謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44e1698d-9e3b-42dc-9ffd-e5b0853b6f30', '吏部謠', '吏部謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["岑愔獠子後，崔湜令公孫。","三人相比校，莫賀咄骨渾。"]', '["岑愔獠子後，崔湜令公孫。","三人相比校，莫賀咄骨渾。"]', '诗', 'shi', '', NULL, '吏部謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9213b554-a775-429b-9ca3-289e95d2ab62', '黃犢子謠', '黄犢子謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["黃㹀犢子挽紖斷，兩脚蹋地鞋𪎱斷。"]', '["黄㹀犢子挽紖斷，兩脚蹋地鞋𪎱斷。"]', '诗', 'shi', '', NULL, '黃犢子謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc810e38-8590-409c-8b2d-4c8af53b1fd5', '安樂寺童謠', '安乐寺童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["可憐安樂寺，了了樹頭懸。"]', '["可怜安乐寺，了了樹头懸。"]', '诗', 'shi', '', NULL, '安樂寺童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f63881b7-6544-4c2c-8d01-002c34918198', '鯉魚兒謠', '鯉鱼兒謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["可憐聖善寺，身著綠毛衣。","牽來河裏飲，蹋殺鯉魚兒。"]', '["可怜聖善寺，身著綠毛衣。","牽来河裏饮，蹋殺鯉鱼兒。"]', '诗', 'shi', '', NULL, '鯉魚兒謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3501b19-3cc1-4b66-9749-6ad14fe60c09', '羊頭山謠', '羊头山謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["羊頭山北作朝堂。"]', '["羊头山北作朝堂。"]', '诗', 'shi', '', NULL, '羊頭山謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60455b99-3c3d-43c4-9e9d-b57291c2dff8', '金橋童謠', '金橋童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["聖人執節度金橋。"]', '["聖人執節度金橋。"]', '诗', 'shi', '', NULL, '金橋童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa9def3d-411e-4b34-b4ca-04bad05b5487', '天寶中京兆謠', '天寶中京兆謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["欲得米麥賤，無過追李峴。"]', '["欲得米麦賤，無過追李峴。"]', '诗', 'shi', '', NULL, '天寶中京兆謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9cf5628-45e7-4aba-9898-4695e13c2677', '天寶初語', '天寶初語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["義髻拋河裏，黃帬逐水流。"]', '["義髻拋河裏，黄帬逐水流。"]', '诗', 'shi', '', NULL, '天寶初語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('128a1e2e-2a28-49b5-8f08-55094eb434f4', '楊氏謠', '楊氏謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["男不封侯女作妃，君看女却是門楣。"]', '["男不封侯女作妃，君看女却是门楣。"]', '诗', 'shi', '', NULL, '楊氏謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('514e610e-47d5-47f8-8f24-9daeb0fbe722', '神雞童謠', '神雞童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["生兒不用識文字，鬬雞走馬勝讀書。","賈家小兒年十三，富貴榮華代不如。","能令金距期勝負，白羅繡衫隨軟輿。","父死長安千里外，差夫治道輓喪車。"]', '["生兒不用識文字，鬬雞走马勝读书。","賈家小兒年十三，富貴榮华代不如。","能令金距期勝負，白羅繡衫隨軟輿。","父死长安千里外，差夫治道輓喪车。"]', '诗', 'shi', '', NULL, '神雞童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b34e566-0728-4c54-81e8-3e270b97fdb9', '燕燕謠', '燕燕謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["燕燕，飛上天。","天上女兒鋪白氈，氈上有千錢。"]', '["燕燕，飞上天。","天上女兒鋪白氈，氈上有千錢。"]', '诗', 'shi', '', NULL, '燕燕謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bde4e646-c6a3-4cd3-9b21-b1fee5c5e5ed', '幽州謠', '幽州謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["舊來誇戴竿，今日不堪看。","但看五月裏，清水河邊見契丹。"]', '["旧来誇戴竿，今日不堪看。","但看五月裏，清水河邊见契丹。"]', '诗', 'shi', '', NULL, '幽州謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('849628ae-b27c-443f-9f2e-eb708ae6efc9', '兩京童謠', '兩京童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["不怕上蘭單，惟愁荅辨難。","無錢求案典，生死任都官。"]', '["不怕上蘭單，惟愁荅辨难。","無錢求案典，生死任都官。"]', '诗', 'shi', '', NULL, '兩京童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('469f841c-b819-41ff-8f80-98de73f4210d', '兩頭朱童謠', '兩头朱童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一隻箸，兩頭朱。","五六月化爲膽。"]', '["一隻箸，兩头朱。","五六月化爲膽。"]', '诗', 'shi', '', NULL, '兩頭朱童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee4a2b9e-61b2-4dff-bf95-c320a0f14be0', '打麥謠', '打麦謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["打麥，麥打。","三三三，舞了也。"]', '["打麦，麦打。","三三三，舞了也。"]', '诗', 'shi', '', NULL, '打麥謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6b5f9d4-c5ab-46c4-948e-2bc0042fadcf', '張權輿作裴度僞謠', '張權輿作裴度僞謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["非衣小兒坦其腹，天上有口被驅逐。"]', '["非衣小兒坦其腹，天上有口被驱逐。"]', '诗', 'shi', '', NULL, '張權輿作裴度僞謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0a73740-21ed-4ab7-9a81-e9fcbe4148c4', '馬僕射謠', '马僕射謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["齋鐘動也，和尚不上堂。"]', '["斋鐘动也，和尚不上堂。"]', '诗', 'shi', '', NULL, '馬僕射謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34e78a8f-127b-479d-be10-dd2686ca4102', '咸通七年童謠', '咸通七年童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["草青青，被嚴霜。","鵲始巢，復看顛狂。"]', '["草青青，被嚴霜。","鵲始巢，复看顛狂。"]', '诗', 'shi', '', NULL, '咸通七年童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a90f3601-e311-464d-b8e1-116eb8992b01', '咸通十四年成都謠', '咸通十四年成都謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["咸通癸巳，出無所之。","蛇去馬來，道路稍開。","頭無片瓦，地有殘灰。"]', '["咸通癸巳，出無所之。","蛇去马来，道路稍开。","头無片瓦，地有殘灰。"]', '诗', 'shi', '', NULL, '咸通十四年成都謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55464509-5421-4c86-a20a-b68de961689a', '乾符六年童謠', '乾符六年童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["八月無霜塞草青，將軍騎馬出空城。","漢家天子西巡狩，猶向江東更索兵。"]', '["八月無霜塞草青，將軍騎马出空城。","漢家天子西巡狩，猶向江东更索兵。"]', '诗', 'shi', '', NULL, '乾符六年童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('915f5724-d735-4ea0-af5b-88021ae9ddcb', '僖宗時童謠', '僖宗时童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["金色蝦蟆爭努眼，飜却曹州天下反。"]', '["金色蝦蟆爭努眼，飜却曹州天下反。"]', '诗', 'shi', '', NULL, '僖宗時童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35ebef13-863b-4262-b95d-23949f8b4c1a', '黃巢軍中謠', '黄巢軍中謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["逢儒則肉師必覆。"]', '["逢儒則肉師必覆。"]', '诗', 'shi', '', NULL, '黃巢軍中謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00378596-0b01-448f-bb44-617317621bfe', '中和初童謠', '中和初童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["黃巢走，泰山東，死在翁家翁。"]', '["黄巢走，泰山东，死在翁家翁。"]', '诗', 'shi', '', NULL, '中和初童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb20c814-cd74-46b1-a0d9-edddc98b61f6', '山陰老人僞謠', '山陰老人僞謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["欲識聖人姓，千里草青青。","欲識聖人名，日從日上生。"]', '["欲識聖人姓，千里草青青。","欲識聖人名，日從日上生。"]', '诗', 'shi', '', NULL, '山陰老人僞謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6b6b8da-4c42-4fce-a1b4-95b529b03017', '胡楚賓謠', '胡楚賓謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["胡楚賓，李翰林。","詞同三峽水，字值雙南金。"]', '["胡楚賓，李翰林。","词同三峽水，字值雙南金。"]', '诗', 'shi', '', NULL, '胡楚賓謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('873a3c6b-22af-4e99-824d-1979b11ffc39', '後唐軍士謠', '後唐軍士謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["除去菩薩，扶立生鐵。"]', '["除去菩薩，扶立生鐵。"]', '诗', 'shi', '', NULL, '後唐軍士謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b353f2e0-2491-4b9b-996c-a358bf943314', '周顯德中齊州謠', '周显德中齊州謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["蹋陽春人間二月雨和塵陽春蹋盡西風起腸斷人間白髮人。"]', '["蹋陽春人间二月雨和塵陽春蹋尽西风起腸斷人间白髮人。"]', '诗', 'shi', '', NULL, '周顯德中齊州謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a9647c5-326a-422f-b6d4-2917f1ccb5c3', '天祐中江南童謠', '天祐中江南童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["東海鯉魚飛上天。"]', '["东海鯉鱼飞上天。"]', '诗', 'shi', '', NULL, '天祐中江南童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f41cf2e-4385-4bee-a597-d9cad48fd8fe', '真人謠', '真人謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["有一真人在冀川，開口持弓向外邊。"]', '["有一真人在冀川，开口持弓向外邊。"]', '诗', 'shi', '', NULL, '真人謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efa21cb4-174f-48e7-a34f-2bd18e891014', '李後主童謠', '李後主童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["索得娘來忘却家，後院桃李不生花。","豬兒狗兒都死盡，養得貓兒患赤瘕。"]', '["索得娘来忘却家，後院桃李不生花。","豬兒狗兒都死尽，養得貓兒患赤瘕。"]', '诗', 'shi', '', NULL, '李後主童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2efd5b78-acbd-4276-8e52-e0b6e76a3913', '秦人竹𧳽謠', '秦人竹𧳽謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["𧳽𧳽引黑牛，天差不自由。","但看戊寅歲，揚在蜀江頭。"]', '["𧳽𧳽引黑牛，天差不自由。","但看戊寅歲，揚在蜀江头。"]', '诗', 'shi', '', NULL, '秦人竹𧳽謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cd6f117-b3ea-47bd-9271-72865430132d', '蜀人謠', '蜀人謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["黑牛無繫絆，椶繩一時斷。"]', '["黑牛無繫絆，椶繩一时斷。"]', '诗', 'shi', '', NULL, '蜀人謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('145afe51-db75-4bca-8cf7-02614dba6928', '秦城芭蕉謠', '秦城芭蕉謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["花開來裏，花謝也裏。"]', '["花开来裏，花謝也裏。"]', '诗', 'shi', '', NULL, '秦城芭蕉謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bd78e39-2ddb-4662-94c0-c44e5d993262', '蜀童謠', '蜀童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["我有一帖藥，其名曰阿魏，賣與十八子。"]', '["我有一帖藥，其名曰阿魏，賣與十八子。"]', '诗', 'shi', '', NULL, '蜀童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('353a0192-8021-449e-b850-a620e610c976', '蜀中埽地和尚', '蜀中埽地和尚', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["水行仙，怕秦川。"]', '["水行仙，怕秦川。"]', '诗', 'shi', '', NULL, '蜀中埽地和尚 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8092ce74-08c2-4e43-ac47-6e2b48e48a21', '福州謠', '福州謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["騎馬來，騎馬去。"]', '["騎马来，騎马去。"]', '诗', 'shi', '', NULL, '福州謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('818ee701-07ff-4f87-a0b5-ca091ba2d2e3', '閩人謠', '閩人謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["風吹楊菜鼓山下，不得錢郎戈不罷。"]', '["风吹楊菜鼓山下，不得錢郎戈不罷。"]', '诗', 'shi', '', NULL, '閩人謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5f9fb4a-d411-4cee-97e1-217b801f5cd7', '廣州童謠', '廣州童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["羊頭二四，白天雨至。"]', '["羊头二四，白天雨至。"]', '诗', 'shi', '', NULL, '廣州童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('361e9a26-310e-4a2b-8811-bffc17db2e78', '桂管童謠', '桂管童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["大蟲來。"]', '["大蟲来。"]', '诗', 'shi', '', NULL, '桂管童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c20cad4-ec9f-449a-9709-d5457ef9d5be', '湖南童謠', '湖南童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["湖南城郭好長街，竟栽柳樹不栽槐。","百姓奔竄無一事，只是椎芒織草鞋。"]', '["湖南城郭好长街，竟栽柳樹不栽槐。","百姓奔竄無一事，只是椎芒织草鞋。"]', '诗', 'shi', '', NULL, '湖南童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b80fdfc6-2e5b-47aa-a92a-1ae6e0dda90a', '長沙童謠', '长沙童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鞭打馬，馬急走。"]', '["鞭打马，马急走。"]', '诗', 'shi', '', NULL, '長沙童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1a65716-e432-479b-bcd1-a2cfb049d355', '湘中童謠', '湘中童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["馬去不用鞭，齩牙過今年。"]', '["马去不用鞭，齩牙過今年。"]', '诗', 'shi', '', NULL, '湘中童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f470388-108b-4cbe-8fb5-fd2df3f7eeca', '長沙童謠', '长沙童謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["三羊五馬，馬子離羣，羊子無舍。"]', '["三羊五马，马子離羣，羊子無舍。"]', '诗', 'shi', '', NULL, '長沙童謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf85ba38-42a2-48f6-888b-4920fb654d69', '丹陽語', '丹陽語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["待錢來，待錢來。"]', '["待錢来，待錢来。"]', '诗', 'shi', '', NULL, '丹陽語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('094bf051-81c7-48f3-8ebe-913fa8549021', '遼述律后謠', '遼述律后謠', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["青牛嫗，曾避路。"]', '["青牛嫗，曾避路。"]', '诗', 'shi', '', NULL, '遼述律后謠 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e25df57-0186-4560-9d2a-7e16fe055bb2', '招手令', '招手令', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["亞其虎膺，曲其松根。","以蹲鴟間虎膺之下，以鉤戟差玉柱之旁。","潛虯闊玉柱三分，奇兵闊潛虯一寸。","死其三洛，生其五峰。"]', '["亞其虎膺，曲其松根。","以蹲鴟间虎膺之下，以鉤戟差玉柱之旁。","潛虯闊玉柱三分，奇兵闊潛虯一寸。","死其三洛，生其五峰。"]', '诗', 'shi', '', NULL, '招手令 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe0aeb69-f0e0-4ec8-bc11-21a8fc648d4b', '打令口號', '打令口號', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["送搖招，由三方。","一圓分成四片，送在搖前。"]', '["送搖招，由三方。","一圓分成四片，送在搖前。"]', '诗', 'shi', '', NULL, '打令口號 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8af70fac-0912-45c6-af8d-b5b324deb13f', '龍朔中酒令', '龙朔中酒令', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["子母相去離，連臺拗倒。"]', '["子母相去離，連台拗倒。"]', '诗', 'shi', '', NULL, '龍朔中酒令 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24182fad-ba90-4183-93e5-a5b53cdcdaa3', '沈亞之 一', '沈亞之 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["伐木丁丁，鳥鳴嚶嚶。","東行西行，遇飯遇羹。"]', '["伐木丁丁，鸟鳴嚶嚶。","东行西行，遇飯遇羹。"]', '诗', 'shi', '', NULL, '沈亞之 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e491648-57a3-48b4-8371-9c573781e72d', '沈亞之 二', '沈亞之 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["如切如磋，如琢如磨。","欺客打婦，不當婁羅。"]', '["如切如磋，如琢如磨。","欺客打婦，不當婁羅。"]', '诗', 'shi', '', NULL, '沈亞之 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('141bffaa-5ba6-4f70-b6a8-4c679fd8b312', '令狐楚顧非熊 一', '令狐楚顧非熊 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["水裏取一鼉，岸上取一駝。","將者駝，來馱者鼉，是爲駝馱鼉。"]', '["水裏取一鼉，岸上取一駝。","將者駝，来馱者鼉，是爲駝馱鼉。"]', '诗', 'shi', '', NULL, '令狐楚顧非熊 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ed302b4-3908-44a0-9212-3b4fd48b7667', '令狐楚顧非熊 二', '令狐楚顧非熊 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["屋裏取一鴿，水裏取一蛤。","將者鴿，來合者蛤，是謂鴿合蛤。"]', '["屋裏取一鴿，水裏取一蛤。","將者鴿，来合者蛤，是謂鴿合蛤。"]', '诗', 'shi', '', NULL, '令狐楚顧非熊 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c64133dc-ef68-4f28-bf23-6b05d1f18178', '張祜 一', '張祜 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["上水船，風大急。","帆下人，須好立。"]', '["上水船，风大急。","帆下人，須好立。"]', '诗', 'shi', '', NULL, '張祜 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b7a21f5-78d4-4a8d-b32c-eca826899630', '張祜 二', '張祜 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["上水船，船底破。","好看客，莫倚柁。"]', '["上水船，船底破。","好看客，莫倚柁。"]', '诗', 'shi', '', NULL, '張祜 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33f6e3be-fb21-4b46-978e-7bd7c747c6b0', '盧發 一', '盧發 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["十姓胡中第六胡，也曾金闕掌洪爐。","少年從事誇門第，莫向尊前氣色粗。"]', '["十姓胡中第六胡，也曾金闕掌洪爐。","少年從事誇门第，莫向尊前氣色粗。"]', '诗', 'shi', '', NULL, '盧發 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9cb0793-b1ff-46ad-93d7-1b9dd773e34f', '盧發 二', '盧發 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["十姓胡中第六胡，文章官職勝崔盧。","暫來關外分優寄，不稱賓筵語氣粗。"]', '["十姓胡中第六胡，文章官職勝崔盧。","暫来关外分優寄，不稱賓筵語氣粗。"]', '诗', 'shi', '', NULL, '盧發 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1feb9df0-dd58-498e-8435-1b359c03d0ac', '沈詢', '沈詢', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["莫打南來雁，從他向北飛。","打時雙打取，莫遣兩分離。"]', '["莫打南来雁，從他向北飞。","打时雙打取，莫遣兩分離。"]', '诗', 'shi', '', NULL, '沈詢 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3950e45c-662f-4d74-a549-55dad9a461be', '姚巖傑', '姚巖傑', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["遙望漁舟，不闊尺八。","憑闌一嘔，已覺空喉。"]', '["遙望漁舟，不闊尺八。","憑闌一嘔，已覺空喉。"]', '诗', 'shi', '', NULL, '姚巖傑 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2b8a61a-e0d5-4fc0-9f3e-afedd4eadf2f', '裴勛父子 一', '裴勛父子 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["矬人饒舌，破車饒楔。"]', '["矬人饒舌，破车饒楔。"]', '诗', 'shi', '', NULL, '裴勛父子 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c26d2b26-01a4-46be-ad7b-3f7a7f61507c', '裴勛父子 二', '裴勛父子 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["蝙蝠不自見，笑他梁上燕。"]', '["蝙蝠不自见，笑他梁上燕。"]', '诗', 'shi', '', NULL, '裴勛父子 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('719ba26e-722f-4fae-b04e-69848753003c', '方干李主簿改令 一', '方干李主簿改令 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["措大喫酒點鹽，將軍喫酒點醬。","只見門外著籬，未見眼中安鄣。"]', '["措大喫酒点鹽，將軍喫酒点醬。","只见门外著籬，未见眼中安鄣。"]', '诗', 'shi', '', NULL, '方干李主簿改令 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea6769d4-ddea-47e1-9103-b1d6c36964e3', '方干李主簿改令 二', '方干李主簿改令 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["措大喫酒點鹽，下人喫酒點鮓。","只見半臂著籬，不見口脣開袴。"]', '["措大喫酒点鹽，下人喫酒点鮓。","只见半臂著籬，不见口脣开袴。"]', '诗', 'shi', '', NULL, '方干李主簿改令 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82ba3726-9960-42c7-86cf-348a2d5e9074', '高駢薛濤 一', '高駢薛濤 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["口，有似沒量斗。"]', '["口，有似沒量斗。"]', '诗', 'shi', '', NULL, '高駢薛濤 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6645b8e8-52d0-40e6-957f-f44e2423f2aa', '高駢薛濤 二', '高駢薛濤 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["川，有似三條椽。"]', '["川，有似三條椽。"]', '诗', 'shi', '', NULL, '高駢薛濤 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('054372a0-9f20-42c5-b437-2bcf3156c4af', '南唐烈祖酒令 一', '南唐烈祖酒令 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["雪下紛紛，便是白起。"]', '["雪下紛紛，便是白起。"]', '诗', 'shi', '', NULL, '南唐烈祖酒令 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9af5df27-b1ea-473e-839c-a2339e7e5d13', '南唐烈祖酒令 二', '南唐烈祖酒令 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["著履過街，必須雍齒。"]', '["著履過街，必須雍齒。"]', '诗', 'shi', '', NULL, '南唐烈祖酒令 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00e07304-b538-47ee-a712-289f8b46cc20', '南唐烈祖酒令 三', '南唐烈祖酒令 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["明朝日出，爭奈蕭何。"]', '["明朝日出，爭奈蕭何。"]', '诗', 'shi', '', NULL, '南唐烈祖酒令 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c6b1ee3-e524-4524-8672-d731455fad6f', '吳越王與陶穀酒令 一', '吳越王與陶穀酒令 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["白玉石，碧波亭上迎仙客。"]', '["白玉石，碧波亭上迎仙客。"]', '诗', 'shi', '', NULL, '吳越王與陶穀酒令 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('338e10da-29de-4317-93bc-f9b171c4caea', '吳越王與陶穀酒令 二', '吳越王與陶穀酒令 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["口耳王，聖明天子要錢塘。"]', '["口耳王，聖明天子要錢塘。"]', '诗', 'shi', '', NULL, '吳越王與陶穀酒令 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b419a9e-df23-4630-ab04-33d0cd86fda0', '夷陵女郎鬼', '夷陵女郎鬼', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鸞老頭腦好，好頭腦鸞老。"]', '["鸾老头腦好，好头腦鸾老。"]', '诗', 'shi', '', NULL, '夷陵女郎鬼 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77f4df8b-b5f4-4444-8abf-15962afab155', '城陽公主卜繇', '城陽公主卜繇', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["二火皆食，始同榮，末同戚。"]', '["二火皆食，始同榮，末同戚。"]', '诗', 'shi', '', NULL, '城陽公主卜繇 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e56a6837-eb22-4223-9e71-080e1040e600', '馮存澄爲明皇占', '馮存澄爲明皇占', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["合同斬關，鑄印乘軒。","始當果斷，終得嗣天。"]', '["合同斬关，鑄印乘軒。","始當果斷，終得嗣天。"]', '诗', 'shi', '', NULL, '馮存澄爲明皇占 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97cc9343-5904-468d-8c56-a8b98fa61951', '錢知微卜賣天津橋', '錢知微卜賣天津橋', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["兩頭點土，中心虛懸。","人足踏跋，不肯下錢。"]', '["兩头点土，中心虛懸。","人足踏跋，不肯下錢。"]', '诗', 'shi', '', NULL, '錢知微卜賣天津橋 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfafa85b-4cca-4be0-ab51-04fe0351f54d', '王山人爲李衛公按冥', '王山人爲李衛公按冥', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["位極人臣，壽六十四。"]', '["位極人臣，壽六十四。"]', '诗', 'shi', '', NULL, '王山人爲李衛公按冥 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f480a1b-9d88-4b56-b642-2d423fd0b3e4', '鍾傳客占曆日包橘', '鍾傳客占曆日包橘', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["太歲當頭坐，諸神不敢當。","其中有一物，常帶洞庭香。"]', '["太歲當头坐，諸神不敢當。","其中有一物，常带洞庭香。"]', '诗', 'shi', '', NULL, '鍾傳客占曆日包橘 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a86f389e-aa12-4b6f-8326-c764def57e8f', '馬重績占隨卦繇辭', '马重績占隨卦繇辞', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["南瞻析木，木不自續。","虛而動之，動隨其覆。"]', '["南瞻析木，木不自續。","虛而动之，动隨其覆。"]', '诗', 'shi', '', NULL, '馬重績占隨卦繇辭 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45fdd678-6fcf-4f46-b5f1-3285011bef8d', '方龜精爲錢元懿卜詞', '方龟精爲錢元懿卜词', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["太乙接天河，金華寶貝多。","郡侯六十六，別處不經過。"]', '["太乙接天河，金华寶貝多。","郡侯六十六，別处不經過。"]', '诗', 'shi', '', NULL, '方龜精爲錢元懿卜詞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbb3cd72-d3e2-41f7-8337-32447ef3fc34', '葉簡占失牛', '葉簡占失牛', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["占失牛，已被家邊載上州。","欲知賊姓一斤求，欲知賊名十干頭。"]', '["占失牛，已被家邊載上州。","欲知賊姓一斤求，欲知賊名十干头。"]', '诗', 'shi', '', NULL, '葉簡占失牛 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2850de73-cd41-47b4-a5af-699ec8862c26', '又射覆橘子', '又射覆橘子', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["圓似珠，色如丹。","儻能擘破同分喫，爭不慙媿洞庭山。"]', '["圓似珠，色如丹。","儻能擘破同分喫，爭不慙媿洞庭山。"]', '诗', 'shi', '', NULL, '又射覆橘子 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ea50bdb-5aa9-46a1-b1cd-808496a92fa1', '射覆巾子', '射覆巾子', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["近來好裹束，各自競尖新。","秤無三五兩，因何號一斤。"]', '["近来好裹束，各自競尖新。","秤無三五兩，因何號一斤。"]', '诗', 'shi', '', NULL, '射覆巾子 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeffbc2c-5b22-49c8-9685-bee2177ca516', '射覆二雞子', '射覆二雞子', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["此物不難知，一雄兼一雌。","誰將打破看，方明混沌時。"]', '["此物不难知，一雄兼一雌。","誰將打破看，方明混沌时。"]', '诗', 'shi', '', NULL, '射覆二雞子 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab67b350-f74a-40e6-bd7f-332e04ce1bbb', '天衝星占', '天衝星占', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["天衝抱極泣帝前，血濁霧下天下冤。"]', '["天衝抱極泣帝前，血濁霧下天下冤。"]', '诗', 'shi', '', NULL, '天衝星占 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bb7f041-7d79-464d-9dfa-ba76699c4b79', '占月語', '占月語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["月如彎弓，少雨多風。","月如仰瓦，不求自下。"]', '["月如彎弓，少雨多风。","月如仰瓦，不求自下。"]', '诗', 'shi', '', NULL, '占月語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('feefdf82-bc7e-4133-95b2-2e00528bf483', '占雨 一', '占雨 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["乾星照溼土，明日依舊雨。"]', '["乾星照溼土，明日依旧雨。"]', '诗', 'shi', '', NULL, '占雨 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b5bea73-b730-45e1-9df3-6e242fd3d2b6', '占雨 二', '占雨 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["雲行西，星照泥。"]', '["云行西，星照泥。"]', '诗', 'shi', '', NULL, '占雨 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0db4d9c5-b2e0-4af0-a719-7868b5f1de07', '占雨 三', '占雨 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["朝霞不出門，暮霞行千里。"]', '["朝霞不出门，暮霞行千里。"]', '诗', 'shi', '', NULL, '占雨 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88034b80-42bc-4a54-992e-69f308e138a5', '占雨 四', '占雨 四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["天將雨，鳩逐婦。"]', '["天將雨，鳩逐婦。"]', '诗', 'shi', '', NULL, '占雨 四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a605fe4-6622-42c1-9726-4eafde7a4880', '占四時甲子雨', '占四时甲子雨', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["春雨甲子，赤地千里。","夏雨甲子，乘船入市。","秋雨甲子，禾頭生耳。","冬雨甲子，牛羊凍死。","鵲巢下地，其年大水。"]', '["春雨甲子，赤地千里。","夏雨甲子，乘船入市。","秋雨甲子，禾头生耳。","冬雨甲子，牛羊凍死。","鵲巢下地，其年大水。"]', '诗', 'shi', '', NULL, '占四時甲子雨 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb02add6-9d4d-4bf6-8a7f-cc2f9fb8498f', '占年 一', '占年 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["要見麥，見三白。"]', '["要见麦，见三白。"]', '诗', 'shi', '', NULL, '占年 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4095cac5-b133-46bf-8b0a-8b3e1773aa7b', '占年 二', '占年 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["正月三白，田公笑赫赫。"]', '["正月三白，田公笑赫赫。"]', '诗', 'shi', '', NULL, '占年 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('434e0cf7-dc7d-49c8-bbd1-a1a59a461436', '樹稼諺', '樹稼諺', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["樹稼，達官怕。"]', '["樹稼，達官怕。"]', '诗', 'shi', '', NULL, '樹稼諺 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2559017-abc2-4518-9d07-356c0629d03e', '相書語', '相书語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["目有四白，五夫守宅。"]', '["目有四白，五夫守宅。"]', '诗', 'shi', '', NULL, '相書語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c7c2d90-028a-42bb-b073-e5d7f041dc86', '葬書語 一', '葬书語 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["葬壓龍角，其棺必斲。"]', '["葬壓龙角，其棺必斲。"]', '诗', 'shi', '', NULL, '葬書語 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50cfb8f4-ec53-42c0-adf7-43d903d36951', '葬書語 二', '葬书語 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["朱雀和鳴，子孫盛榮。"]', '["朱雀和鳴，子孫盛榮。"]', '诗', 'shi', '', NULL, '葬書語 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bcf8b1b-926c-44d5-9263-ede855349932', '葬書語 三', '葬书語 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["朱雀悲哀，棺中見灰。"]', '["朱雀悲哀，棺中见灰。"]', '诗', 'shi', '', NULL, '葬書語 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8ea55ea-5039-4860-8601-8fa310a954d6', '葬書語 四', '葬书語 四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["安龍頭，枕龍角。","不三年，自消鑠。"]', '["安龙头，枕龙角。","不三年，自消鑠。"]', '诗', 'shi', '', NULL, '葬書語 四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aade48b-4bbc-47b0-9dc0-d12f728e68f3', '葬書語 五', '葬书語 五', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["安龍頭，枕龍耳。","不三年，萬乘至。"]', '["安龙头，枕龙耳。","不三年，万乘至。"]', '诗', 'shi', '', NULL, '葬書語 五 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f89c9ab-8012-4e13-adac-82ef9b948047', '陰陽書語', '陰陽书語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["喬木先枯，衆子必孤。"]', '["喬木先枯，衆子必孤。"]', '诗', 'shi', '', NULL, '陰陽書語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd6fb19e-48f4-4fb4-9792-c000cf019bcf', '本草采萍時日歌', '本草采萍时日歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["不在山，不在岸，采我之時七月半。","選甚癱風與緩風，些小微風都不算。","豆淋酒內下三丸，鐵幞頭上也出汗。"]', '["不在山，不在岸，采我之时七月半。","選甚癱风與緩风，些小微风都不算。","豆淋酒內下三丸，鐵幞头上也出汗。"]', '诗', 'shi', '', NULL, '本草采萍時日歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfaf74b9-357e-46f3-87bf-37d4e6898606', '和劑方補骨脂丸方詩', '和劑方補骨脂丸方诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["三年時節向邊隅，人信方知藥力殊。","奪得春光來在手，青娥休笑白髭鬚。"]', '["三年时節向邊隅，人信方知藥力殊。","奪得春光来在手，青娥休笑白髭鬚。"]', '诗', 'shi', '', NULL, '和劑方補骨脂丸方詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e0061bb-87a7-4efe-8bfa-953dc663d6c4', '李廷珪藏墨訣', '李廷珪藏墨訣', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["贈爾烏玉玦，泉清硏須潔。","避暑懸葛囊，臨風度梅月。"]', '["贈爾烏玉玦，泉清硏須潔。","避暑懸葛囊，臨风度梅月。"]', '诗', 'shi', '', NULL, '李廷珪藏墨訣 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8a6a251-3d49-494b-8fca-f903e14da232', '蒙求', '蒙求', 'ea6cb42e-ef38-44a5-a2eb-c591032fdd6c', '唐', '["王戎簡要，裴楷清通。","孔明臥龍，呂望非熊。","楊震關西，丁寬易東。","謝安高潔，王導公忠。","匡衡鑿壁，孫敬閉戶。","郅都蒼鷹，寧成乳虎。","周嵩狼抗，梁冀跋扈。","郗超䫇參，王珣短簿。","伏波標柱，博望尋河。","李陵初詩，田橫感歌。","武仲不休，士衡患多。","桓譚非讖，王商止訛。","嵇呂命駕，程孔傾蓋。","劇孟一敵，周處三害。","胡廣補闕，袁安倚賴。","黃霸政殊，梁習治最。","墨子悲絲，楊朱泣岐。","朱博烏集，蕭芝雉隨。","杜后生齒，靈王出髭。","賈誼忌鵩，莊周畏犧。","燕昭築臺，鄭莊置驛。","瓘靖二妙，岳湛連璧。","郄詵一枝，戴馮重席。","鄒陽長裾，王符逢掖。","鳴鶴日下，士龍雲間。","晉宣狼顧，漢祖龍顏。","鮑靚記井，羊祜識環。","仲容青雲，叔夜玉山。","毛義捧檄，子路負米。","江革忠孝，王覽友弟。","蕭何定律，叔孫制禮。","葛豐刺舉，息躬歷詆。","管寧割席，和嶠專車。","時苗留犢，羊續懸魚。","樊噲排闥，辛毘引裾。","孫楚漱石，郝隆曬書。","枚臯詣闕，充國自贊。","王衍風鑑，許劭月旦。","賀循儒宗，孫綽才冠。","太叔辨洽，摯仲辭翰。","山濤識量，毛玠公方。","袁盎却座，衛瓘撫牀。","于公高門，曹參趣裝。","庶女振風，鄒衍降霜。","范丹生塵，晏嬰脫粟。","詰汾興魏，鼈靈王蜀。","不疑誣金，卞和泣玉。","檀卿沐猴，謝尚鴝鵒。","泰初日月，季野陽秋。","荀陳德星，李郭仙舟。","王忳繡被，張氏銅鉤。","丁公遽戮，雍齒先侯。","陳雷膠漆，范張雞黍。","周侯山嶷，會稽霞舉。","季布一諾，阮瞻三語。","郭文游山，袁宏泊渚。","黃琬對日，秦宓論天。","孟軻養素，揚雄草玄。","向秀聞笛，伯牙絕弦。","郭槐自屈，南郡猶憐。","魯恭馴雉，宋均去獸。","廣客蛇影，殷師牛鬬。","元禮模楷，季彥領袖。","魯褒錢神，崔烈銅臭。","梁竦廟食，趙溫雄飛。","枚乘蒲輪，鄭均白衣。","陵母伏劒，軻親斷機。","齊后破環，謝女解圍。","鑿齒尺牘，荀勗音律。","胡威推縑，陸績懷橘。","羅含吞鳥，江淹夢筆。","李廞清貞，劉驎高率。","蔣詡三徑，許由一瓢。","楊僕移關，杜預建橋。","壽王議鼎，杜林駮堯。","西施捧心，孫壽折腰。","靈輒扶輪，魏顆結草。","逸少傾寫，平子絕倒。","澹臺毀璧，子罕辭寶。","東平爲善，司馬稱好。","公超霧市，魯般雲梯。","田單火牛，江逌爇雞。","蔡裔殞盜，張遼止啼。","陳平多轍，李廣成蹊。","陳遵投轄，山簡倒載。","淵客泣珠，交甫解佩。","龔勝不屈，孫寶自劾。","呂安題鳳，子猷訪戴。","董宣彊項，翟璜直言。","紀昌貫蝨，養由號猨。","馮衍歸里，張昭塞門。","蘇韶鬼靈，盧充幽婚。","震畏四知，秉去三惑。","柳下直道，叔敖陰德。","張湯巧詆，杜周深刻。","三王尹京，二鮑糾慝。","孫康映雪，車胤聚螢。","李充四部，井春五經。","谷永筆札，顧愷丹青。","戴逵破琴，謝敷應星。","阮宣杖頭，畢卓甕下。","文伯羞鼈，孟宗寄鮓。","史丹青蒲，張湛白馬。","隱之感鄰，王修輟社。","阮放八雋，江臮四凶。","華歆忤旨，陳羣蹙容。","王濬懸刀，丁固生松。","姜維膽斗，盧植音鐘。","桓溫奇骨，鄧艾大志。","楊修捷對，羅友默記。","杜康造酒，蒼頡制字。","樗里智囊，邊韶經笥。","滕公佳城，王果石崖。","買妻恥醮，澤室犯齋。","馬后大練，孟光荆釵。","顏叔秉燭，宋弘不諧。","鄧通銅山，郭況金穴。","秦彭攀轅，侯霸臥轍。","淳于炙輠，彥國吐屑。","太真玉臺，武子金埓。","巫馬戴星，宓賤彈琴。","郝廉留錢，雷義送金。","逢萌挂冠，胡昭投簪。","王喬雙鳧，華佗五禽。","程邈隸書，史籀大篆。","王承魚盜，丙吉牛喘。","賈琮褰帷，郭賀露冕。","馮媛當熊，班女辭輦。","王充閱市，董生下帷。","平叔傅粉，弘治凝脂。","楊生黃雀，毛子白龜。","宿瘤采桑，漆室憂葵。","韋賢滿籯，夏侯拾芥。","阮簡曠達，袁耽俊邁。","蘇武持節，鄭衆不拜。","郭巨將坑，董永自賣。","仲連蹈海，范蠡泛湖。","文寶緝柳，溫舒截蒲。","伯道無兒，嵇紹不孤。","綠珠墜樓，文君當壚。","伊尹負鼎，甯戚叩角。","趙壹坎壈，顏駟蹇剝。","龔遂勸農，文翁興學。","晏御揚揚，五鹿嶽嶽。","蕭珠結綬，王貢彈冠。","龐統展驥，仇覽栖鷹。","葛亮顧廬，韓信升壇。","王褒柏慘，閔損衣單。","蒙恬製筆，蔡倫造紙。","孔伋緼袍，祭遵布被。","周公握髮，蔡邕倒屣。","王敦傾室，紀瞻出妓。","暴勝持斧，張綱埋輪。","靈運曲笠，林宗折巾。","屈原澤畔，漁父江濱。","魏勃埽門，潘岳望塵。","京房推律，翼奉觀性。","甘寧奢侈，陸凱貴盛。","干木富義，於陵辭聘。","元凱傳癖，伯英草聖。","馮異大樹，千秋小車。","漂母進食，孫鍾設瓜。","壺公謫天，薊訓歷家。","劉玄刮席，晉惠聞蟆。","伊籍一拜，酈生長揖。","馬安四至，應璩三入。","郭解借交，朱家脫急。","虞延剋期，盛吉垂泣。","豫讓吞炭，鉏麑觸槐。","阮孚蠟屐，祖約好財。","初平起石，左慈擲杯。","武陵桃源，劉阮天台。","王儉墜車，褚淵落水。","季倫錦障，春申珠履。","甄后出拜，劉楨平視。","胡嬪爭摴，晉武傷指。","石慶數馬，孔光溫樹。","翟湯隱操，許詢勝具。","優旃滑稽，落下曆數。","曼容自免，子平畢娶。","師曠清耳，離婁明目。","仲文照鏡，臨江折軸。","欒巴噀酒，偃師舞木。","德潤傭書，君平賣卜。","叔寶玉潤，彥輔冰清。","衛后髮鬒，飛燕體輕。","玄石沈湎，劉伶解酲。","趙勝謝躄，楚莊絕纓。","惡來多力，飛廉善走。","趙孟疵面，田駢天口。","張憑理窟，裴頠談藪。","仲宣獨步，子建八斗。","廣漢鉤距，弘羊心計。","衛青拜幕，去病辭第。","酈寄賣友，紀信詐帝。","濟叔不癡，周兄無慧。","虞卿擔簦，蘇章負笈。","南風擲孕，商受斮涉。","廣德從橋，君章拒獵。","應奉五行，安世三篋。","相如題柱，終軍棄繻。","孫晨槀席，原憲桑樞。","端木辭金，鍾離委珠。","季札挂劒，徐穉致芻。","朱雲折檻，申屠斷鞅。","衛玠羊車，王恭鶴氅。","管仲隨馬，蒼舒稱象。","丁蘭刻木，伯瑜泣杖。","陳逵豪爽，田方簡傲。","黃向訪主，陳寔遺盜。","龐儉鑿井，陰方祀竈。","韓壽竊香，王濛市帽。","句踐投醪，陸抗嘗藥。","孔愉放龜，張顥墮鵲。","田豫儉素，李恂清約。","義縱攻剽，周陽暴虐。","孟陽擲瓦，賈氏如臯。","顏回簞瓢，仲蔚蓬蒿。","糜竺收資，桓景登高。","雷煥送劒，呂虔佩刀。","老萊斑衣，黃香扇枕。","王祥守奈，蔡順分椹。","淮南食時，左思十稔。","劉惔傾釀，孝伯痛飲。","女媧補天，長房縮地。","季珪士首，長孺國器。","陸玩無人，賈詡非次。","何晏神伏，郭奕心醉。","常林帶經，高鳳漂麥。","孟嘉落帽，庾凱墮幘。","龍逢板出，張華台坼。","董奉活燮，扁鵲起虢。","寇恂借一，何武去思。","韓子孤憤，梁鴻五噫。","蔡琰辨琴，王粲覆棊。","西門投巫，何謙焚祠。","孟嘗還珠，劉昆反火。","姜肱共被，孔融讓果。","端康相代，亮陟隔坐。","趙倫鶹怪，梁孝牛禍。","桓典避馬，王尊叱馭。","鼂錯峭直，趙禹廉倨。","亮遺巾幗，備失匕箸。","張翰適意，陶潛歸去。","魏儲南館，漢相東閣。","楚元置醴，陳蕃下榻。","廣利泉湧，王霸冰合。","孔融坐滿，鄭崇門雜。","張堪折轅，周鎮漏船。","郭伋竹馬，劉寬蒲鞭。","許史侯盛，韋平相延。","雍伯種玉，黃尋飛錢。","王允千里，黃憲萬頃。","虞𩦎才望，戴淵鋒穎。","史魚黜殯，子囊城郢。","戴封積薪，耿恭拜井。","汲黯開倉，馮驩折券。","齊景駟千，何曾食萬。","顧榮錫炙，田文比飯。","稚珪蛙鳴，彥倫鶴怨。","廉頗負荆，須賈擢髮。","孔翊絕書，申嘉私謁。","淵明把菊，真長望月。","子房取履，釋之結韤。","郭丹約關，祖逖誓江。","賈逵問事，許慎無雙。","婁敬和親，白起坑降。","蕭史鳳臺，宋宗雞窗。","王陽囊衣，馬援薏苡。","劉整交質，五倫十起。","張敞畫眉，謝鯤折齒。","盛彥感螬，姜詩躍鯉。","宗資主諾，成瑨坐嘯。","伯成辭耕，嚴陵去釣。","董遇三餘，譙周獨笑。","將閭仰天，王凌呼廟。","二疏散金，陸賈分橐。","慈明八龍，禰衡一鶚。","不占隕車，子雲投閣。","魏舒堂堂，周舍諤諤。","無鹽如漆，姑射若冰。","邾子投火，王思怒蠅。","符朗皁白，易牙淄澠。","周勃織薄，灌嬰販繒。","馬良白眉，阮籍青眼。","黥布開關，張良燒棧。","陳遺飯感，陶侃酒限。","楚昭萍實，束皙竹簡。","曼倩三冬，陳思七步。","劉寵一錢，廉范五袴。","氾毓字孤，郗鑒吐哺。","苟弟轉酷，嚴母埽墓。","洪喬擲水，陳泰挂壁。","王述忿狷，荀粲惑溺。","宋女愈謹，敬姜猶績。","鮑照篇翰，陳琳書檄。","浩浩萬古，不可備甄。","芟繁摭華，爾曹勉旃。"]', '["王戎簡要，裴楷清通。","孔明臥龙，呂望非熊。","楊震关西，丁寬易东。","謝安高潔，王導公忠。","匡衡鑿壁，孫敬閉戶。","郅都蒼鷹，寧成乳虎。","周嵩狼抗，梁冀跋扈。","郗超䫇參，王珣短簿。","伏波標柱，博望尋河。","李陵初诗，田橫感歌。","武仲不休，士衡患多。","桓譚非讖，王商止訛。","嵇呂命駕，程孔傾蓋。","劇孟一敵，周处三害。","胡廣補闕，袁安倚賴。","黄霸政殊，梁習治最。","墨子悲絲，楊朱泣岐。","朱博烏集，蕭芝雉隨。","杜后生齒，靈王出髭。","賈誼忌鵩，莊周畏犧。","燕昭築台，鄭莊置驛。","瓘靖二妙，岳湛連璧。","郄詵一枝，戴馮重席。","鄒陽长裾，王符逢掖。","鳴鹤日下，士龙云间。","晉宣狼顧，漢祖龙顏。","鲍靚記井，羊祜識环。","仲容青云，叔夜玉山。","毛義捧檄，子路負米。","江革忠孝，王覽友弟。","蕭何定律，叔孫制禮。","葛豐刺舉，息躬歷詆。","管寧割席，和嶠專车。","时苗留犢，羊續懸鱼。","樊噲排闥，辛毘引裾。","孫楚漱石，郝隆曬书。","枚臯詣闕，充国自贊。","王衍风鑑，許劭月旦。","賀循儒宗，孫綽才冠。","太叔辨洽，摯仲辞翰。","山濤識量，毛玠公方。","袁盎却座，衛瓘撫牀。","于公高门，曹參趣裝。","庶女振风，鄒衍降霜。","范丹生塵，晏嬰脫粟。","詰汾兴魏，鼈靈王蜀。","不疑誣金，卞和泣玉。","檀卿沐猴，謝尚鴝鵒。","泰初日月，季野陽秋。","荀陳德星，李郭仙舟。","王忳繡被，張氏銅鉤。","丁公遽戮，雍齒先侯。","陳雷膠漆，范張雞黍。","周侯山嶷，會稽霞舉。","季布一諾，阮瞻三語。","郭文游山，袁宏泊渚。","黄琬对日，秦宓論天。","孟軻養素，揚雄草玄。","向秀闻笛，伯牙絕弦。","郭槐自屈，南郡猶怜。","魯恭馴雉，宋均去獸。","廣客蛇影，殷師牛鬬。","元禮模楷，季彥領袖。","魯褒錢神，崔烈銅臭。","梁竦廟食，趙溫雄飞。","枚乘蒲輪，鄭均白衣。","陵母伏劒，軻親斷機。","齊后破环，謝女解圍。","鑿齒尺牘，荀勗音律。","胡威推縑，陸績懷橘。","羅含吞鸟，江淹梦笔。","李廞清貞，劉驎高率。","蔣詡三徑，許由一瓢。","楊僕移关，杜預建橋。","壽王議鼎，杜林駮堯。","西施捧心，孫壽折腰。","靈輒扶輪，魏顆結草。","逸少傾寫，平子絕倒。","澹台毀璧，子罕辞寶。","东平爲善，司马稱好。","公超霧市，魯般云梯。","田單火牛，江逌爇雞。","蔡裔殞盜，張遼止啼。","陳平多轍，李廣成蹊。","陳遵投轄，山簡倒載。","淵客泣珠，交甫解佩。","龔勝不屈，孫寶自劾。","呂安題鳳，子猷訪戴。","董宣彊項，翟璜直言。","紀昌貫蝨，養由號猨。","馮衍归里，張昭塞门。","蘇韶鬼靈，盧充幽婚。","震畏四知，秉去三惑。","柳下直道，叔敖陰德。","張湯巧詆，杜周深刻。","三王尹京，二鲍糾慝。","孫康映雪，车胤聚螢。","李充四部，井春五經。","谷永笔札，顧愷丹青。","戴逵破琴，謝敷應星。","阮宣杖头，畢卓甕下。","文伯羞鼈，孟宗寄鮓。","史丹青蒲，張湛白马。","隐之感鄰，王修輟社。","阮放八雋，江臮四凶。","华歆忤旨，陳羣蹙容。","王濬懸刀，丁固生松。","姜維膽斗，盧植音鐘。","桓溫奇骨，鄧艾大志。","楊修捷对，羅友默記。","杜康造酒，蒼頡制字。","樗里智囊，邊韶經笥。","滕公佳城，王果石崖。","買妻恥醮，澤室犯斋。","马后大練，孟光荆釵。","顏叔秉燭，宋弘不諧。","鄧通銅山，郭況金穴。","秦彭攀轅，侯霸臥轍。","淳于炙輠，彥国吐屑。","太真玉台，武子金埓。","巫马戴星，宓賤彈琴。","郝廉留錢，雷義送金。","逢萌挂冠，胡昭投簪。","王喬雙鳧，华佗五禽。","程邈隸书，史籀大篆。","王承鱼盜，丙吉牛喘。","賈琮褰帷，郭賀露冕。","馮媛當熊，班女辞輦。","王充閱市，董生下帷。","平叔傅粉，弘治凝脂。","楊生黄雀，毛子白龟。","宿瘤采桑，漆室憂葵。","韋賢满籯，夏侯拾芥。","阮簡曠達，袁耽俊邁。","蘇武持節，鄭衆不拜。","郭巨將坑，董永自賣。","仲連蹈海，范蠡泛湖。","文寶緝柳，溫舒截蒲。","伯道無兒，嵇紹不孤。","綠珠墜楼，文君當壚。","伊尹負鼎，甯戚叩角。","趙壹坎壈，顏駟蹇剝。","龔遂勸農，文翁兴学。","晏御揚揚，五鹿嶽嶽。","蕭珠結綬，王貢彈冠。","龐統展驥，仇覽栖鷹。","葛亮顧廬，韓信升壇。","王褒柏慘，閔損衣單。","蒙恬製笔，蔡倫造紙。","孔伋緼袍，祭遵布被。","周公握髮，蔡邕倒屣。","王敦傾室，紀瞻出妓。","暴勝持斧，張綱埋輪。","靈運曲笠，林宗折巾。","屈原澤畔，漁父江濱。","魏勃埽门，潘岳望塵。","京房推律，翼奉观性。","甘寧奢侈，陸凱貴盛。","干木富義，於陵辞聘。","元凱傳癖，伯英草聖。","馮異大樹，千秋小车。","漂母進食，孫鍾設瓜。","壺公謫天，薊訓歷家。","劉玄刮席，晉惠闻蟆。","伊籍一拜，酈生长揖。","马安四至，應璩三入。","郭解借交，朱家脫急。","虞延剋期，盛吉垂泣。","豫讓吞炭，鉏麑觸槐。","阮孚蠟屐，祖約好財。","初平起石，左慈擲杯。","武陵桃源，劉阮天台。","王儉墜车，褚淵落水。","季倫錦障，春申珠履。","甄后出拜，劉楨平視。","胡嬪爭摴，晉武傷指。","石慶數马，孔光溫樹。","翟湯隐操，許詢勝具。","優旃滑稽，落下曆數。","曼容自免，子平畢娶。","師曠清耳，離婁明目。","仲文照镜，臨江折軸。","欒巴噀酒，偃師舞木。","德潤傭书，君平賣卜。","叔寶玉潤，彥輔冰清。","衛后髮鬒，飞燕體轻。","玄石沈湎，劉伶解酲。","趙勝謝躄，楚莊絕纓。","惡来多力，飞廉善走。","趙孟疵面，田駢天口。","張憑理窟，裴頠談藪。","仲宣独步，子建八斗。","廣漢鉤距，弘羊心計。","衛青拜幕，去病辞第。","酈寄賣友，紀信詐帝。","濟叔不癡，周兄無慧。","虞卿擔簦，蘇章負笈。","南风擲孕，商受斮涉。","廣德從橋，君章拒獵。","應奉五行，安世三篋。","相如題柱，終軍棄繻。","孫晨槀席，原憲桑樞。","端木辞金，鍾離委珠。","季札挂劒，徐穉致芻。","朱云折檻，申屠斷鞅。","衛玠羊车，王恭鹤氅。","管仲隨马，蒼舒稱象。","丁蘭刻木，伯瑜泣杖。","陳逵豪爽，田方簡傲。","黄向訪主，陳寔遺盜。","龐儉鑿井，陰方祀竈。","韓壽竊香，王濛市帽。","句踐投醪，陸抗嘗藥。","孔愉放龟，張顥墮鵲。","田豫儉素，李恂清約。","義縱攻剽，周陽暴虐。","孟陽擲瓦，賈氏如臯。","顏回簞瓢，仲蔚蓬蒿。","糜竺收資，桓景登高。","雷煥送劒，呂虔佩刀。","老萊斑衣，黄香扇枕。","王祥守奈，蔡順分椹。","淮南食时，左思十稔。","劉惔傾釀，孝伯痛饮。","女媧補天，长房縮地。","季珪士首，长孺国器。","陸玩無人，賈詡非次。","何晏神伏，郭奕心醉。","常林带經，高鳳漂麦。","孟嘉落帽，庾凱墮幘。","龙逢板出，張华台坼。","董奉活燮，扁鵲起虢。","寇恂借一，何武去思。","韓子孤憤，梁鴻五噫。","蔡琰辨琴，王粲覆棊。","西门投巫，何謙焚祠。","孟嘗還珠，劉昆反火。","姜肱共被，孔融讓果。","端康相代，亮陟隔坐。","趙倫鶹怪，梁孝牛禍。","桓典避马，王尊叱馭。","鼂錯峭直，趙禹廉倨。","亮遺巾幗，備失匕箸。","張翰適意，陶潛归去。","魏儲南館，漢相东閣。","楚元置醴，陳蕃下榻。","廣利泉湧，王霸冰合。","孔融坐满，鄭崇门杂。","張堪折轅，周鎮漏船。","郭伋竹马，劉寬蒲鞭。","許史侯盛，韋平相延。","雍伯種玉，黄尋飞錢。","王允千里，黄憲万頃。","虞𩦎才望，戴淵鋒穎。","史鱼黜殯，子囊城郢。","戴封積薪，耿恭拜井。","汲黯开倉，馮驩折券。","齊景駟千，何曾食万。","顧榮錫炙，田文比飯。","稚珪蛙鳴，彥倫鹤怨。","廉頗負荆，須賈擢髮。","孔翊絕书，申嘉私謁。","淵明把菊，真长望月。","子房取履，釋之結韤。","郭丹約关，祖逖誓江。","賈逵问事，許慎無雙。","婁敬和親，白起坑降。","蕭史鳳台，宋宗雞窗。","王陽囊衣，马援薏苡。","劉整交質，五倫十起。","張敞畫眉，謝鯤折齒。","盛彥感螬，姜诗躍鯉。","宗資主諾，成瑨坐嘯。","伯成辞耕，嚴陵去釣。","董遇三餘，譙周独笑。","將閭仰天，王凌呼廟。","二疏散金，陸賈分橐。","慈明八龙，禰衡一鶚。","不占隕车，子云投閣。","魏舒堂堂，周舍諤諤。","無鹽如漆，姑射若冰。","邾子投火，王思怒蠅。","符朗皁白，易牙淄澠。","周勃织薄，灌嬰販繒。","马良白眉，阮籍青眼。","黥布开关，張良燒棧。","陳遺飯感，陶侃酒限。","楚昭萍實，束皙竹簡。","曼倩三冬，陳思七步。","劉寵一錢，廉范五袴。","氾毓字孤，郗鑒吐哺。","苟弟轉酷，嚴母埽墓。","洪喬擲水，陳泰挂壁。","王述忿狷，荀粲惑溺。","宋女愈謹，敬姜猶績。","鲍照篇翰，陳琳书檄。","浩浩万古，不可備甄。","芟繁摭华，爾曹勉旃。"]', '诗', 'shi', '', NULL, '蒙求 李瀚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebabe85e-144e-4661-a853-09bbb5005868', '宗廟九德之歌辭', '宗廟九德之歌辞', 'c1f09038-b18e-4605-849b-e513b016fa4b', '唐', '["皇祖誕慶，於昭于天。","積德斯遠，茂攸緒先。","維文應曆，神武弘宣。","肇迹□水，成功坂泉。","道光覆載，聲穆吉先。","式備犧象，用□牲牷。","禮終九獻，樂展四懸。","神貺景福，遐哉永年。"]', '["皇祖誕慶，於昭于天。","積德斯远，茂攸緒先。","維文應曆，神武弘宣。","肇迹□水，成功坂泉。","道光覆載，声穆吉先。","式備犧象，用□牲牷。","禮終九獻，乐展四懸。","神貺景福，遐哉永年。"]', '诗', 'shi', '', NULL, '宗廟九德之歌辭 褚亮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9695ecc-7555-4829-b1e8-5699038ccc78', '太廟祼地歌辭', '太廟祼地歌辞', 'fc6a1be5-84e8-43f9-8b5e-244fe8e69cca', '唐', '["清廟既裸，鬱鬯推禮。","大哉孝思，嚴恭祖禰。","龍衮以祭，鸞刀思啓。","發德朱弦，升歌丹陛。","遙享粢盛，堂斟況齊。","降福穰穰，來儀濟濟。"]', '["清廟既裸，鬱鬯推禮。","大哉孝思，嚴恭祖禰。","龙衮以祭，鸾刀思啓。","發德朱弦，升歌丹陛。","遙享粢盛，堂斟況齊。","降福穰穰，来儀濟濟。"]', '诗', 'shi', '', NULL, '太廟祼地歌辭 陳叔達 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7684ea4c-fd62-456e-aed3-5a90d9a71089', '堦前石行', '堦前石行', '24545951-5e18-436e-b7b7-ba8191227f84', '唐', '["上天布甘雨，萬物咸均平。","自顧微且賤，亦得蒙滋榮。","萋萋結綠枝，曄曄垂朱英。","常恐零露降，不得全其生。","歎息聊自思，此生豈我情。","昔我未生時，誰者令我萌。","棄置勿重陳，委化何所營。"]', '["上天布甘雨，万物咸均平。","自顧微且賤，亦得蒙滋榮。","萋萋結綠枝，曄曄垂朱英。","常恐零露降，不得全其生。","歎息聊自思，此生豈我情。","昔我未生时，誰者令我萌。","棄置勿重陳，委化何所營。"]', '诗', 'shi', '', NULL, '堦前石行 王績 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37de5d02-7e31-47d9-8e5a-9aa80bccdc62', '九月九日', '九月九日', '3dd1f8dc-a616-412a-8f4f-a1a3b96d28f6', '唐', '["九日重陽節，三秋季月殘。","菊花催晚氣，萸房辟早寒。","霜濃鷹擊遠，霧重雁飛難。","誰憶龍山外，蕭條邊興闌。"]', '["九日重陽節，三秋季月殘。","菊花催晚氣，萸房辟早寒。","霜濃鷹擊远，霧重雁飞难。","誰憶龙山外，蕭條邊兴闌。"]', '诗', 'shi', '', NULL, '九月九日 崔善爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7168e7-dda7-4db8-a257-a9bbbff8883b', '奉和九月九日應制', '奉和九月九日應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["爽氣申時豫，臨秋肆武功。","太液榮光發，曾城佳氣融。","紫霄寒暑麗，黃山極望通。","講藝遵先𮜿，覩德暢宸衷。","鷲嶺飛夏服，娥魄亂雕弓。","汗浹鑣流赭，塵生埓散紅。","飲羽驚開石，中葉遽凋叢。","雁殫雲路靜，烏墜日輪空。","九流參廣宴，萬宇抃恩隆。"]', '["爽氣申时豫，臨秋肆武功。","太液榮光發，曾城佳氣融。","紫霄寒暑丽，黄山極望通。","講藝遵先𮜿，覩德暢宸衷。","鷲嶺飞夏服，娥魄亂雕弓。","汗浹鑣流赭，塵生埓散紅。","饮羽驚开石，中葉遽凋叢。","雁殫云路静，烏墜日輪空。","九流參廣宴，万宇抃恩隆。"]', '诗', 'shi', '', NULL, '奉和九月九日應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ced6745-f334-45de-b6bc-b169f3bc3d60', '奉和守歲應制', '奉和守歲應制', '89ed7e48-6d32-48c4-84f3-81395616df78', '唐', '["玉琯移玄序，金奏賞彤闈。","祥鸞歌裏轉，春燕舞前歸。","壽爵傳三禮，燈枝麗九微。","運廣薰風積，恩深湛露晞。","送寒終此夜，延宴待晨暉。"]', '["玉琯移玄序，金奏賞彤闈。","祥鸾歌裏轉，春燕舞前归。","壽爵傳三禮，灯枝丽九微。","運廣薰风積，恩深湛露晞。","送寒終此夜，延宴待晨暉。"]', '诗', 'shi', '', NULL, '奉和守歲應制 許敬宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe904573-3cd1-452e-9bcf-e17e51f149f4', '凌晨', '凌晨', '27f24bee-3389-4d40-8463-6f6e93e6c4d3', '唐', '["日掩鴻都夕，河低亂箭移。","蟲飛明月戶，鵲繞落花枝。","蘭襟帳北壑，玉匣鼓文漪。","聞有啼鶯處，暗幄曉雲披。"]', '["日掩鴻都夕，河低亂箭移。","蟲飞明月戶，鵲繞落花枝。","蘭襟帳北壑，玉匣鼓文漪。","闻有啼鶯处，暗幄晓云披。"]', '诗', 'shi', '', NULL, '凌晨 盧照隣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b9eb36c-10cc-44f0-b1ff-0f13af8cde3c', '登北固山', '登北固山', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["京鎮周天險，東南作北關。","埭橫江曲路，戍入海中山。","望越心初切，思秦鬢已斑。","空憐上林雁，朝夕待春還。"]', '["京鎮周天險，东南作北关。","埭橫江曲路，戍入海中山。","望越心初切，思秦鬢已斑。","空怜上林雁，朝夕待春還。"]', '诗', 'shi', '', NULL, '登北固山 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f44e02b-2e60-43e3-bbb5-7443e9f28ffa', '陪羣公登箕山賦得羣字', '陪羣公登箕山賦得羣字', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["許由去已遠，冥莫見幽墳。","世薄人不貴，茲山唯白雲。","寧知三千歲，復有堯爲君。","時佐激頹俗，登箕挹清芬。","高節雖旦暮，邈與洪崖羣。"]', '["許由去已远，冥莫见幽墳。","世薄人不貴，茲山唯白云。","寧知三千歲，复有堯爲君。","时佐激頹俗，登箕挹清芬。","高節雖旦暮，邈與洪崖羣。"]', '诗', 'shi', '', NULL, '陪羣公登箕山賦得羣字 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fce924e5-d51e-463c-97dc-d366989542f6', '人日兼立春小園宴', '人日兼立春小园宴', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["黃山積高次，表裏望京邑。","白日最靈朝，登攀盡原隰。","年灰律象動，陽氣開迎入。","煙靄長薄含，臨流小溪澀。","賓朋莫我棄，詞賦當春立。","更與韶物期，不孤東園集。"]', '["黄山積高次，表裏望京邑。","白日最靈朝，登攀尽原隰。","年灰律象动，陽氣开迎入。","煙靄长薄含，臨流小溪澀。","賓朋莫我棄，词賦當春立。","更與韶物期，不孤东园集。"]', '诗', 'shi', '', NULL, '人日兼立春小園宴 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d619eca-11cc-4f3b-8cff-fab2c6e01389', '和黃門舅十五夜作', '和黄门舅十五夜作', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["聞君陌上來，歌管沸相催。","孤月連明照，千燈合暗開。","寶裝遊騎出，香繞看車迴。","獨有歸閑意，春庭伴落梅。"]', '["闻君陌上来，歌管沸相催。","孤月連明照，千灯合暗开。","寶裝游騎出，香繞看车迴。","独有归闲意，春庭伴落梅。"]', '诗', 'shi', '', NULL, '和黃門舅十五夜作 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c865f894-816c-46a9-bbc6-aeb0f18ee740', '登綿州富樂山別李道士䇿', '登綿州富乐山別李道士䇿', 'b7e6100f-0f8e-42d1-a91a-49481ba62ed4', '唐', '["珠闕崑山遠，銀宮漲海懸。","送君從此路，城郭幾千年。","雲霧含丹景，桑麻覆細田。","笙歌未盡曲，風馭獨泠然。"]', '["珠闕崑山远，銀宮漲海懸。","送君從此路，城郭幾千年。","云霧含丹景，桑麻覆細田。","笙歌未尽曲，风馭独泠然。"]', '诗', 'shi', '', NULL, '登綿州富樂山別李道士䇿 薛曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e0fb2b1-7fe9-4298-b12e-bd8a2b6965f7', '九城尋山水', '九城尋山水', 'b7e6100f-0f8e-42d1-a91a-49481ba62ed4', '唐', '["菊浦桃源瞰九城，鸞歌鳳嘯忽將迎。","千巖雜樹雲霞色，百道流泉風雨聲。","上客由來軒蓋重，幽人自覺薜蘿輕。","疑是昔年棲息地，山中日暮有餘情。"]', '["菊浦桃源瞰九城，鸾歌鳳嘯忽將迎。","千巖杂樹云霞色，百道流泉风雨声。","上客由来軒蓋重，幽人自覺薜蘿轻。","疑是昔年棲息地，山中日暮有餘情。"]', '诗', 'shi', '', NULL, '九城尋山水 薛曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d299b7-066f-400f-862a-871cd02f7f2f', '邙山古意', '邙山古意', 'b7e6100f-0f8e-42d1-a91a-49481ba62ed4', '唐', '["昔掩佳城路，曾驚壑易遷。","今接宜都里，翻疑海作田。","鏤鼎名應大，生金字不傳。","風飆吹白日，羅綺拭黃泉。","象鳳笙留國，成龍劒上天。","長樂移新壟，咸陽失舊阡。","川流徒漫漫，神理竟綿綿。","佇見飛來鶴，沈嗟不學仙。"]', '["昔掩佳城路，曾驚壑易遷。","今接宜都里，翻疑海作田。","鏤鼎名應大，生金字不傳。","风飆吹白日，羅綺拭黄泉。","象鳳笙留国，成龙劒上天。","长乐移新壟，咸陽失旧阡。","川流徒漫漫，神理竟綿綿。","佇见飞来鹤，沈嗟不学仙。"]', '诗', 'shi', '', NULL, '邙山古意 薛曜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5312e844-d52a-496f-a44d-0347971845ab', '鳳閣南廳槐樹半生死雖遇陽和終呈枯朽託根清禁頗覺非宜感物緣情率爾爲詠', '鳳閣南廳槐樹半生死雖遇陽和終呈枯朽託根清禁頗覺非宜感物緣情率爾爲詠', 'e0a2bc68-0715-4c69-a8a8-6218aaaa4fc4', '唐', '["庭槐歲月深，半死尚抽心。","葉少寧障日，枝疎不礙禽。","帷幄諒無取，棟梁非所在。","媿在龍樓側，羞處鳳池陰。","未能辭雨露，猶得款衣簪。","惜悲生意盡，空餘古木吟。"]', '["庭槐歲月深，半死尚抽心。","葉少寧障日，枝疎不礙禽。","帷幄諒無取，棟梁非所在。","媿在龙楼側，羞处鳳池陰。","未能辞雨露，猶得款衣簪。","惜悲生意尽，空餘古木吟。"]', '诗', 'shi', '', NULL, '鳳閣南廳槐樹半生死雖遇陽和終呈枯朽託根清禁頗覺非宜感物緣情率爾爲詠 李懷遠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61d4a0be-449b-4f0d-bffc-4055825898ef', '和九月九日登慈恩寺浮圖應制', '和九月九日登慈恩寺浮圖應制', 'baa921db-caa9-4556-9ab9-7801616aa382', '唐', '["出豫垂佳節，憑高陟梵宮。","皇心滿塵界，佛迹現虛空。","日月宜長壽，天人得大通。","喜聞題寶偈，受記莫由同。"]', '["出豫垂佳節，憑高陟梵宮。","皇心满塵界，佛迹現虛空。","日月宜长壽，天人得大通。","喜闻題寶偈，受記莫由同。"]', '诗', 'shi', '', NULL, '和九月九日登慈恩寺浮圖應制 趙彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a7ee87f-b579-4951-b826-e435d86fb9a6', '秋夜巫山', '秋夜巫山', '7902da67-399b-4060-aac6-d860d7122958', '唐', '["巫峽裴回雨，陽臺淡蕩雲。","江山空窈窕，朝暮自紛氳。","螢色寒秋露，猨啼清夜聞。","誰憐夢魂遠，腸斷思紛紛。"]', '["巫峽裴回雨，陽台淡蕩云。","江山空窈窕，朝暮自紛氳。","螢色寒秋露，猨啼清夜闻。","誰怜梦魂远，腸斷思紛紛。"]', '诗', 'shi', '', NULL, '秋夜巫山 喬備 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b7f2d5-f8f3-4572-80d2-9c8aad1aacc2', '晦日與盧舍人同詣補闕城南林園', '晦日與盧舍人同詣補闕城南林园', '7f8e8631-fd9c-42b3-b5b3-dbe716b4a35c', '唐', '["芳年正月晦，假日早朝迴。","欲盡三春賞，還欽二阮才。","柳迎郊騎入，花近□庭開。","宛是人寰外，真情寓物來。"]', '["芳年正月晦，假日早朝迴。","欲尽三春賞，還欽二阮才。","柳迎郊騎入，花近□庭开。","宛是人寰外，真情寓物来。"]', '诗', 'shi', '', NULL, '晦日與盧舍人同詣補闕城南林園 孫逖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9cd36e5-6105-4959-80e4-9803fc8dd99c', '贈劉藍田', '贈劉藍田', '1684753a-bf81-44bf-b413-c21e565f8425', '唐', '["籬中犬迎吠，出屋候柴扉。","歲晏輸井稅，山村人暮歸。","晚田始家食，餘布成我衣。","對此能無事，勞君問是非。"]', '["籬中犬迎吠，出屋候柴扉。","歲晏輸井稅，山村人暮归。","晚田始家食，餘布成我衣。","对此能無事，勞君问是非。"]', '诗', 'shi', '', NULL, '贈劉藍田 盧象 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e1e37d-6979-497f-a527-9015b612182c', '清明日青龍寺上方', '清明日青龙寺上方', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["上方偏可適，季月況堪過。","遠近人都至，東西山色多。","夕陽留逕草，新葉變庭柯。","已度清明節，春愁如客何。"]', '["上方偏可適，季月況堪過。","远近人都至，东西山色多。","夕陽留逕草，新葉变庭柯。","已度清明節，春愁如客何。"]', '诗', 'shi', '', NULL, '清明日青龍寺上方 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8ba9d98-7fdd-42e5-9b93-a6c2e250a624', '羽山', '羽山', 'd182350e-d601-466d-bda9-b209e9ea4219', '唐', '["九山方蕩潏，三考佇良材。","夏祖何屯圯，遷殛此山隈。","空餘下泉客，誰復辨黃能。"]', '["九山方蕩潏，三考佇良材。","夏祖何屯圯，遷殛此山隈。","空餘下泉客，誰复辨黄能。"]', '诗', 'shi', '', NULL, '羽山 蕭頴士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ce07641-2975-4123-abe5-a5e2b2f6ccb0', '遊馬耳山', '游马耳山', 'd182350e-d601-466d-bda9-b209e9ea4219', '唐', '["茲山表東服，遠近瞻其名。","合沓盡溟漲，渾渾連太清。","我來疑初伏，幽路無炎精。","流水出溪盡，覆蘿搖風輕。","高深變氣候，俯仰暮天晴。","入谷煙雨潤，登崖雲日明。","乾坤正含養，種植總滋榮。","草樹皆秀色，雛麋亂新聲。","攀巖挹桂髓，洞穴拾瑤英。","此地隱微逕，何人得長生。","宿心尚葛許，彌願棲蓬瀛。","太息宦名路，遲迴忠孝情。","還丹昧遠術，養素慚幽貞。","安得從此去，悠然昇玉京。"]', '["茲山表东服，远近瞻其名。","合沓尽溟漲，渾渾連太清。","我来疑初伏，幽路無炎精。","流水出溪尽，覆蘿搖风轻。","高深变氣候，俯仰暮天晴。","入谷煙雨潤，登崖云日明。","乾坤正含養，種植總滋榮。","草樹皆秀色，雛麋亂新声。","攀巖挹桂髓，洞穴拾瑤英。","此地隐微逕，何人得长生。","宿心尚葛許，彌願棲蓬瀛。","太息宦名路，遲迴忠孝情。","還丹昧远術，養素慚幽貞。","安得從此去，悠然昇玉京。"]', '诗', 'shi', '', NULL, '遊馬耳山 蕭頴士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88488c60-807a-4e14-be17-d9d66d1cb06c', '□□□趙載同遊焦湖夜歸作', '□□□趙載同游焦湖夜归作', 'd182350e-d601-466d-bda9-b209e9ea4219', '唐', '["□□將澤國，淜騰迎淮甸。","東江輸大江，別流從此縣。","仙尉俯勝境，輕橈恣遊衍。","自公暇有餘，微尚得所願。","拈引間翰墨，風流盡歡宴。","稍移井邑閑，始悅登眺便。","遙岫逢應接，連塘乍迴轉。","劃然氣象分，萬頃行可見。","波中峰一點，雲際帆千片。","浩歎無端涯，孰知蘊虛變。","往遊信不厭，畢景方未還。","蘭□煙靄裏，延緣蒲稗間。","勢隨風潮遠，心與□□閑。","迴見出浦月，雄光射東關。","悠然蓬壺事，□□□衰顏。","安得傲吏隱，彌年寓茲山。"]', '["□□將澤国，淜腾迎淮甸。","东江輸大江，別流從此縣。","仙尉俯勝境，轻橈恣游衍。","自公暇有餘，微尚得所願。","拈引间翰墨，风流尽歡宴。","稍移井邑闲，始悅登眺便。","遙岫逢應接，連塘乍迴轉。","劃然氣象分，万頃行可见。","波中峰一点，云際帆千片。","浩歎無端涯，孰知蘊虛变。","往游信不厭，畢景方未還。","蘭□煙靄裏，延緣蒲稗间。","勢隨风潮远，心與□□闲。","迴见出浦月，雄光射东关。","悠然蓬壺事，□□□衰顏。","安得傲吏隐，彌年寓茲山。"]', '诗', 'shi', '', NULL, '□□□趙載同遊焦湖夜歸作 蕭頴士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e41de81a-1060-4cf1-aa51-071011f32c5e', '龍興觀金籙建醮', '龙兴观金籙建醮', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["泰山巖巖兮凌紫氛，中有羣仙兮乘白雲，陳金薦璧兮□□□。"]', '["泰山巖巖兮凌紫氛，中有羣仙兮乘白云，陳金薦璧兮□□□。"]', '诗', 'shi', '', NULL, '龍興觀金籙建醮 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91285ada-838b-4f3f-9a57-6e909cb6cb55', '山中松', '山中松', '4a94c648-4c3d-43bc-badc-e28b176dc769', '唐', '["枝聳碧雲端，根侵蘚壁盤。","幾經良匠顧，猶作散材看。","雪積花開少，風多子落乾。","空存後凋色，歲晚出林巒。"]', '["枝聳碧云端，根侵蘚壁盤。","幾經良匠顧，猶作散材看。","雪積花开少，风多子落乾。","空存後凋色，歲晚出林巒。"]', '诗', 'shi', '', NULL, '山中松 張鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98b5f1ff-c232-4e1e-a7e9-def2f9c9297c', '庭前晚花開', '庭前晚花开', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["西王母桃種我家，三千陽春始一花。","結實苦遲爲人笑，攀折唧唧長咨嗟。"]', '["西王母桃種我家，三千陽春始一花。","結實苦遲爲人笑，攀折唧唧长咨嗟。"]', '诗', 'shi', '', NULL, '庭前晚花開 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56170485-7791-4084-ae2b-5f4d7a611eed', '漢州王大錄事宅作', '漢州王大錄事宅作', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南溪老病客，相見下肩輿。","近髮看烏帽，催蓴煮白魚。","宅中平岸水，身外滿牀書。","憶爾才名叔，含悽意有餘。"]', '["南溪老病客，相见下肩輿。","近髮看烏帽，催蓴煮白鱼。","宅中平岸水，身外满牀书。","憶爾才名叔，含悽意有餘。"]', '诗', 'shi', '', NULL, '漢州王大錄事宅作 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a51727c-7910-475c-bf99-bd15c38bfa87', '田家作', '田家作', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["臥見高原燒，閑尋空谷泉。","土膏消臘後，麥隴發春前。","藥驗桐君錄，心齊莊子篇。","荒村三數處，衰柳百餘年。","好就山僧去，時過野舍眠。","汲流寧厭遠，卜地本求偏。","向子諳樵路，陶家置黍田。","雪峰明晚景，風雁急寒天。","且復冠名鶡，寧知冕戴蟬。","問津夫子倦，荷蓧丈人賢。","顧物皆從爾，求心正儻然。","稽康嬾慢性，祗自戀風煙。"]', '["臥见高原燒，闲尋空谷泉。","土膏消臘後，麦隴發春前。","藥驗桐君錄，心齊莊子篇。","荒村三數处，衰柳百餘年。","好就山僧去，时過野舍眠。","汲流寧厭远，卜地本求偏。","向子諳樵路，陶家置黍田。","雪峰明晚景，风雁急寒天。","且复冠名鶡，寧知冕戴蟬。","问津夫子倦，荷蓧丈人賢。","顧物皆從爾，求心正儻然。","稽康嬾慢性，祗自戀风煙。"]', '诗', 'shi', '', NULL, '田家作 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dd0b43b-a677-4ee0-809d-f75aaf0cefa5', '寄劉方平', '寄劉方平', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["十年不出蹊林中，一朝結束甘從戎。","嚴子持竿心寂歷，寥落荒籬遮舊宅。","終日碧湍聲自喧，暮秋黃菊花誰摘。","每望南峰如對君，昨來不見多黃雲。","石徑幽人何所在，玉泉疎鐘時獨聞。","與君從來同語默，豈是悠悠但相識。","天畔三秋空復情，袖中一字無由得。","世人易合復易離，故交棄置求新知。","歎息青青長不改，歲寒霜雪貞松枝。"]', '["十年不出蹊林中，一朝結束甘從戎。","嚴子持竿心寂歷，寥落荒籬遮旧宅。","終日碧湍声自喧，暮秋黄菊花誰摘。","每望南峰如对君，昨来不见多黄云。","石徑幽人何所在，玉泉疎鐘时独闻。","與君從来同語默，豈是悠悠但相識。","天畔三秋空复情，袖中一字無由得。","世人易合复易離，故交棄置求新知。","歎息青青长不改，歲寒霜雪貞松枝。"]', '诗', 'shi', '', NULL, '寄劉方平 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92e5941a-9a07-40eb-8a49-9cc7a6c2ddf0', '和中丞奉使承恩還終南舊居', '和中丞奉使承恩還終南旧居', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["軒車尋舊隱，賓從滿郊園。","蕭散煙霞興，殷勤故老言。","謝公山不改，陶令菊猶存。","苔蘚侵垂釣，松篁長閉門。","風霜清吏事，江海諭君恩。","祗召趨宣室，沈冥在一論。"]', '["軒车尋旧隐，賓從满郊园。","蕭散煙霞兴，殷勤故老言。","謝公山不改，陶令菊猶存。","苔蘚侵垂釣，松篁长閉门。","风霜清吏事，江海諭君恩。","祗召趨宣室，沈冥在一論。"]', '诗', 'shi', '', NULL, '和中丞奉使承恩還終南舊居 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8895e9b0-8362-498a-b82f-5e1b6706678d', '送令狐明府', '送令狐明府', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["行當臘候晚，共惜歲陰殘。","聞道巴山遠，如何蜀路難。","荒林藏積雪，亂石起驚湍。","君有親人術，應令勞者安。"]', '["行當臘候晚，共惜歲陰殘。","闻道巴山远，如何蜀路难。","荒林藏積雪，亂石起驚湍。","君有親人術，應令勞者安。"]', '诗', 'shi', '', NULL, '送令狐明府 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b75ba8-5d13-4988-a731-e4d2f8affd65', '同韓給事觀畢給事畫松石', '同韓給事观畢給事畫松石', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["海嶠微茫那得到，楚關迢遞心空憶。","夕郎善畫巖間松，遠意幽姿此何極。","千條萬葉紛異狀，虎伏螭盤爭勁力。","扶疎半映晚天青，凝澹全和曙雲黑。","煙籠月照安可道，雨濕風吹未曾息。","能將積雪辨晴光，每與連峰作寒色。","龍樓不競繁花吐，騎省偏宜遙夜直。","羅浮道士訪移來，少室山僧舊應識。","掖垣深沈晝無事，終日亭亭在人側。","古槐衰柳寧足論，還對罘罳列行植。"]', '["海嶠微茫那得到，楚关迢遞心空憶。","夕郎善畫巖间松，远意幽姿此何極。","千條万葉紛異狀，虎伏螭盤爭勁力。","扶疎半映晚天青，凝澹全和曙云黑。","煙籠月照安可道，雨濕风吹未曾息。","能將積雪辨晴光，每與連峰作寒色。","龙楼不競繁花吐，騎省偏宜遙夜直。","羅浮道士訪移来，少室山僧旧應識。","掖垣深沈晝無事，終日亭亭在人側。","古槐衰柳寧足論，還对罘罳列行植。"]', '诗', 'shi', '', NULL, '同韓給事觀畢給事畫松石 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06633922-9d92-40d7-8802-bf29afe46c6e', '送從姪棲閑律師', '送從姪棲闲律師', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["能知出世法，詎有在家心。","南院開門送，東山策杖尋。","經年期故里，及夏到空林。","念遠長勞望，朝朝草色深。"]', '["能知出世法，詎有在家心。","南院开门送，东山策杖尋。","經年期故里，及夏到空林。","念远长勞望，朝朝草色深。"]', '诗', 'shi', '', NULL, '送從姪棲閑律師 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78b8801f-141c-4f3d-8ca2-ef73f8088cc6', '舟中送李觀', '舟中送李观', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["江南近別亦依依，山晚川長客伴稀。","獨坐相思計行日，出門臨水望君歸。"]', '["江南近別亦依依，山晚川长客伴稀。","独坐相思計行日，出门臨水望君归。"]', '诗', 'shi', '', NULL, '舟中送李觀 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f3d1c62-0511-4fb2-b2db-d8c816082da1', '勅移橘栽', '勅移橘栽', 'a74e1c3c-a964-42b7-ad56-831e95bee5be', '唐', '["南橘北爲枳，古來豈虛言。","徙植期不變，陰陽感君恩。","枝條皆宛然，本土封其根。","及時望栽種，萬里繞花園。","滋味豈聖心，實以憂黎元。","暫勞致力重，永感貢獻煩。","是嗟草木類，稟異於乾坤。","願爲王母桃，千歲奉至尊。"]', '["南橘北爲枳，古来豈虛言。","徙植期不变，陰陽感君恩。","枝條皆宛然，本土封其根。","及时望栽種，万里繞花园。","滋味豈聖心，實以憂黎元。","暫勞致力重，永感貢獻煩。","是嗟草木類，稟異於乾坤。","願爲王母桃，千歲奉至尊。"]', '诗', 'shi', '', NULL, '勅移橘栽 張彪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21f5e72d-0f4c-4f9d-9d79-b4419b8fdf10', '晚霽登王六東閣', '晚霽登王六东閣', 'e73a9597-0d64-4ebe-9a5f-1ce1fa5dd69f', '唐', '["試上江樓望，初逢山雨晴。","連空青嶂合，向晚白雲生。","俊美要殊觀，蕭條見遠情。","情來不可極，日暮水流清。"]', '["試上江楼望，初逢山雨晴。","連空青嶂合，向晚白云生。","俊美要殊观，蕭條见远情。","情来不可極，日暮水流清。"]', '诗', 'shi', '', NULL, '晚霽登王六東閣 嚴維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a9a8bdc-38df-45fe-a6ed-309d99e699d6', '曲龍山歌 一', '曲龙山歌 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["曲龍丈人冠藕花，其顏色映光明砂。","玉繩金枝有通籍，五嶽三山如一家。","遙指叢霄呇靈島，島中曄曄無凡草。","九仙傲倪折五芝，翠鳳白麟回異道。","石臺石鏡月長明，石洞石橋連上清。","人間妻子見不識，拍雲揮手升天行。","摩天截漢何瀟灑，四石五雲更上下。","下方小兆更拜焉，願得騎雲作車馬。"]', '["曲龙丈人冠藕花，其顏色映光明砂。","玉繩金枝有通籍，五嶽三山如一家。","遙指叢霄呇靈島，島中曄曄無凡草。","九仙傲倪折五芝，翠鳳白麟回異道。","石台石镜月长明，石洞石橋連上清。","人间妻子见不識，拍云揮手升天行。","摩天截漢何瀟灑，四石五云更上下。","下方小兆更拜焉，願得騎云作车马。"]', '诗', 'shi', '', NULL, '曲龍山歌 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fad7421-313b-4af2-9323-ef08948d6502', '曲龍山歌 二', '曲龙山歌 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["子欲居九夷，乘桴浮於海，聖人之意有所在。","曲龍何在在海中，石室玉堂窅玲瓏。","其下琛怪之所產，其上靈棲復無限。","無風浪頂高屋脊，有風天晴翻海眼。","願逐剛風騎吏旋，起居按摩參寥天。","鳳皇頰骨流珠佩，孔雀尾毛張翠蓋。","下看人界等蟲沙，夜宿層城阿母家。"]', '["子欲居九夷，乘桴浮於海，聖人之意有所在。","曲龙何在在海中，石室玉堂窅玲瓏。","其下琛怪之所產，其上靈棲复無限。","無风浪頂高屋脊，有风天晴翻海眼。","願逐剛风騎吏旋，起居按摩參寥天。","鳳皇頰骨流珠佩，孔雀尾毛張翠蓋。","下看人界等蟲沙，夜宿層城阿母家。"]', '诗', 'shi', '', NULL, '曲龍山歌 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad82da16-d919-4156-b1a8-6fb5ef620ed7', '柳宜城鵲巢歌', '柳宜城鵲巢歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["相公宅前楊柳樹，野鵲飛來復飛去。","東家斫樹枝，西家斫樹枝。","東家西家斫樹枝，發遣野鵲巢何枝。","相君處分留野鵲，一月生得三箇兒。","相君長命復富貴，口舌貧窮徒爾爲。"]', '["相公宅前楊柳樹，野鵲飞来复飞去。","东家斫樹枝，西家斫樹枝。","东家西家斫樹枝，發遣野鵲巢何枝。","相君处分留野鵲，一月生得三箇兒。","相君长命复富貴，口舌貧窮徒爾爲。"]', '诗', 'shi', '', NULL, '柳宜城鵲巢歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09f2823e-bb05-4fff-b29d-b4cf583b6d27', '道該上人院石竹花歌', '道該上人院石竹花歌', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["道該房前石竹叢，深淺紫，深淺紅。","嬋娟灼爍委清露，小枝小葉飄香風。","上人心中如鏡中，永日垂簾觀色空。"]', '["道該房前石竹叢，深淺紫，深淺紅。","嬋娟灼爍委清露，小枝小葉飄香风。","上人心中如镜中，永日垂簾观色空。"]', '诗', 'shi', '', NULL, '道該上人院石竹花歌 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e31b96f-b2bf-49f1-a392-aa816f710f91', '九日', '九日', 'a4b2965e-c742-477d-be70-58058778c94e', '唐', '["九日強游登藻井，髮稀那敢插茱萸。","橫空過雨千峰出，大野新霜萬壑鋪。","更望尊中菊花酒，殷勤能得幾回沽。"]', '["九日強游登藻井，髮稀那敢插茱萸。","橫空過雨千峰出，大野新霜万壑鋪。","更望尊中菊花酒，殷勤能得幾回沽。"]', '诗', 'shi', '', NULL, '九日 耿湋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a9d2293-f954-46ff-a919-cbb1b3a347a0', '青陽館望九子山', '青陽館望九子山', '06e56031-264e-4496-916b-e86a866d0222', '唐', '["蒼翠岧嶢上碧天，九峰遙落縣門前。","毫芒映日千重樹，涓滴垂空萬丈泉。","武帝南遊曾駐蹕，始皇東幸亦祈年。","雲祠絕跡終難訪，唯有猨聲到客邊。"]', '["蒼翠岧嶢上碧天，九峰遙落縣门前。","毫芒映日千重樹，涓滴垂空万丈泉。","武帝南游曾駐蹕，始皇东幸亦祈年。","云祠絕跡終难訪，唯有猨声到客邊。"]', '诗', 'shi', '', NULL, '青陽館望九子山 竇叔向 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('338811f4-7f95-4dd0-a885-b5667ee79e21', '青出藍', '青出藍', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["芳藍滋匹帛，人力半天經。","浸潤加新氣，光輝勝本清。","還同冰出水，不共草爲螢。","翻覆衣襟上，偏知造化靈。"]', '["芳藍滋匹帛，人力半天經。","浸潤加新氣，光輝勝本清。","還同冰出水，不共草爲螢。","翻覆衣襟上，偏知造化靈。"]', '诗', 'shi', '', NULL, '青出藍 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3136916f-caa1-4c8b-85ea-261ee06380cb', '皇帝移晦日爲中和節', '皇帝移晦日爲中和節', 'c4876be8-a529-49a5-96a5-18b6c6e0a522', '唐', '["皇心不向晦，改節號中和。","淑氣同風景，嘉名別詠歌。","湔裙移舊俗，賜尺下新科。","曆象千年正，酺醵四海多。","花隨春令發，鴻度歲陽過。","天地齊休慶，歡聲欲蕩波。"]', '["皇心不向晦，改節號中和。","淑氣同风景，嘉名別詠歌。","湔裙移旧俗，賜尺下新科。","曆象千年正，酺醵四海多。","花隨春令發，鴻度歲陽過。","天地齊休慶，歡声欲蕩波。"]', '诗', 'shi', '', NULL, '皇帝移晦日爲中和節 王季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16ff683c-ff71-4a7f-ad9e-7b3baf0e6ff4', '送劉南史往杭州拜覲別駕叔', '送劉南史往杭州拜覲別駕叔', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["兄弟飄零自長年，見君眉白轉相憐。","清揚似玉須勤學，富貴由人不在天。","萬里榛蕪迷舊國，兩河烽火復相連。","林中若使題書信，但問漳濱訪客船。"]', '["兄弟飄零自长年，见君眉白轉相怜。","清揚似玉須勤学，富貴由人不在天。","万里榛蕪迷旧国，兩河烽火复相連。","林中若使題书信，但问漳濱訪客船。"]', '诗', 'shi', '', NULL, '送劉南史往杭州拜覲別駕叔 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce06145c-beac-4628-8569-dbf0c790d20b', '和汴州令狐相公白菊', '和汴州令狐相公白菊', '08b14256-c564-4489-be33-927205119c81', '唐', '["兔園春欲盡，別有一叢芳。","直似窮陰雪，全輕向曉霜。","凝暉侵桂魄，晶彩奪螢光。","素萼迎風舞，銀房泫露香。","水晶簾不隔，雲母扇韜鋩。","紈袖呈瑤瑟，冰容啓玉堂。","今來碧油下，知自白雲鄉。","留此非吾土，須移鳳沼傍。"]', '["兔园春欲尽，別有一叢芳。","直似窮陰雪，全轻向晓霜。","凝暉侵桂魄，晶彩奪螢光。","素萼迎风舞，銀房泫露香。","水晶簾不隔，云母扇韜鋩。","紈袖呈瑤瑟，冰容啓玉堂。","今来碧油下，知自白云乡。","留此非吾土，須移鳳沼傍。"]', '诗', 'shi', '', NULL, '和汴州令狐相公白菊 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b641d8d9-8a91-40a2-9819-8c9c3d9e97cf', '贈陳判官求子花詩', '贈陳判官求子花诗', '08b14256-c564-4489-be33-927205119c81', '唐', '["油地輕綃碧且紅，須憐纖手是良工。","能生麗思千花外，善點穠姿五彩中。","子細傳看臨霽景，殷勤持贈及春風。","若將江上迎桃葉，一帖何妨錦繡同。"]', '["油地轻綃碧且紅，須怜纖手是良工。","能生丽思千花外，善点穠姿五彩中。","子細傳看臨霽景，殷勤持贈及春风。","若將江上迎桃葉，一帖何妨錦繡同。"]', '诗', 'shi', '', NULL, '贈陳判官求子花詩 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19a3e13e-c52d-485a-b6b6-f9b41115c61b', '同諸公過福先寺律院宣上人房', '同諸公過福先寺律院宣上人房', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["律座下朝講，晝門猶掩關。","叨同靜者來，正值高雲閑。","寂爾方丈內，瑩然虛白間。","千燈智慧心，片玉清羸顏。","松色落深井，竹陰寒小山。","晤言流曦晚，惆悵歸人寰。"]', '["律座下朝講，晝门猶掩关。","叨同静者来，正值高云闲。","寂爾方丈內，瑩然虛白间。","千灯智慧心，片玉清羸顏。","松色落深井，竹陰寒小山。","晤言流曦晚，惆悵归人寰。"]', '诗', 'shi', '', NULL, '同諸公過福先寺律院宣上人房 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea55d569-22e0-4bc4-9bf5-7078c40e9b27', '城西別元九', '城西別元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["城西三月三十日，別友辭春兩恨多。","帝里却歸猶寂寞，通州獨去又如何。"]', '["城西三月三十日，別友辞春兩恨多。","帝里却归猶寂寞，通州独去又如何。"]', '诗', 'shi', '', NULL, '城西別元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8eede14-f760-47b7-8db9-1b25cff61a5e', '陳家紫藤花下贈周判官', '陳家紫藤花下贈周判官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["藤花無次第，萬朵一時開。","不是周從事，何人喚我來。"]', '["藤花無次第，万朵一时开。","不是周從事，何人喚我来。"]', '诗', 'shi', '', NULL, '陳家紫藤花下贈周判官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('191fd21a-4102-4432-8ac9-78a11aefa5a9', '遊小洞庭', '游小洞庭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["湖山上頭別有湖，芰荷香氣占仙都。","夜含星斗分乾象，曉映雷雲作畫圖。","風動綠蘋天上浪，鳥棲寒照月中烏。","若非神物多靈迹，爭得長年冬不枯。"]', '["湖山上头別有湖，芰荷香氣占仙都。","夜含星斗分乾象，晓映雷云作畫圖。","风动綠蘋天上浪，鸟棲寒照月中烏。","若非神物多靈迹，爭得长年冬不枯。"]', '诗', 'shi', '', NULL, '遊小洞庭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5cda4df-3f0d-4e69-8db8-881d74542130', '傷蔡處士', '傷蔡处士', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["篋中遺草是琅玕，對此令人灑淚看。","三逕尚疑行迹在，數螢猶自映書殘。","晨光不借泉門曉，暝色空添隴樹寒。","欲問皇天天更遠，有才無命說應難。"]', '["篋中遺草是琅玕，对此令人灑泪看。","三逕尚疑行迹在，數螢猶自映书殘。","晨光不借泉门晓，暝色空添隴樹寒。","欲问皇天天更远，有才無命说應难。"]', '诗', 'shi', '', NULL, '傷蔡處士 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be061687-a553-48a3-b405-fcbcf685271b', '奉使過石門瀑布', '奉使過石门瀑布', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["溪上望懸泉，耿耿雲中見。","披榛上巖巘，絕壁正東面。","千仞瀉聯珠，一潭噴飛霰。","嵯灇滿山響，坐覺炎氛變。","照日類虹蜺，從風似綃練。","靈奇既天造，惜處窮海甸。","吾祖昔登臨，謝公亦遊衍。","王程懼淹泊，下磴空延眷。","千里雷尚聞，巒迴樹葱蒨。","奔波恭賤役，探討媿前彥。","永欲洗塵纓，終當愜茲願。"]', '["溪上望懸泉，耿耿云中见。","披榛上巖巘，絕壁正东面。","千仞瀉聯珠，一潭噴飞霰。","嵯灇满山响，坐覺炎氛变。","照日類虹蜺，從风似綃練。","靈奇既天造，惜处窮海甸。","吾祖昔登臨，謝公亦游衍。","王程懼淹泊，下磴空延眷。","千里雷尚闻，巒迴樹葱蒨。","奔波恭賤役，探討媿前彥。","永欲洗塵纓，終當愜茲願。"]', '诗', 'shi', '', NULL, '奉使過石門瀑布 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbbd77c2-3da9-451a-beef-7d1634974dc7', '秋夕宿石門館', '秋夕宿石门館', 'fef74ee3-6b39-40bc-9d31-939b46ffabe1', '唐', '["暝從石門宿，搖落四岩空。","潭月漾山足，天河瀉澗中。","杉松寒似雨，猨鳥夕驚風。","獨臥不成寐，蒼然想謝公。"]', '["暝從石门宿，搖落四岩空。","潭月漾山足，天河瀉澗中。","杉松寒似雨，猨鸟夕驚风。","独臥不成寐，蒼然想謝公。"]', '诗', 'shi', '', NULL, '秋夕宿石門館 丘丹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39de9ced-7a5e-46a3-b398-ca200e2ce4a7', '廬山瀑布', '廬山瀑布', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["誰將織女機頭練，貼出青山碧雲面。","造化工夫不等閑，剪破澄江凝一片。","怪來洞口流嗚咽，怕見三冬晝飛雪。","石鏡無光相對愁，漫漫頂上沈秋月。","爭得陽烏照山北，放出青天豁胸臆。","黛花新染插天風，驀吐中心爛銀色。","五月六月暑雲飛，閣門遠看澄心機。","參差碎碧落巖畔，梅花亂擺當風散。"]', '["誰將织女機头練，貼出青山碧云面。","造化工夫不等闲，剪破澄江凝一片。","怪来洞口流嗚咽，怕见三冬晝飞雪。","石镜無光相对愁，漫漫頂上沈秋月。","爭得陽烏照山北，放出青天豁胸臆。","黛花新染插天风，驀吐中心爛銀色。","五月六月暑云飞，閣门远看澄心機。","參差碎碧落巖畔，梅花亂擺當风散。"]', '诗', 'shi', '', NULL, '廬山瀑布 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a3811d5-8923-4c7b-84b4-30e71f349d34', '林書記薔薇', '林书記薔薇', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["東風折盡諸花卉，是箇亭臺冷如水。","黃鸝舌滑跳柳陰，教看薔薇吐金蘂。","雙成湧出琉璃宮，天香闊罩紅熏籠。","西施曉下吳王殿，亂拋嬌臉新勻濃。","瑤姬學繡流蘇幔，綠夾殷紅垂錦段。","炎洲吹落滿汀雲，阮瑀庭前裝一半。","醉且書懷還復吟，蜀箋影裏霞光侵。","秦娥晚憑欄干立，柔枝墜落青羅襟。","殷勤無波綠池水，爲君作鏡開妝蘂。"]', '["东风折尽諸花卉，是箇亭台冷如水。","黄鸝舌滑跳柳陰，教看薔薇吐金蘂。","雙成湧出琉璃宮，天香闊罩紅熏籠。","西施晓下吳王殿，亂拋嬌臉新勻濃。","瑤姬学繡流蘇幔，綠夾殷紅垂錦段。","炎洲吹落满汀云，阮瑀庭前裝一半。","醉且书懷還复吟，蜀箋影裏霞光侵。","秦娥晚憑欄干立，柔枝墜落青羅襟。","殷勤無波綠池水，爲君作镜开妝蘂。"]', '诗', 'shi', '', NULL, '林書記薔薇 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e57261cf-bfbb-4c00-ba23-e7d42e3fa0a8', '荅友人新栽松', '荅友人新栽松', '447738a7-2ba4-4b4c-8ab5-270ef7176194', '唐', '["石門新長青龍髯，虬身宛轉雲光粘。","聞君愛我幽崖前，十株五株寒霜天。","越溪老僧頭削雪，曾云手植當庭月。","三十年來遮火雲，涼風五月生空門。","願君栽於清澗泉，貞姿莫迓夭桃妍。","□□易開還易落，貞姿鬱鬱長依然。","山童嬾上孤峰巔，當窗劃破屏風煙。"]', '["石门新长青龙髯，虬身宛轉云光粘。","闻君愛我幽崖前，十株五株寒霜天。","越溪老僧头削雪，曾云手植當庭月。","三十年来遮火云，涼风五月生空门。","願君栽於清澗泉，貞姿莫迓夭桃妍。","□□易开還易落，貞姿鬱鬱长依然。","山童嬾上孤峰巔，當窗劃破屏风煙。"]', '诗', 'shi', '', NULL, '荅友人新栽松 張碧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ba1bb3f-6c11-4fc9-9b98-b71ff3b160bb', '金錢花 一', '金錢花 一', 'd057751c-99e7-4310-9451-7b03da50fe94', '唐', '["裊露牽風夾瘦莎，一星星火遍窠窠。","閑門永巷新秋裏，幸不傷廉莫怕多。"]', '["裊露牽风夾瘦莎，一星星火遍窠窠。","闲门永巷新秋裏，幸不傷廉莫怕多。"]', '诗', 'shi', '', NULL, '金錢花 一 陳翥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('976e872c-e05f-4cc7-ab77-45eca944bfde', '金錢花 二', '金錢花 二', 'd057751c-99e7-4310-9451-7b03da50fe94', '唐', '["古蘚寒蕪讓品流，小齋多謝伴清幽。","若教夷甫門前種，也是無多過一秋。"]', '["古蘚寒蕪讓品流，小斋多謝伴清幽。","若教夷甫门前種，也是無多過一秋。"]', '诗', 'shi', '', NULL, '金錢花 二 陳翥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5ab4bad-45b5-43da-b72a-b5b44dbd5a4f', '山居雨霽即事', '山居雨霽即事', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["結茅蒼嶺下，自與喧卑隔。","況值雷雨晴，郊原轉岑寂。","出門看反照，繞屋殘溜滴。","古路絕人行，荒陂響螻蟈。","籬崩瓜豆蔓，圃壤牛羊跡。","斷續古祠鴉，高低遠村笛。","喜聞東臯潤，欲往未通屐。","杖策試危橋，攀蘿瞰苔壁。","隣翁夜相訪，緩酌聊跂石。","新月出汙尊，浮雲在中舃。","常隳腐儒操，謬習經邦畫。","有待時未知，非關慕沮溺。"]', '["結茅蒼嶺下，自與喧卑隔。","況值雷雨晴，郊原轉岑寂。","出门看反照，繞屋殘溜滴。","古路絕人行，荒陂响螻蟈。","籬崩瓜豆蔓，圃壤牛羊跡。","斷續古祠鴉，高低远村笛。","喜闻东臯潤，欲往未通屐。","杖策試危橋，攀蘿瞰苔壁。","隣翁夜相訪，緩酌聊跂石。","新月出汙尊，浮云在中舃。","常隳腐儒操，謬習經邦畫。","有待时未知，非关慕沮溺。"]', '诗', 'shi', '', NULL, '山居雨霽即事 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1feef8a-fe93-4834-b360-57350f629835', '秋日登山', '秋日登山', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["逐勝不怯寒，秋山閑獨登。","依稀小徑通，深處逢來僧。","側右擁寒溜，欹松懸古藤。","明書問知友，興詠將誰能。"]', '["逐勝不怯寒，秋山闲独登。","依稀小徑通，深处逢来僧。","側右擁寒溜，欹松懸古藤。","明书问知友，兴詠將誰能。"]', '诗', 'shi', '', NULL, '秋日登山 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d1e429a-adbd-40c2-9986-0848c832d031', '自京師將赴黔南', '自京師將赴黔南', '9e971afd-0c44-4a2d-894a-584509609a84', '唐', '["風雨荆州二月天，問人須雇峽中船。","西南一望雲和水，猶道黔南有四千。"]', '["风雨荆州二月天，问人須雇峽中船。","西南一望云和水，猶道黔南有四千。"]', '诗', 'shi', '', NULL, '自京師將赴黔南 竇鞏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('426bdd3c-ea91-4ae3-92e8-24e838c33691', '中秋夜洞庭圓月', '中秋夜洞庭圓月', 'a99e9854-eb4d-4b8f-a6c4-f49575af1f39', '唐', '["素月閑秋景，騷人汎洞庭。","滄波正澄霽，涼葉未飄零。","練彩凝葭菼，霜容靜杳冥。","曉棲河畔鶴，宵映渚邊螢。","圓彩含珠魄，微颷發桂馨。","誰憐採蘋客，此夜宿孤汀。"]', '["素月闲秋景，騷人汎洞庭。","滄波正澄霽，涼葉未飄零。","練彩凝葭菼，霜容静杳冥。","晓棲河畔鹤，宵映渚邊螢。","圓彩含珠魄，微颷發桂馨。","誰怜採蘋客，此夜宿孤汀。"]', '诗', 'shi', '', NULL, '中秋夜洞庭圓月 姚合 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ddaa601-365c-48e4-b0c0-170c7bbc57c4', '濉陽行', '濉陽行', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["黃昏日暮驅羸馬，夜宿濉陽烽火下。","此地新經殺戮來，墟落無煙空碎瓦。","層冰塞斷隋朝水，一道銀河貫千里。","愁心翻覆夢難成，病僕呻吟呼不起。","泗水三千招義軍，本是征戰邀殊勳。","十年麾下蓄壯氣，一朝此地爲愁人。","昨日太陽回照燭，轉見天心重含育。","早晚東風的發生，古堤春草年年綠。"]', '["黄昏日暮驱羸马，夜宿濉陽烽火下。","此地新經殺戮来，墟落無煙空碎瓦。","層冰塞斷隋朝水，一道銀河貫千里。","愁心翻覆梦难成，病僕呻吟呼不起。","泗水三千招義軍，本是征戰邀殊勳。","十年麾下蓄壯氣，一朝此地爲愁人。","昨日太陽回照燭，轉见天心重含育。","早晚东风的發生，古堤春草年年綠。"]', '诗', 'shi', '', NULL, '濉陽行 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9843076-b322-477a-887b-8c3a71873c37', '六歎 一', '六歎 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["蓬萊島邊採珠客，西望人寰星漢隔。","千重疊浪聳雲高，萬里平沙連月白。","海中洞穴尋難極，水底鮫人半相識。","玄蚌初開影暫明，驪龍欲近威難逼。","辛苦風濤白首期，得珠却恨求珠時。","隋侯歿世幾千載，只今薄俗空嗤嗤。"]', '["蓬萊島邊採珠客，西望人寰星漢隔。","千重叠浪聳云高，万里平沙連月白。","海中洞穴尋难極，水底鮫人半相識。","玄蚌初开影暫明，驪龙欲近威难逼。","辛苦风濤白首期，得珠却恨求珠时。","隋侯歿世幾千載，只今薄俗空嗤嗤。"]', '诗', 'shi', '', NULL, '六歎 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eb655f9-6ca0-455c-bc57-691c78e1332f', '六歎 二', '六歎 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["燕王愛賢築金臺，四方豪俊承風來。","秦王燒書殺儒客，肘腋之中千里隔。","去年八月幽幷道，昭王陵邊哭秋草。","今年二月遊函關，秦家城外悲河山。","河上山邊車馬路，殘日青煙五陵樹。"]', '["燕王愛賢築金台，四方豪俊承风来。","秦王燒书殺儒客，肘腋之中千里隔。","去年八月幽幷道，昭王陵邊哭秋草。","今年二月游函关，秦家城外悲河山。","河上山邊车马路，殘日青煙五陵樹。"]', '诗', 'shi', '', NULL, '六歎 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5879ba8f-d2f0-42cd-8508-ef6cbc24311b', '六歎 三', '六歎 三', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["關東病儒客梁城，五歲十回逢亂兵。","燒人之家食人肉，狼虎熾心都未足。","城裏愁雲不開城，城頭野草春還綠。","五十餘年忠烈臣，臨難守節羞謀身。","堂上英髦沈白刃，門前輿隸乘朱輪。","千古傷心汴河水，陰天落日悲風起。"]', '["关东病儒客梁城，五歲十回逢亂兵。","燒人之家食人肉，狼虎熾心都未足。","城裏愁云不开城，城头野草春還綠。","五十餘年忠烈臣，臨难守節羞謀身。","堂上英髦沈白刃，门前輿隸乘朱輪。","千古傷心汴河水，陰天落日悲风起。"]', '诗', 'shi', '', NULL, '六歎 三 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f027cfa2-5835-4ab5-98f1-b4d851f4b0a3', '却歸巴陵途中走筆寄唐知言', '却归巴陵途中走笔寄唐知言', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["去年臘月來夏口，黑風白浪打頭吼。","櫓聲軋軋搖不前，看他撩亂張帆走。","逾月始到鸚鵡洲，嗚嗚暮角喧城頭。","逡巡未得見官長，夢寢但覺生愁憂。","軍中賢倅李監察，人馬曉來兼手札。","教令參謁禮數全，頭頭要處相稱掣。","唐氏一門今五龍，聲華殷殷皆如鍾。","就中十一最年少，別有俊氣橫心胸。","巧綴五言才刮骨，却怕柱天身硉矹。","後輩無勞續出頭，坳塘不合窺溟渤。","君家三兄舊山侶，方寸久來常許與。","不覺淹留兩月餘，風光漫爛生洲渚。","宇文文學儒家子，竹繞書齋花映水。","醉舞狂歌此地多，有時酩酊扶還起。","猥蒙方伯憐飢貧，假名許得陪諸賓。","酒家債負有填日，恣意頗敢排青緡。","余瞿二家同愛客，園蔬任遣奴人摘。","野狐泉頭銀葉方，一別十年今再覿。","更有風流歙奴子，能將盤帕來欺爾。","白馬青袍豁眼明，許他真是查郎髓。","良會芳時難再來，隟光電影長相催。","扁舟惆悵人南去，目斷江天凡幾回。"]', '["去年臘月来夏口，黑风白浪打头吼。","櫓声軋軋搖不前，看他撩亂張帆走。","逾月始到鸚鵡洲，嗚嗚暮角喧城头。","逡巡未得见官长，梦寢但覺生愁憂。","軍中賢倅李監察，人马晓来兼手札。","教令參謁禮數全，头头要处相稱掣。","唐氏一门今五龙，声华殷殷皆如鍾。","就中十一最年少，別有俊氣橫心胸。","巧綴五言才刮骨，却怕柱天身硉矹。","後輩無勞續出头，坳塘不合窺溟渤。","君家三兄旧山侶，方寸久来常許與。","不覺淹留兩月餘，风光漫爛生洲渚。","宇文文学儒家子，竹繞书斋花映水。","醉舞狂歌此地多，有时酩酊扶還起。","猥蒙方伯怜飢貧，假名許得陪諸賓。","酒家債負有填日，恣意頗敢排青緡。","余瞿二家同愛客，园蔬任遣奴人摘。","野狐泉头銀葉方，一別十年今再覿。","更有风流歙奴子，能將盤帕来欺爾。","白马青袍豁眼明，許他真是查郎髓。","良會芳时难再来，隟光電影长相催。","扁舟惆悵人南去，目斷江天凡幾回。"]', '诗', 'shi', '', NULL, '却歸巴陵途中走筆寄唐知言 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df521da7-8c6f-463c-88d9-973270c6353b', '山中五無奈何 一', '山中五無奈何 一', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["無奈落葉何，紛紛滿衰草。","疾來無氣力，擁戶不能掃。","欲訪雲外人，都迷上山道。"]', '["無奈落葉何，紛紛满衰草。","疾来無氣力，擁戶不能掃。","欲訪云外人，都迷上山道。"]', '诗', 'shi', '', NULL, '山中五無奈何 一 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17c029d2-2e54-4433-a2d9-ce5fe8a87a7c', '山中五無奈何 二', '山中五無奈何 二', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["無奈澗水何，喧喧夜鳴石。","疎林透斜月，散亂金光滴。","欲訪澗底人，路窮潭水碧。"]', '["無奈澗水何，喧喧夜鳴石。","疎林透斜月，散亂金光滴。","欲訪澗底人，路窮潭水碧。"]', '诗', 'shi', '', NULL, '山中五無奈何 二 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7815a25f-96b9-403f-9f3e-38158bbbfdc1', '山中五無奈何 三', '山中五無奈何 三', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["無奈阿鼎何，嬌啼索梨栗。","柴門正風雨，千向千回出。","欲識老病心，賴渠將過日。"]', '["無奈阿鼎何，嬌啼索梨栗。","柴门正风雨，千向千回出。","欲識老病心，賴渠將過日。"]', '诗', 'shi', '', NULL, '山中五無奈何 三 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72851b59-aa82-4519-96c9-3ba147dbd8d7', '山中五無奈何 四', '山中五無奈何 四', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["無奈梅花何，滿巖光似雪。","春風總未至，獨自驚時節。","欲見惆悵心，又看花上月。"]', '["無奈梅花何，满巖光似雪。","春风總未至，独自驚时節。","欲见惆悵心，又看花上月。"]', '诗', 'shi', '', NULL, '山中五無奈何 四 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3871d1f-d55e-4ad4-a278-ce4cb435c853', '江南雜題', '江南杂題', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["積潦池新漲，頹垣址舊高。","怒蛙橫飽腹，鬬雀墮輕毛。","碧瘦三稜草，紅鮮百葉桃。","幽棲日無事，痛飲讀離騷。"]', '["積潦池新漲，頹垣址旧高。","怒蛙橫飽腹，鬬雀墮轻毛。","碧瘦三稜草，紅鲜百葉桃。","幽棲日無事，痛饮读離騷。"]', '诗', 'shi', '', NULL, '江南雜題 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f33874-afc4-4647-85ee-644c4bcd1809', '賦得福州白竹扇子', '賦得福州白竹扇子', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["金泥小扇謾多情，未勝南工巧織成。","藤縷雪光纏柄滑，篾鋪銀薄露花輕。","清風坐向羅衫起，明月看從玉手生。","猶賴早時君不棄，每憐初作合歡名。"]', '["金泥小扇謾多情，未勝南工巧织成。","藤縷雪光纏柄滑，篾鋪銀薄露花轻。","清风坐向羅衫起，明月看從玉手生。","猶賴早时君不棄，每怜初作合歡名。"]', '诗', 'shi', '', NULL, '賦得福州白竹扇子 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a225f6f9-4416-4f5f-bbab-4e3b3bdf2c35', '潤州楊別駕宅送蔣侍御收兵歸揚州', '潤州楊別駕宅送蔣侍御收兵归揚州', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["冷氣清金虎，兵威壯鐵冠。","揚旌川色暗，吹角水風寒。","人對輜軿醉，花垂睥睨殘。","羨歸丞相閣，空望舊門闌。"]', '["冷氣清金虎，兵威壯鐵冠。","揚旌川色暗，吹角水风寒。","人对輜軿醉，花垂睥睨殘。","羨归丞相閣，空望旧门闌。"]', '诗', 'shi', '', NULL, '潤州楊別駕宅送蔣侍御收兵歸揚州 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42aa12e8-bb08-4d56-8c92-74d0c6e2fed0', '觀泗州李常侍打毬', '观泗州李常侍打毬', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["日出樹煙紅，開場畫鼓雄。","驟騎鞍上月，輕撥鐙前風。","斗轉時乘勢，旁捎乍迸空。","等來低背手，爭得旋分騣。","遠射門斜入，深排馬迥通。","遙知三殿下，長恨出征東。"]', '["日出樹煙紅，开場畫鼓雄。","驟騎鞍上月，轻撥鐙前风。","斗轉时乘勢，旁捎乍迸空。","等来低背手，爭得旋分騣。","远射门斜入，深排马迥通。","遙知三殿下，长恨出征东。"]', '诗', 'shi', '', NULL, '觀泗州李常侍打毬 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbf21aaa-abd4-46c2-87ce-ae4d154a14bd', '閑居', '闲居', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["僻巷新苔徧，空庭弱柳垂。","井欄防穉子，盆水試鵝兒。","喜客加籩食，邀僧長路棋。","未能拋世事，除此更何爲。"]', '["僻巷新苔徧，空庭弱柳垂。","井欄防穉子，盆水試鵝兒。","喜客加籩食，邀僧长路棋。","未能拋世事，除此更何爲。"]', '诗', 'shi', '', NULL, '閑居 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9515433-e5f5-40a4-b067-478ffa3d581c', '渡吳江', '渡吳江', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["堠館人稀夜更長，姑蘇城遠樹蒼蒼。","江湖潮落高樓迥，河漢秋歸廣殿涼。","月轉碧梧移鵲影，露低紅草溼螢光。","文園詩侶應多思，莫醉笙歌掩華堂。"]', '["堠館人稀夜更长，姑蘇城远樹蒼蒼。","江湖潮落高楼迥，河漢秋归廣殿涼。","月轉碧梧移鵲影，露低紅草溼螢光。","文园诗侶應多思，莫醉笙歌掩华堂。"]', '诗', 'shi', '', NULL, '渡吳江 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0acf4571-85be-4330-8ae5-666154f171de', '元日觀朝', '元日观朝', '1bb99cff-8449-44c8-8297-1e5eb119b959', '唐', '["玉座臨新歲，朝盈萬國人。","火連雙闕曉，仗列五門春。","瑞雪銷鴛瓦，祥光在日輪。","天顏不敢視，稱慶拜空頻。"]', '["玉座臨新歲，朝盈万国人。","火連雙闕晓，仗列五门春。","瑞雪銷鴛瓦，祥光在日輪。","天顏不敢視，稱慶拜空頻。"]', '诗', 'shi', '', NULL, '元日觀朝 厲玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceed3cc4-2014-4831-b1a8-009bee641541', '六月', '六月', 'af3be6c3-d696-439c-a8b2-645fd1962b79', '唐', '["六月火雲散，蟬聲鳴樹梢。","秋風豈便借，客思已蕭條。","傾國三年別，煙霞一路遙。","行人斷消息，更上灞陵橋。"]', '["六月火云散，蟬声鳴樹梢。","秋风豈便借，客思已蕭條。","傾国三年別，煙霞一路遙。","行人斷消息，更上灞陵橋。"]', '诗', 'shi', '', NULL, '六月 趙璜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52c6d58e-c308-4415-9562-f5862d8fd132', '樊川寒食', '樊川寒食', '59e0cb7b-2d9e-43bf-8b50-9a74e6b0c21d', '唐', '["新松□綠草，古柏翳黃沙。","珮珂客驚鳥，綺羅人間花。","蹙塵南北馬，碾石去來車。","川晚悲風動，墳前碎紙斜。"]', '["新松□綠草，古柏翳黄沙。","珮珂客驚鸟，綺羅人间花。","蹙塵南北马，碾石去来车。","川晚悲风动，墳前碎紙斜。"]', '诗', 'shi', '', NULL, '樊川寒食 喻鳧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef9c3012-c29a-440e-86da-53512b41035d', '芍藥', '芍藥', '228259f9-b158-4f88-84f2-342a02c03e2d', '唐', '["閑來竹亭賞，賞極蘂珠宮。","葉已盡餘翠，花纔半展紅。","媚欺桃李色，香奪綺羅風。","每到春殘日，芳華處處同。"]', '["闲来竹亭賞，賞極蘂珠宮。","葉已尽餘翠，花纔半展紅。","媚欺桃李色，香奪綺羅风。","每到春殘日，芳华处处同。"]', '诗', 'shi', '', NULL, '芍藥 潘咸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('871a889d-60ab-41d7-a393-1dd5d3d92c61', '晚步', '晚步', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["野步晚悠悠，山光澹早秋。","遠空淪日脚，多稼沒人頭。","古木蟬齊噪，深塍水慢流。","幽居迴不近，秋策却堪愁。"]', '["野步晚悠悠，山光澹早秋。","远空淪日脚，多稼沒人头。","古木蟬齊噪，深塍水慢流。","幽居迴不近，秋策却堪愁。"]', '诗', 'shi', '', NULL, '晚步 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed434a12-f7ae-4e98-8a1d-6197cbff0204', '村晚閑步', '村晚闲步', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["緩步出居處，過原邊雁行。","夕陽投草木，遠水迎蒼茫。","野寺同蟾宿，雲溪劚藥嘗。","蕭條霜景暮，極目盡堪傷。"]', '["緩步出居处，過原邊雁行。","夕陽投草木，远水迎蒼茫。","野寺同蟾宿，云溪劚藥嘗。","蕭條霜景暮，極目尽堪傷。"]', '诗', 'shi', '', NULL, '村晚閑步 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7222cde-b174-4c7d-b45a-3157bd43d4bb', '冬日題興善寺崔律師院孤松', '冬日題兴善寺崔律師院孤松', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["爲此疎名路，頻來訪遠松。","孤標宜雪後，每見憶山中。","靜影生幽蘚，寒聲入迥空。","何年植茲地，曉夕動清風。"]', '["爲此疎名路，頻来訪远松。","孤標宜雪後，每见憶山中。","静影生幽蘚，寒声入迥空。","何年植茲地，晓夕动清风。"]', '诗', 'shi', '', NULL, '冬日題興善寺崔律師院孤松 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f3b603c-5416-4095-a464-b81dbe6afa90', '題新栽小松', '題新栽小松', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["滿庭蕭颯皆凡木，豈得颼飀似石溪。","雪夜枝柯疑畫出，月中長短共人齊。","未知何日干天及，恐到秋來被鶴棲。","却向舊山尋得處，白雲根蕟覓應迷。"]', '["满庭蕭颯皆凡木，豈得颼飀似石溪。","雪夜枝柯疑畫出，月中长短共人齊。","未知何日干天及，恐到秋来被鹤棲。","却向旧山尋得处，白云根蕟覓應迷。"]', '诗', 'shi', '', NULL, '題新栽小松 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('414acb18-ca29-4858-91d7-3ee57709aa6d', '栽松', '栽松', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["翠色凜空庭，披衣獨繞行。","取從山頂嶮，栽得道心生。","未弱幽泉韻，焉論別木聲。","霜天殘月在，轉影入池清。"]', '["翠色凜空庭，披衣独繞行。","取從山頂嶮，栽得道心生。","未弱幽泉韻，焉論別木声。","霜天殘月在，轉影入池清。"]', '诗', 'shi', '', NULL, '栽松 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55d9235e-a7ee-466d-a351-1df8d2af5bcc', '十日菊', '十日菊', '4be8bf5c-85a3-4e8c-be58-7c36967a8629', '唐', '["昨日尊前折，萬人酣曉香。","今朝籬下見，滿地委殘陽。","得失片時痛，榮枯一歲傷。","未將同腐草，猶更有重霜。"]', '["昨日尊前折，万人酣晓香。","今朝籬下见，满地委殘陽。","得失片时痛，榮枯一歲傷。","未將同腐草，猶更有重霜。"]', '诗', 'shi', '', NULL, '十日菊 薛瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5c5919b-c47b-4045-a5bb-faaa5d368cb8', '赴南巴留別蘇臺知己', '赴南巴留別蘇台知己', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["人過梅嶺上，歲歲北風寒。","落日孤舟去，青山萬里看。","猿聲湘水靜，草色洞庭寬。","已料生涯事，只應持釣竿。"]', '["人過梅嶺上，歲歲北风寒。","落日孤舟去，青山万里看。","猿声湘水静，草色洞庭寬。","已料生涯事，只應持釣竿。"]', '诗', 'shi', '', NULL, '赴南巴留別蘇臺知己 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('319f58b1-8749-45a0-bf09-e0def1bce6ec', '紅薔薇', '紅薔薇', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["九天碎霞明澤國，造化工夫潛翦刻。","翠葉長眉約細枝，殷紅短刺鉤春色。","明日當樓晚香歇，金帶盤空已成結。","謝豹聲催麥隴秋，熏風吹落猩猩血。"]', '["九天碎霞明澤国，造化工夫潛翦刻。","翠葉长眉約細枝，殷紅短刺鉤春色。","明日當楼晚香歇，金带盤空已成結。","謝豹声催麦隴秋，熏风吹落猩猩血。"]', '诗', 'shi', '', NULL, '紅薔薇 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35b27368-84fb-4ab6-8c8b-23077b7c59aa', '曉歌', '晓歌', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["鵾雞哭樹星河轉，海上金烏翅如電。","嫦娥斂髮綰雲頭，玉女舒霞織天面。","九土廚煙滿城邑，商洛隴頭車馬急。","魏宮鐘動繡窗明，夢娥驚對殘燈立。"]', '["鵾雞哭樹星河轉，海上金烏翅如電。","嫦娥斂髮綰云头，玉女舒霞织天面。","九土廚煙满城邑，商洛隴头车马急。","魏宮鐘动繡窗明，梦娥驚对殘灯立。"]', '诗', 'shi', '', NULL, '曉歌 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e17a022-2f81-4918-a659-07277e090239', '春草歌', '春草歌', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["漠漠緜緜幾多思，無言領得春風意。","花裁小錦繡晴空，葉抽碧簟鋪平地。","含芳弔影爭芬敷，繞雲恨起山蘼蕪。","離人不忍到此處，淚娥滴盡雙真珠。"]', '["漠漠緜緜幾多思，無言領得春风意。","花裁小錦繡晴空，葉抽碧簟鋪平地。","含芳弔影爭芬敷，繞云恨起山蘼蕪。","離人不忍到此处，泪娥滴尽雙真珠。"]', '诗', 'shi', '', NULL, '春草歌 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4378eb3-eccc-4e4f-bd1a-ae62119da5b4', '古松歌', '古松歌', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["山上山下松，森沈翠蓋煙。","龜鱗犀甲鏁支體，泉聲雨脚洗春風。","深碧麈尾埽冥濛，淺黃龍腹盤穹崇。","拏天攫地數千尺，恐作雲雨歸維嵩。","維嵩成大廈，莫遣邂逅逢樵者。"]', '["山上山下松，森沈翠蓋煙。","龟鱗犀甲鏁支體，泉声雨脚洗春风。","深碧麈尾埽冥濛，淺黄龙腹盤穹崇。","拏天攫地數千尺，恐作云雨归維嵩。","維嵩成大廈，莫遣邂逅逢樵者。"]', '诗', 'shi', '', NULL, '古松歌 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e8554f0-330f-4a2c-a64b-bac4936a7e05', '蒲中霽後晚望', '蒲中霽後晚望', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["河邊霽色無人見，身帶春風立岸頭。","濁水茫茫有何意，日斜還向古蒲州。"]', '["河邊霽色無人见，身带春风立岸头。","濁水茫茫有何意，日斜還向古蒲州。"]', '诗', 'shi', '', NULL, '蒲中霽後晚望 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6373fcab-44e0-4dc2-8827-c8b49a7d9eb4', '龍門八韻', '龙门八韻', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["河浸華夷闊，山橫宇宙雄。","高波萬丈瀉，夏禹幾年功。","川迸晴明雨，林生旦暮風。","人看飜進退，鳥性斷西東。","氣逐雲歸海，聲驅石落空。","近身毛乍豎，當面語難通。","沸沫歸何處，盤渦傍此中。","從來化鬐者，攀去路應同。"]', '["河浸华夷闊，山橫宇宙雄。","高波万丈瀉，夏禹幾年功。","川迸晴明雨，林生旦暮风。","人看飜進退，鸟性斷西东。","氣逐云归海，声驱石落空。","近身毛乍豎，當面語难通。","沸沫归何处，盤渦傍此中。","從来化鬐者，攀去路應同。"]', '诗', 'shi', '', NULL, '龍門八韻 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cc61f10-7ce7-4b69-9408-4b34d6d2ce1c', '新雪', '新雪', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["細落麤和忽復繁，頓清朝市不聞喧。","天迷皓色風何亂，地溼春泥土半飜。","香暖會中懷岳寺，樵鳴村外想家園。","閑吟只愛煎茶澹，斡破平光向近軒。"]', '["細落麤和忽复繁，頓清朝市不闻喧。","天迷皓色风何亂，地溼春泥土半飜。","香暖會中懷岳寺，樵鳴村外想家园。","闲吟只愛煎茶澹，斡破平光向近軒。"]', '诗', 'shi', '', NULL, '新雪 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a513b19d-0c29-4963-91a4-cdde3b8f9a16', '送判官赴京', '送判官赴京', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["闕下情偏已絕稀，天涯身遠復相依。","庭花每對從容落，夜燭多同笑語歸。","君子是行應柏署，鄙人何望即柴扉。","青雲若遇交親話，白璧無心待發揮。"]', '["闕下情偏已絕稀，天涯身远复相依。","庭花每对從容落，夜燭多同笑語归。","君子是行應柏署，鄙人何望即柴扉。","青云若遇交親話，白璧無心待發揮。"]', '诗', 'shi', '', NULL, '送判官赴京 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de221824-f2ff-4b9f-9f9c-5dd137682ff3', '溪東岑望天都山', '溪东岑望天都山', 'a123599a-f84c-4f6e-9dba-e14ca9af644f', '唐', '["目望浮山丘，梯雲上東岑。","羣峰爭入冥，巉巉生太陰。","昔賢此升仙，結構窮聳深。","未曉日先照，當晝色半沈。","風泉雪霜飛，雲樹瓊玉林。","大道非閉隔，無路不可尋。","窺鏡澄夙慮，望壇起敬心。","一從呼子安，永絕金玉音。"]', '["目望浮山丘，梯云上东岑。","羣峰爭入冥，巉巉生太陰。","昔賢此升仙，結構窮聳深。","未晓日先照，當晝色半沈。","风泉雪霜飞，云樹瓊玉林。","大道非閉隔，無路不可尋。","窺镜澄夙慮，望壇起敬心。","一從呼子安，永絕金玉音。"]', '诗', 'shi', '', NULL, '溪東岑望天都山 朱景玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82e53ca2-fe2a-4d96-8efe-9801c5ad8485', '夜行次東關逢魏扶東歸', '夜行次东关逢魏扶东归', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["南北斷蓬飄，長亭酒一瓢。","殘雲歸太華，疏雨過中條。","樹色隨關[迥]，河聲入塞遙。","勞歌此分首，風急馬蕭蕭。"]', '["南北斷蓬飄，长亭酒一瓢。","殘云归太华，疏雨過中條。","樹色隨关[迥]，河声入塞遙。","勞歌此分首，风急马蕭蕭。"]', '诗', 'shi', '', NULL, '夜行次東關逢魏扶東歸 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6520edd-a6b1-4431-a712-8528c1743907', '南遊湘漢寄友人', '南游湘漢寄友人', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["南去遠三京，三湘五月行。","巴江雪水下，楚澤火雲生。","向野聊中飲，乘涼探暮程。","離懷不可說，已近峽猨聲。"]', '["南去远三京，三湘五月行。","巴江雪水下，楚澤火云生。","向野聊中饮，乘涼探暮程。","離懷不可说，已近峽猨声。"]', '诗', 'shi', '', NULL, '南遊湘漢寄友人 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6aa7dc7-141a-406a-ab6a-b54e9c38983d', '送劉山人歸洞庭', '送劉山人归洞庭', '19a6c4c6-187a-45a0-a6a4-c1764045b245', '唐', '["却共孤雲去，高眠最上峰。","半湖乘早月，中路入疏鐘。","秋盡蟲聲急，夜深山雨重。","當時同隱者，分得幾株松。"]', '["却共孤云去，高眠最上峰。","半湖乘早月，中路入疏鐘。","秋尽蟲声急，夜深山雨重。","當时同隐者，分得幾株松。"]', '诗', 'shi', '', NULL, '送劉山人歸洞庭 李頻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35664761-ba2b-4683-a89b-776ab02faa29', '早發', '早發', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["野店星河在，行人道路長。","孤燈憐宿處，斜月厭新裝。","草色多寒露，蟲聲似故鄉。","清秋無限恨，殘菊過重陽。"]', '["野店星河在，行人道路长。","孤灯怜宿处，斜月厭新裝。","草色多寒露，蟲声似故乡。","清秋無限恨，殘菊過重陽。"]', '诗', 'shi', '', NULL, '早發 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dead5b8d-a26c-4913-95e5-a9e97f6e1086', '題惠山', '題惠山', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["乳洞陰陰碧澗連，杉松六月冷無蟬。","黃昏飛盡白蝙蝠，茶火數星山寂然。"]', '["乳洞陰陰碧澗連，杉松六月冷無蟬。","黄昏飞尽白蝙蝠，茶火數星山寂然。"]', '诗', 'shi', '', NULL, '題惠山 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb82ffb-1125-442a-8582-dff8dae03409', '雨中看山榴落花', '雨中看山榴落花', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["山榴逼砌栽，山火一團開。","盡日風兼雨，春渠擁作堆。"]', '["山榴逼砌栽，山火一團开。","尽日风兼雨，春渠擁作堆。"]', '诗', 'shi', '', NULL, '雨中看山榴落花 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02a8f0aa-bf46-4acc-9c4b-5a31d8bd814b', '寄友人乞菊栽', '寄友人乞菊栽', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["藥闌經雨正堪鋤，白菊煩君乞數株。","潘岳賦中芳思在，陶潛籬下綠英無。","移來稍及蟬鳴樹，種罷長教酒滿壺。","□子成仙縱難學，九秋思看集鳩雛。"]', '["藥闌經雨正堪鋤，白菊煩君乞數株。","潘岳賦中芳思在，陶潛籬下綠英無。","移来稍及蟬鳴樹，種罷长教酒满壺。","□子成仙縱难学，九秋思看集鳩雛。"]', '诗', 'shi', '', NULL, '寄友人乞菊栽 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7e95170-7f3c-40ee-bf95-5102640c9bce', '江邊柳', '江邊柳', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["東風晴色挂闌干，眉葉初晴畏曉寒。","江上別筵終日有，綠條春在長應難。"]', '["东风晴色挂闌干，眉葉初晴畏晓寒。","江上別筵終日有，綠條春在长應难。"]', '诗', 'shi', '', NULL, '江邊柳 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac7a5fb5-609d-428f-9174-9637cf0d17ab', '鵝兒', '鵝兒', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["臘後閑行村舍邊，黃鵝清水真可憐。","何窮散亂隨新草，永日淹留在野田。","無事羣鳴遮水際，爭來引頸逼人前。","風吹楚澤蒹葭暮，看下寒溪逐去船。"]', '["臘後闲行村舍邊，黄鵝清水真可怜。","何窮散亂隨新草，永日淹留在野田。","無事羣鳴遮水際，爭来引頸逼人前。","风吹楚澤蒹葭暮，看下寒溪逐去船。"]', '诗', 'shi', '', NULL, '鵝兒 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd9961bd-d6d7-4cba-8638-a7edcab6e0c3', '酬友人春暮寄枳花茶', '酬友人春暮寄枳花茶', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["昨日東風吹枳花，酒醒春晚一甌茶。","如雲正護幽人壍，似雪纔分野老家。","金餅拍成和雨露，玉塵煎出照煙霞。","相如病渴今全校，不羨生臺白頸鵶。"]', '["昨日东风吹枳花，酒醒春晚一甌茶。","如云正護幽人壍，似雪纔分野老家。","金餅拍成和雨露，玉塵煎出照煙霞。","相如病渴今全校，不羨生台白頸鵶。"]', '诗', 'shi', '', NULL, '酬友人春暮寄枳花茶 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acf5e605-5d9c-45af-a257-b7a25601b8a6', '郢自街西醉歸馬鞭墜失崔員外起祕書知其闕用皆許見貽俄頃之間二信俱至短長堅重價不相饒輒抒短章仰酬珍錫', '郢自街西醉归马鞭墜失崔員外起祕书知其闕用皆許见貽俄頃之间二信俱至短长堅重價不相饒輒抒短章仰酬珍錫', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["蜀巖陰面冷冥冥，偃雪欺霜半露青。","銛刃翦裁多鵲媚，細鞘揮拂帶龍腥。","崖垂萬仞知無影，蘚漬千年合有靈。","蘭省貴寮蓬閣吏，一時緘贈到雲亭。"]', '["蜀巖陰面冷冥冥，偃雪欺霜半露青。","銛刃翦裁多鵲媚，細鞘揮拂带龙腥。","崖垂万仞知無影，蘚漬千年合有靈。","蘭省貴寮蓬閣吏，一时緘贈到云亭。"]', '诗', 'shi', '', NULL, '郢自街西醉歸馬鞭墜失崔員外起祕書知其闕用皆許見貽俄頃之間二信俱至短長堅重價不相饒輒抒短章仰酬珍錫 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e62e5fe8-0382-47a6-a291-0c56a1478ea1', '即目', '即目', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["自笑騰騰者，非憨又不狂。","何爲跧似鼠，而復怯於麞。","落拓無生計，伶俜戀酒鄉。","冥搜得詩窟，偶戰出文場。","愛雪愁冬盡，懷人覺夜長。","石樓多爽氣，檉案有餘香。","運去非關拙，時來不在忙。","平生兩閑暇，孤趣滿滄浪。"]', '["自笑腾腾者，非憨又不狂。","何爲跧似鼠，而复怯於麞。","落拓無生計，伶俜戀酒乡。","冥搜得诗窟，偶戰出文場。","愛雪愁冬尽，懷人覺夜长。","石楼多爽氣，檉案有餘香。","運去非关拙，时来不在忙。","平生兩闲暇，孤趣满滄浪。"]', '诗', 'shi', '', NULL, '即目 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e8a1da-421b-43c5-90b3-18c33068a99d', '羅敷東館亭下流泉云至前山擁咽經歲移時掬弄惆悵成章', '羅敷东館亭下流泉云至前山擁咽經歲移时掬弄惆悵成章', '1d1f8e7e-94f0-47db-b76f-d10f8155bfcc', '唐', '["看山亭下小鳴泉，嗚咽難通亦可憐。","惆悵無人爲疎鑿，擁愁含恨過年年。"]', '["看山亭下小鳴泉，嗚咽难通亦可怜。","惆悵無人爲疎鑿，擁愁含恨過年年。"]', '诗', 'shi', '', NULL, '羅敷東館亭下流泉云至前山擁咽經歲移時掬弄惆悵成章 李郢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44f774b5-c274-44b2-aaf9-d6c9ce935b08', '白櫻樹', '白櫻樹', '7f940d53-e264-49bd-a337-3678ea2c3e53', '唐', '["記得花開雪滿枝，和蠭和蝶帶花移。","如今花落遊蠭去，空作主人惆悵詩。"]', '["記得花开雪满枝，和蠭和蝶带花移。","如今花落游蠭去，空作主人惆悵诗。"]', '诗', 'shi', '', NULL, '白櫻樹 于武陵 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92ba21f6-3239-4371-99cb-6f1d8b48d042', '過南城縣麻姑山 一', '過南城縣麻姑山 一', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["似前如却玉堆堆，薄帶輕煙翠好裁。","斜倚兔鉤孤影伴，校低仙掌一頭來。","盤疑虎伏形難寫，展認龍拏勢未迴。","驚訝昔人曾羽化，此中爭不接瑤臺。"]', '["似前如却玉堆堆，薄带轻煙翠好裁。","斜倚兔鉤孤影伴，校低仙掌一头来。","盤疑虎伏形难寫，展認龙拏勢未迴。","驚訝昔人曾羽化，此中爭不接瑤台。"]', '诗', 'shi', '', NULL, '過南城縣麻姑山 一 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec08eaa0-9fa2-4b90-bbc6-a5ba88a33cc2', '過南城縣麻姑山 二', '過南城縣麻姑山 二', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["詩手難題畫手慙，淺青濃碧壘東南。","塵愁世界忙心在，霞伴神仙穩夢酣。","雨涕自悲看雪鬢，星冠無計整雲篸。","家風負荷須名宦，可惜千峰綠似藍。"]', '["诗手难題畫手慙，淺青濃碧壘东南。","塵愁世界忙心在，霞伴神仙穩梦酣。","雨涕自悲看雪鬢，星冠無計整云篸。","家风負荷須名宦，可惜千峰綠似藍。"]', '诗', 'shi', '', NULL, '過南城縣麻姑山 二 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89f1a52a-4e3a-4b6a-b340-b493c463a174', '過南城縣麻姑山 三', '過南城縣麻姑山 三', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["差煙危碧半斜暉，何代仙人此羽飛。","高袖鎮長寒柏暗，古祠時復彩雲歸。","紅塵鞭馬顏將換，碧落驂鸞意有違。","聲利繫身家繫念，今生辜負六銖衣。"]', '["差煙危碧半斜暉，何代仙人此羽飞。","高袖鎮长寒柏暗，古祠时复彩云归。","紅塵鞭马顏將換，碧落驂鸾意有違。","声利繫身家繫念，今生辜負六銖衣。"]', '诗', 'shi', '', NULL, '過南城縣麻姑山 三 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac93f193-f6ae-4d1d-abfc-6eb682bbc1e5', '和友人題僧院薔薇花三首 一', '和友人題僧院薔薇花三首 一', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["何人移得在蟬家，瑟瑟枝條簇簇霞。","爭那寂寥埋草暗，不勝惆悵舞風斜。","無緣影對金尊酒，可惜香和石鼎茶。","看取老僧齊物意，一般拋擲等凡花。"]', '["何人移得在蟬家，瑟瑟枝條簇簇霞。","爭那寂寥埋草暗，不勝惆悵舞风斜。","無緣影对金尊酒，可惜香和石鼎茶。","看取老僧齊物意，一般拋擲等凡花。"]', '诗', 'shi', '', NULL, '和友人題僧院薔薇花三首 一 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5483030a-9ba8-4922-a550-a84dd1efcf34', '和友人題僧院薔薇花三首 二', '和友人題僧院薔薇花三首 二', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["忍委芳心此地開，似霞顏色苦低迴。","風驚少女偷香去，雨認巫娥覓伴來。","今日獨憐僧院種，舊山曾映釣磯栽。","三清上客知惆悵，勸我春醪一兩杯。"]', '["忍委芳心此地开，似霞顏色苦低迴。","风驚少女偷香去，雨認巫娥覓伴来。","今日独怜僧院種，旧山曾映釣磯栽。","三清上客知惆悵，勸我春醪一兩杯。"]', '诗', 'shi', '', NULL, '和友人題僧院薔薇花三首 二 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd3dce37-6ef3-4432-80c7-129285757f03', '和友人題僧院薔薇花三首 三', '和友人題僧院薔薇花三首 三', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["露香如醉態如慵，斜壓危闌草色中。","試問更誰過野寺，無憀徒自舞春風。","蘭缸尚惜連明在，錦帳先愁入夏空。","一日幾回來又去，不能容易捨深紅。"]', '["露香如醉態如慵，斜壓危闌草色中。","試问更誰過野寺，無憀徒自舞春风。","蘭缸尚惜連明在，錦帳先愁入夏空。","一日幾回来又去，不能容易捨深紅。"]', '诗', 'shi', '', NULL, '和友人題僧院薔薇花三首 三 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b4bb9b3-be96-457a-a165-7c9b6ecd8855', '春晚泊船江村', '春晚泊船江村', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["芳草青青古渡頭，漁家住處暫維舟。","殘花半樹悄無語，細雨滿天風似愁。","家信不來春又晚，客程難盡水空流。","自憐愛失心期約，看取花時更遠遊。"]', '["芳草青青古渡头，漁家住处暫維舟。","殘花半樹悄無語，細雨满天风似愁。","家信不来春又晚，客程难尽水空流。","自怜愛失心期約，看取花时更远游。"]', '诗', 'shi', '', NULL, '春晚泊船江村 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd4e5787-2983-4015-ad8b-668a2840699f', '柳', '柳', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["風慢日遲遲，拖煙拂水時。","惹將千萬恨，繫在短長枝。","骨輭張郎瘦，腰輕楚女飢。","故園歸未得，多少斷腸思。"]', '["风慢日遲遲，拖煙拂水时。","惹將千万恨，繫在短长枝。","骨輭張郎瘦，腰轻楚女飢。","故园归未得，多少斷腸思。"]', '诗', 'shi', '', NULL, '柳 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77ebfaf5-af98-45fb-8c55-e6bd1a67645e', '蓮花', '蓮花', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["影欹晴浪勢欹煙，恨態緘言日抵年。","輕霧曉和香積飯，片紅時墮化人船。","人間有筆應難畫，雨後無塵更好憐。","何限斷腸名不得，倚風嬌怯醉腰偏。"]', '["影欹晴浪勢欹煙，恨態緘言日抵年。","轻霧晓和香積飯，片紅时墮化人船。","人间有笔應难畫，雨後無塵更好怜。","何限斷腸名不得，倚风嬌怯醉腰偏。"]', '诗', 'shi', '', NULL, '蓮花 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12e67396-6714-4909-89a0-0624e8267ff5', '殘蓮花 一', '殘蓮花 一', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["倚風無力減香時，涵露如啼臥翠池。","金谷樓前馬嵬下，世間殊色一般悲。"]', '["倚风無力減香时，涵露如啼臥翠池。","金谷楼前马嵬下，世间殊色一般悲。"]', '诗', 'shi', '', NULL, '殘蓮花 一 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c515586f-9611-4066-ba6c-139fdbbdf18e', '殘蓮花 二', '殘蓮花 二', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["不耐高風怕冷煙，瘦紅欹委倒青蓮。","無人解把無塵袖，盛取殘香盡日憐。"]', '["不耐高风怕冷煙，瘦紅欹委倒青蓮。","無人解把無塵袖，盛取殘香尽日怜。"]', '诗', 'shi', '', NULL, '殘蓮花 二 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2d21e07-2429-4977-aef6-3b2686ff2e0a', '惜蓮花', '惜蓮花', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["半塘前日染來紅，瘦盡金方昨夜風。","留樣最嗟無巧筆，護香誰爲惜熏籠。","緣停翠櫂沈吟看，忍使良波積漸空。","魂斷舊溪顦顇態，冷煙殘粉楚臺東。"]', '["半塘前日染来紅，瘦尽金方昨夜风。","留樣最嗟無巧笔，護香誰爲惜熏籠。","緣停翠櫂沈吟看，忍使良波積漸空。","魂斷旧溪顦顇態，冷煙殘粉楚台东。"]', '诗', 'shi', '', NULL, '惜蓮花 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a33da766-052b-46a4-a11d-53f95c81313e', '岳陽雲夢亭看蓮花', '岳陽云梦亭看蓮花', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["似醉如慵一水心，斜陽欲暝彩雲深。","清明月照羞無語，涼冷風吹勢不禁。","曾向楚臺和雨看，只於吳苑弄船尋。","當時爲汝題詩徧，此地依前泥苦吟。"]', '["似醉如慵一水心，斜陽欲暝彩云深。","清明月照羞無語，涼冷风吹勢不禁。","曾向楚台和雨看，只於吳苑弄船尋。","當时爲汝題诗徧，此地依前泥苦吟。"]', '诗', 'shi', '', NULL, '岳陽雲夢亭看蓮花 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07b6f498-0173-43bf-af5a-1fcb4191d486', '村路菊花', '村路菊花', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["褭風驚未定，溪影晚來寒。","不得重陽節，虛將滿把看。","神仙誰采掇，煙雨惜彫殘。","牧豎樵童看，應教愛爾難。"]', '["褭风驚未定，溪影晚来寒。","不得重陽節，虛將满把看。","神仙誰采掇，煙雨惜彫殘。","牧豎樵童看，應教愛爾难。"]', '诗', 'shi', '', NULL, '村路菊花 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d111d6f6-6e55-4b66-8755-a2325bacbcea', '題山驛新桐花', '題山驛新桐花', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["雨餘煙膩暖香浮，影暗斜陽古驛樓。","丹鳳總巢阿閣去，紫花空映楚雲愁。","堪憐翠蓋奇於畫，更惜芳庭冷似秋。","長日老春看落盡，野禽閑哢碧悠悠。"]', '["雨餘煙膩暖香浮，影暗斜陽古驛楼。","丹鳳總巢阿閣去，紫花空映楚云愁。","堪怜翠蓋奇於畫，更惜芳庭冷似秋。","长日老春看落尽，野禽闲哢碧悠悠。"]', '诗', 'shi', '', NULL, '題山驛新桐花 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e53fa388-3699-47c3-990c-c980650466f0', '山路木芙蓉', '山路木芙蓉', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["不向橫塘泥裏栽，兩株晴笑碧巖隈。","枉教絕世深紅色，只向深山僻處開。","萬里王孫應有恨，三年賈傅惜無才。","緣花更歎人間事，半日江邊悵望迴。"]', '["不向橫塘泥裏栽，兩株晴笑碧巖隈。","枉教絕世深紅色，只向深山僻处开。","万里王孫應有恨，三年賈傅惜無才。","緣花更歎人间事，半日江邊悵望迴。"]', '诗', 'shi', '', NULL, '山路木芙蓉 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3882103-1dc2-47c8-8703-3fcedc34659c', '新柳', '新柳', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["無情柔態任春催，似不勝風倚古臺。","多少去年今日恨，御溝顏色洞庭來。"]', '["無情柔態任春催，似不勝风倚古台。","多少去年今日恨，御溝顏色洞庭来。"]', '诗', 'shi', '', NULL, '新柳 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04feb050-cf39-4bd7-8adb-27234fe38924', '臨川見新柳', '臨川见新柳', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["不見江頭三四日，橋邊楊柳老金絲。","岸南岸北往來渡，帶雨帶煙深淺枝。","何處故鄉牽夢想，兩迴他國見榮衰。","汀州草色亦如此，愁殺遠人人不知。"]', '["不见江头三四日，橋邊楊柳老金絲。","岸南岸北往来渡，带雨带煙深淺枝。","何处故乡牽梦想，兩迴他国见榮衰。","汀州草色亦如此，愁殺远人人不知。"]', '诗', 'shi', '', NULL, '臨川見新柳 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14e82926-a0b7-41aa-894a-d4fbb025f561', '南陽見柳', '南陽见柳', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["夜來風入最高枝，罥斷愁腸幾尺絲。","楚塞曾吟煙午處，曲江長憶雪晴時。","金銜細轂縈迴岸，戍笛牛歌遠近陂。","還把舊年惆悵意，武安城下一吟詩。"]', '["夜来风入最高枝，罥斷愁腸幾尺絲。","楚塞曾吟煙午处，曲江长憶雪晴时。","金銜細轂縈迴岸，戍笛牛歌远近陂。","還把旧年惆悵意，武安城下一吟诗。"]', '诗', 'shi', '', NULL, '南陽見柳 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c6a476d-8adf-47ff-8925-90a07be79177', '別君山', '別君山', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["點空誇黛妬愁媚，何必浮來結夢思。","慙媿二年青翠色，惹窗黏枕伴吟詩。"]', '["点空誇黛妬愁媚，何必浮来結梦思。","慙媿二年青翠色，惹窗黏枕伴吟诗。"]', '诗', 'shi', '', NULL, '別君山 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1410c70b-634e-4b9f-9e52-ac3870992381', '宿壽安山陰館聞泉', '宿壽安山陰館闻泉', 'addde38b-de0f-453f-b9be-ef65ce9ea611', '唐', '["一支清急萬山來，穿竹喧飛破石苔。","夢在故鄉臨欲到，聲聞孤枕却驚迴。","多愁鬢髮余甘老，有限年光爾莫催。","綠憶舊遊相似處，月明山響子陵臺。"]', '["一支清急万山来，穿竹喧飞破石苔。","梦在故乡臨欲到，声闻孤枕却驚迴。","多愁鬢髮余甘老，有限年光爾莫催。","綠憶旧游相似处，月明山响子陵台。"]', '诗', 'shi', '', NULL, '宿壽安山陰館聞泉 崔櫓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('199f8b8b-f1ba-49fb-816e-87e790a1c04a', '共佳人守歲', '共佳人守歲', '3b2c2096-3e5b-471c-8a22-caffbfd46611', '唐', '["桂華窮北陸，荆豔作東鄰。","殘妝欲送曉，薄衣已迎春。","舉袖爭流雪，分歌競繞塵。","不應將共醉，年去遠催人。"]', '["桂华窮北陸，荆豔作东鄰。","殘妝欲送晓，薄衣已迎春。","舉袖爭流雪，分歌競繞塵。","不應將共醉，年去远催人。"]', '诗', 'shi', '', NULL, '共佳人守歲 劉綺莊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d617296-c22c-499c-8e6c-44862e5edd76', '櫻桃花', '櫻桃花', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["婀娜枝香拂酒壺，向陽疑是不融酥。","晚來嵬峨渾如醉，惟有春風獨自扶。"]', '["婀娜枝香拂酒壺，向陽疑是不融酥。","晚来嵬峨渾如醉，惟有春风独自扶。"]', '诗', 'shi', '', NULL, '櫻桃花 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04b0309c-d99a-4c3e-bc80-b41123f04d23', '夜看櫻桃花', '夜看櫻桃花', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["纖枝瑤月弄圓霜，半入鄰家半入牆。","劉阮不知人獨立，滿衣清露到明香。"]', '["纖枝瑤月弄圓霜，半入鄰家半入牆。","劉阮不知人独立，满衣清露到明香。"]', '诗', 'shi', '', NULL, '夜看櫻桃花 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7900e2d7-9966-4992-a6df-8a12cd327788', '詠白蓮 一', '詠白蓮 一', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["膩於瓊粉白於脂，京兆夫人未畫眉。","靜婉舞偷將動處，西施嚬效半開時。","通宵帶露妝難洗，盡日凌波步不移。","願作水仙無別意，年年圖與此花期。"]', '["膩於瓊粉白於脂，京兆夫人未畫眉。","静婉舞偷將动处，西施嚬效半开时。","通宵带露妝难洗，尽日凌波步不移。","願作水仙無別意，年年圖與此花期。"]', '诗', 'shi', '', NULL, '詠白蓮 一 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49fdebf2-d919-4606-b664-fae944e14dd0', '詠白蓮 二', '詠白蓮 二', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["細嗅深看暗斷腸，從今無意愛紅芳。","折來只合瓊爲客，把種應須玉甃塘。","向日但疑酥滴水，含風渾訝雪生香。","吳王臺下開多少，遙似西施上素妝。"]', '["細嗅深看暗斷腸，從今無意愛紅芳。","折来只合瓊爲客，把種應須玉甃塘。","向日但疑酥滴水，含风渾訝雪生香。","吳王台下开多少，遙似西施上素妝。"]', '诗', 'shi', '', NULL, '詠白蓮 二 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f57285b6-20aa-46df-bc85-509ccc81e436', '赤門堰白蓮花', '赤门堰白蓮花', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["縞帶與綸巾，輕舟漾赤門。","千迴紫萍岸，萬頃白蓮村。","荷露傾衣袖，松風入髻根。","瀟疎今若此，爭不盡餘尊。"]', '["縞带與綸巾，轻舟漾赤门。","千迴紫萍岸，万頃白蓮村。","荷露傾衣袖，松风入髻根。","瀟疎今若此，爭不尽餘尊。"]', '诗', 'shi', '', NULL, '赤門堰白蓮花 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a61a44d-3912-4d0c-b8d9-afbeacb7a2c1', '丙午歲旦', '丙午歲旦', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["雞報已判春，中年抱疾身。","曉催庭火暗，風帶寺幡新。","多慮無成事，空休是吉人。","梅花浮壽酒，莫笑又移巡。"]', '["雞報已判春，中年抱疾身。","晓催庭火暗，风带寺幡新。","多慮無成事，空休是吉人。","梅花浮壽酒，莫笑又移巡。"]', '诗', 'shi', '', NULL, '丙午歲旦 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bae79b26-196f-4ebf-8892-4ff4ef069bf0', '丁巳元日', '丁巳元日', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["稟朔華夷會，開春氣象生。","日隨行闕近，嶽爲壽觴晴。","作睿由稽古，昭仁事措刑。","上玄勞眷佑，高廟保忠貞。","星變當移幸，人心喜奉迎。","傳呼清御道，雪涕識臣誠。","鼎餁和方濟，台階潤欲平。","扶天咨協力，併日召延英。","金躍洪鑪動，雲驅衆蟄驚。","關中留王氣，席上縱奇兵。","累降搜賢詔，兼持進善旌。","短轅收驥步，直路發鵬程。","自乏匡時略，非沽矯俗名。","鶴籠何足獻，蝸舍別無營。","羸帶漳濱病，吟哀越客聲。","移居荒藥圃，耗志在棋枰。","醉忘身空老，書憐眼尚明。","偶能甘蹇分，豈是薄浮榮。","慮戒防微淺，□知近利輕。","獻陵三百里，寤寐禱時清。"]', '["稟朔华夷會，开春氣象生。","日隨行闕近，嶽爲壽觴晴。","作睿由稽古，昭仁事措刑。","上玄勞眷佑，高廟保忠貞。","星变當移幸，人心喜奉迎。","傳呼清御道，雪涕識臣誠。","鼎餁和方濟，台階潤欲平。","扶天咨協力，併日召延英。","金躍洪鑪动，云驱衆蟄驚。","关中留王氣，席上縱奇兵。","累降搜賢詔，兼持進善旌。","短轅收驥步，直路發鵬程。","自乏匡时略，非沽矯俗名。","鹤籠何足獻，蝸舍別無營。","羸带漳濱病，吟哀越客声。","移居荒藥圃，耗志在棋枰。","醉忘身空老，书怜眼尚明。","偶能甘蹇分，豈是薄浮榮。","慮戒防微淺，□知近利轻。","獻陵三百里，寤寐禱时清。"]', '诗', 'shi', '', NULL, '丁巳元日 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88894dbf-89df-4172-b7b6-79bc6c2b7756', '光啓三年人日逢鹿', '光啓三年人日逢鹿', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["浮世仍逢亂，安排賴佛書。","勞生中壽少，抱疾上昇疎。","日暖人逢鹿，園荒雪帶鋤。","知非今又過，蘧瑗最憐渠。"]', '["浮世仍逢亂，安排賴佛书。","勞生中壽少，抱疾上昇疎。","日暖人逢鹿，园荒雪带鋤。","知非今又過，蘧瑗最怜渠。"]', '诗', 'shi', '', NULL, '光啓三年人日逢鹿 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25413a3b-27ac-4baf-914f-110cff1ace46', '浙上重陽', '浙上重陽', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["登高唯北望，菊助可□明。","離恨初逢節，貧居只喜晴。","好文時可見，學稼老無成。","莫歎關山阻，何當不阻兵。"]', '["登高唯北望，菊助可□明。","離恨初逢節，貧居只喜晴。","好文时可见，学稼老無成。","莫歎关山阻，何當不阻兵。"]', '诗', 'shi', '', NULL, '浙上重陽 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8a88928-484f-414b-b7f0-b7c2bbda2e54', '乙巳歲愚春秋四十九辭疾拜章將免左掖重陽獨登上方', '乙巳歲愚春秋四十九辞疾拜章將免左掖重陽独登上方', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["雪鬢不禁鑷，知非又此年。","退居還有旨，榮路免妨賢。","落落鳴蛩鳥，晴霞度雁天。","自無佳節興，依舊菊籬邊。"]', '["雪鬢不禁鑷，知非又此年。","退居還有旨，榮路免妨賢。","落落鳴蛩鸟，晴霞度雁天。","自無佳節兴，依旧菊籬邊。"]', '诗', 'shi', '', NULL, '乙巳歲愚春秋四十九辭疾拜章將免左掖重陽獨登上方 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fcf1733-df8d-44bd-a5c3-d7c8f683d8bb', '重陽山居', '重陽山居', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["此身逃難入鄉關，八度重陽在舊山。","籬菊亂來成爛熳，家僮常得解登攀。","年隨曆日三分盡，醉伴浮生一片閑。","滿目秋光還似鏡，殷勤爲我照衰顏。"]', '["此身逃难入乡关，八度重陽在旧山。","籬菊亂来成爛熳，家僮常得解登攀。","年隨曆日三分尽，醉伴浮生一片闲。","满目秋光還似镜，殷勤爲我照衰顏。"]', '诗', 'shi', '', NULL, '重陽山居 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbe1c25c-21a7-48aa-9154-69dd7dabd12b', '旅中重陽', '旅中重陽', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["乘時爭路秪危身，經亂登高有幾人。","今歲節唯南至在，舊交墳向北邙新。","當歌共惜初筵樂，且健無辭後會頻。","莫道中冬猶有閏，蟾聲纔盡即青春。"]', '["乘时爭路秪危身，經亂登高有幾人。","今歲節唯南至在，旧交墳向北邙新。","當歌共惜初筵乐，且健無辞後會頻。","莫道中冬猶有閏，蟾声纔尽即青春。"]', '诗', 'shi', '', NULL, '旅中重陽 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54f75c8d-93cf-45b8-9bd2-58f98af28d4a', '南至日', '南至日', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["年年山□□來頻，莫強孤危競要津。","吉卦偶成開病眼，暖簷還葺寄羸身。","求仙自躁非無藥，報國當材別有人。","鬢髮堪傷白已遍，鏡中更待白眉新。"]', '["年年山□□来頻，莫強孤危競要津。","吉卦偶成开病眼，暖簷還葺寄羸身。","求仙自躁非無藥，報国當材別有人。","鬢髮堪傷白已遍，镜中更待白眉新。"]', '诗', 'shi', '', NULL, '南至日 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9c043cb-25d3-457f-9d6e-2be124ef1343', '五月九日', '五月九日', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["金石皆銷鑠，賢愚共網羅。","達從詩似偈，狂覺哭勝歌。","高燕凌鴻鵠，枯槎壓芰荷。","此中無別境，此外是閑魔。"]', '["金石皆銷鑠，賢愚共網羅。","達從诗似偈，狂覺哭勝歌。","高燕凌鴻鵠，枯槎壓芰荷。","此中無別境，此外是闲魔。"]', '诗', 'shi', '', NULL, '五月九日 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfd7a71-262c-4bff-91e6-af8743221f7a', '庚子臘月五日', '庚子臘月五日', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["複道朝延火，嚴城夜漲塵。","驊騮思故第，鸚鵡失佳人。","禁漏虛傳點，妖星不振辰。","何當迴萬乘，重覩玉京春。"]', '["複道朝延火，嚴城夜漲塵。","驊騮思故第，鸚鵡失佳人。","禁漏虛傳点，妖星不振辰。","何當迴万乘，重覩玉京春。"]', '诗', 'shi', '', NULL, '庚子臘月五日 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91405a89-5ea6-477e-a7e1-2b4e9e73e24b', '中元夜看月', '中元夜看月', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["朦朧南溟月，洶湧出雲濤。","下射長鯨眼，遙分玉兔毫。","勢來牛斗動，路越宵冥高。","竟夕瞻光影，昂頭把白醪。"]', '["朦朧南溟月，洶湧出云濤。","下射长鯨眼，遙分玉兔毫。","勢来牛斗动，路越宵冥高。","竟夕瞻光影，昂头把白醪。"]', '诗', 'shi', '', NULL, '中元夜看月 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80619ed1-d661-4426-a948-60a609f09bdf', '木蘭', '木蘭', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["衆花搖落正無憀，脉脉芳叢契後凋。","舒卷綠苞臨小檻，剪裁檀的綴長條。","獨當春盡情何限，尚有秋期別未遙。","桃葉近來消息絕，見君長憶渡江橈。"]', '["衆花搖落正無憀，脉脉芳叢契後凋。","舒卷綠苞臨小檻，剪裁檀的綴长條。","独當春尽情何限，尚有秋期別未遙。","桃葉近来消息絕，见君长憶渡江橈。"]', '诗', 'shi', '', NULL, '木蘭 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('025bf33a-51b2-4cde-b715-3e4d5227148b', '玉蘂', '玉蘂', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["玉蘂兩高樹，相輝松桂旁。","向來塵不雜，此夜月仍光。","秀掩叢蘭色，豔吞穠李芳。","世人嫌具美，何必更清香。"]', '["玉蘂兩高樹，相輝松桂旁。","向来塵不杂，此夜月仍光。","秀掩叢蘭色，豔吞穠李芳。","世人嫌具美，何必更清香。"]', '诗', 'shi', '', NULL, '玉蘂 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f3f3d29-1d7f-4ce9-958c-f9605074f241', '蓮', '蓮', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["新蓮映多浦，迢遞綠塘東。","靜影搖波日，寒香映水風。","金塵飄落蘂，玉露洗殘紅。","看著餘芳少，無人問的中。"]', '["新蓮映多浦，迢遞綠塘东。","静影搖波日，寒香映水风。","金塵飄落蘂，玉露洗殘紅。","看著餘芳少，無人问的中。"]', '诗', 'shi', '', NULL, '蓮 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac902494-d395-4db4-b7aa-c56c9a798176', '望岳時賊據華夏', '望岳时賊據华夏', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["長路風埃隔楚氛，忽驚神岳映朝曛。","削成絕壁五千仞，高揖泥金七十君。","祝史祕辭今莫睹，從臣嘉頌久無聞。","幽人閑望封中地，好爲吾皇起白雲。"]', '["长路风埃隔楚氛，忽驚神岳映朝曛。","削成絕壁五千仞，高揖泥金七十君。","祝史祕辞今莫睹，從臣嘉頌久無闻。","幽人闲望封中地，好爲吾皇起白云。"]', '诗', 'shi', '', NULL, '望岳時賊據華夏 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e93fb3e-f73e-4246-a816-676b2104a4d7', '片石', '片石', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["小齋廬阜石，寄自沃洲僧。","山客勞攜笈，幽人自得朋。","瘦雲低作段，野浪凍成雲。","便可同清話，何須有物憑。"]', '["小斋廬阜石，寄自沃洲僧。","山客勞携笈，幽人自得朋。","瘦云低作段，野浪凍成云。","便可同清話，何須有物憑。"]', '诗', 'shi', '', NULL, '片石 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1072facc-8762-4f5b-b251-97ac0ed97b97', '柳', '柳', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["春風向楊柳，能事盡風流。","有意疑張緒，無情見莫愁。","依然金谷在，寧免武昌偷。","前路難回首，何須苦映樓。"]', '["春风向楊柳，能事尽风流。","有意疑張緒，無情见莫愁。","依然金谷在，寧免武昌偷。","前路难回首，何須苦映楼。"]', '诗', 'shi', '', NULL, '柳 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88b18923-dbcf-4ae0-9f7e-4e8e6cb447a9', '垂柳', '垂柳', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["垂柳碧髯茸，樓昏帶雨容。","思量成晝夢，來去發春慵。","梳洗憑張敞，乘騎笑稚恭。","碧虛從轉笠，紅燭近高舂。","怨臉明秋水，愁眉淡遠峰。","小園花盡蝶，靜院酒醒蛩。","舊作琴臺鳳，今爲藥店龍。","寶奩拋擲久，一任景陽鐘。"]', '["垂柳碧髯茸，楼昏带雨容。","思量成晝梦，来去發春慵。","梳洗憑張敞，乘騎笑稚恭。","碧虛從轉笠，紅燭近高舂。","怨臉明秋水，愁眉淡远峰。","小园花尽蝶，静院酒醒蛩。","旧作琴台鳳，今爲藥店龙。","寶奩拋擲久，一任景陽鐘。"]', '诗', 'shi', '', NULL, '垂柳 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27568442-ae4b-48e0-85f5-76178c789d41', '紫薇花', '紫薇花', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["素秋寒露重，芳事固應稀。","小檻臨清沼，高叢見紫薇。","溫{麻/昷}終有思，暗淡豈無輝。","見欲迷交甫，誰能狀宓妃。","妝新猶倚鏡，步緩不勝衣。","怳似新相得，倀如久未歸。","又疑神女過，猶佩七香幃。","還似星娥織，初臨五綵機。","慶雲今已集，威鳳莫驚飛。","綺筆題難盡，煩君白玉徽。"]', '["素秋寒露重，芳事固應稀。","小檻臨清沼，高叢见紫薇。","溫{麻/昷}終有思，暗淡豈無輝。","见欲迷交甫，誰能狀宓妃。","妝新猶倚镜，步緩不勝衣。","怳似新相得，倀如久未归。","又疑神女過，猶佩七香幃。","還似星娥织，初臨五綵機。","慶云今已集，威鳳莫驚飞。","綺笔題难尽，煩君白玉徽。"]', '诗', 'shi', '', NULL, '紫薇花 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07620551-b361-473b-8437-8263268d26af', '望中條', '望中條', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["虞鄉縣西郭，改觀揖中條。","第蓄終南小，交□□□遙。","崦深應有寺，峰近恐通橋。","爲語前村叟，他時寄採樵。"]', '["虞乡縣西郭，改观揖中條。","第蓄終南小，交□□□遙。","崦深應有寺，峰近恐通橋。","爲語前村叟，他时寄採樵。"]', '诗', 'shi', '', NULL, '望中條 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('178757c8-beed-4bb4-a25b-5fa981136791', '蒙穀山', '蒙穀山', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["蒙穀山低碧海枯，仲君閑坐說麻姑。","遙天鶴語知虛實，長夜神光竟有無。","祕祝齋心開九轉，侍臣回首聽三呼。","交朋漫信文成術，短燭瑤壇漏滿壺。"]', '["蒙穀山低碧海枯，仲君闲坐说麻姑。","遙天鹤語知虛實，长夜神光竟有無。","祕祝斋心开九轉，侍臣回首听三呼。","交朋漫信文成術，短燭瑤壇漏满壺。"]', '诗', 'shi', '', NULL, '蒙穀山 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40373389-a5f9-4980-b68e-9d67637bca03', '菊', '菊', '4d8119db-52b8-4403-a93e-37aa69d4ee61', '唐', '["雪菊金英兩斷腸，蝶翎蜂鼻帶清香。","寒村宿霧臨幽徑，廢苑斜暉傍短牆。","近取松筠爲伴侶，遠將桃李作參商。","年來病肺疎杯酒，每憶龍山似故鄉。"]', '["雪菊金英兩斷腸，蝶翎蜂鼻带清香。","寒村宿霧臨幽徑，廢苑斜暉傍短牆。","近取松筠爲伴侶，远將桃李作參商。","年来病肺疎杯酒，每憶龙山似故乡。"]', '诗', 'shi', '', NULL, '菊 唐彥謙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('871b5fee-cdee-4f3f-9daa-10364b261d59', '山中', '山中', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["愛山却把圖書賣，嗜酒空教僮僕賒。","秪向堦前便漁釣，那知枕上有雲霞。","暗泉出石飛仍咽，小徑通橋直復斜。","窗竹未抽今夏笋，庭梅曾試當年花。","姓名未及陶弘景，髭鬢白於姜子牙。","松月水煙千古在，未知終久屬誰家。"]', '["愛山却把圖书賣，嗜酒空教僮僕賒。","秪向堦前便漁釣，那知枕上有云霞。","暗泉出石飞仍咽，小徑通橋直复斜。","窗竹未抽今夏笋，庭梅曾試當年花。","姓名未及陶弘景，髭鬢白於姜子牙。","松月水煙千古在，未知終久屬誰家。"]', '诗', 'shi', '', NULL, '山中 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0257e28b-b434-45e5-91e2-3903e6d9ef98', '次韻和盧先輩避難寺居看牡丹', '次韻和盧先輩避难寺居看牡丹', '9a23bff2-b883-4702-bb77-a8084c235acb', '唐', '["亂後寄僧居，看花恨有餘。","香宜閑靜立，態似別離初。","朵密紅相照，欄低畫不如。","狂風任吹却，最共野人疎。"]', '["亂後寄僧居，看花恨有餘。","香宜闲静立，態似別離初。","朵密紅相照，欄低畫不如。","狂风任吹却，最共野人疎。"]', '诗', 'shi', '', NULL, '次韻和盧先輩避難寺居看牡丹 王駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3357800-9021-4647-a0a0-98499a0ee3c5', '春宮怨', '春宮怨', 'f1dea1de-2c32-4a70-9702-0689730a2812', '唐', '["早被嬋娟誤，欲妝臨鏡慵。","承恩不在貌，教妾若爲容。","風暖鳥聲碎，日高花影重。","年年越溪女，相憶採芙蓉。"]', '["早被嬋娟誤，欲妝臨镜慵。","承恩不在貌，教妾若爲容。","风暖鸟声碎，日高花影重。","年年越溪女，相憶採芙蓉。"]', '诗', 'shi', '', NULL, '春宮怨 杜荀鶴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e52c82b-81d5-466c-b839-2d958224db4b', '晨興', '晨兴', '5f210ba1-2a65-4f2e-a78c-3415c04c103c', '唐', '["鼓絕天街冷霧收，曉來風景已堪愁。","槐無顏色因經雨，菊有精神爲傍秋。","自愛鮮飆生戶外，不教閑事住心頭。","披襟徐步一蕭灑，吟繞盆池想狎鷗。"]', '["鼓絕天街冷霧收，晓来风景已堪愁。","槐無顏色因經雨，菊有精神爲傍秋。","自愛鲜飆生戶外，不教闲事住心头。","披襟徐步一蕭灑，吟繞盆池想狎鷗。"]', '诗', 'shi', '', NULL, '晨興 翁承贊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e799ab8-8e5f-4108-b14b-1fe6a8d29199', '江上吟曉', '江上吟晓', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["一葉野人舟，長將載酒游。","夜來吟思苦，江上月華秋。","曉露滿紅蓼，輕波颺白鷗。","漁翁似有約，相伴釣中流。"]', '["一葉野人舟，长將載酒游。","夜来吟思苦，江上月华秋。","晓露满紅蓼，轻波颺白鷗。","漁翁似有約，相伴釣中流。"]', '诗', 'shi', '', NULL, '江上吟曉 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0c2efec-e03e-4b50-9464-56fa4d1007f6', '過商山', '過商山', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["一宿白雲根，時經採麝村。","數峰雖似蜀，當晝不聞猨。","馬立溪沙淺，人爭閣道喧。","明朝棄襦罷，步步入金門。"]', '["一宿白云根，时經採麝村。","數峰雖似蜀，當晝不闻猨。","马立溪沙淺，人爭閣道喧。","明朝棄襦罷，步步入金门。"]', '诗', 'shi', '', NULL, '過商山 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55a63627-887e-44ed-be31-9cd80a032980', '泛鏡湖□□', '泛镜湖□□', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["我泛鏡湖日，未生千里蓴。","時無賀賓客，誰識謫仙人。","吟對四時雪，憶遊三島春。","惡聞忘越事，洗耳大江濱。"]', '["我泛镜湖日，未生千里蓴。","时無賀賓客，誰識謫仙人。","吟对四时雪，憶游三島春。","惡闻忘越事，洗耳大江濱。"]', '诗', 'shi', '', NULL, '泛鏡湖□□ 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1896a1b0-46a8-4a13-b98f-312b4b6ab3a1', '太湖石', '太湖石', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["誰憐孤峭質，移在太湖心。","出得風波外，任他池館深。","不同花逞豔，多媿竹垂陰。","一片至堅操，那憂歲月侵。"]', '["誰怜孤峭質，移在太湖心。","出得风波外，任他池館深。","不同花逞豔，多媿竹垂陰。","一片至堅操，那憂歲月侵。"]', '诗', 'shi', '', NULL, '太湖石 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcd00f7f-4490-4824-b084-738fead5d453', '依韻和幹公題庭中太湖石二首 一', '依韻和幹公題庭中太湖石二首 一', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["山立秪盈尋，高奇藥圃陰。","風濤打欲醉，巖穴蟄方深。","蘚點晴偏綠，蛩藏曉競吟。","歲寒終不變，堪比古人心。"]', '["山立秪盈尋，高奇藥圃陰。","风濤打欲醉，巖穴蟄方深。","蘚点晴偏綠，蛩藏晓競吟。","歲寒終不变，堪比古人心。"]', '诗', 'shi', '', NULL, '依韻和幹公題庭中太湖石二首 一 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c148b4a9-fe32-4013-9fd1-14bf8e2a9c17', '依韻和幹公題庭中太湖石二首 二', '依韻和幹公題庭中太湖石二首 二', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["徒勞水府尋，宛在玉堂陰。","蘭圃安雖窄，盆池映轉深。","山僧來盡愛，詩客見先吟。","若是買花者，年年不計心。"]', '["徒勞水府尋，宛在玉堂陰。","蘭圃安雖窄，盆池映轉深。","山僧来尽愛，诗客见先吟。","若是買花者，年年不計心。"]', '诗', 'shi', '', NULL, '依韻和幹公題庭中太湖石二首 二 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9651e406-f65e-497f-8d43-bcac9256a7c8', '書陶潛醉石', '书陶潛醉石', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["片石陶真性，非爲麴糵昏。","爭如累月醉，不笑獨醒人。","積疊莓苔色，交加薜荔根。","至今重九日，猶待白衣魂。"]', '["片石陶真性，非爲麴糵昏。","爭如累月醉，不笑独醒人。","積叠莓苔色，交加薜荔根。","至今重九日，猶待白衣魂。"]', '诗', 'shi', '', NULL, '書陶潛醉石 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb49fe0d-4821-4c48-a141-d58c08cbfab0', '看天王院牡丹', '看天王院牡丹', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["前年帝里探春時，寺寺名花我盡知。","今日長安已灰燼，忍隨南國對芳枝。"]', '["前年帝里探春时，寺寺名花我尽知。","今日长安已灰燼，忍隨南国对芳枝。"]', '诗', 'shi', '', NULL, '看天王院牡丹 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad91ac6c-72ab-4499-afd3-9a0535d249a2', '芍藥', '芍藥', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["芍藥承春寵，何曾羨牡丹。","麥秋能幾日，穀雨只微寒。","妬態風頻起，嬌妝露欲殘。","芙蓉浣紗伴，長恨隔波瀾。"]', '["芍藥承春寵，何曾羨牡丹。","麦秋能幾日，穀雨只微寒。","妬態风頻起，嬌妝露欲殘。","芙蓉浣紗伴，长恨隔波瀾。"]', '诗', 'shi', '', NULL, '芍藥 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('968a855c-69e4-4f7b-88b5-8f8615ac99ba', '獨芙蓉', '独芙蓉', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["方塘清曉鏡，獨照玉容秋。","蠹芰不相採，歛蘋空自愁。","日斜還顧影，風起強垂頭。","芳意羨何物，雙雙鸂鶒游。"]', '["方塘清晓镜，独照玉容秋。","蠹芰不相採，歛蘋空自愁。","日斜還顧影，风起強垂头。","芳意羨何物，雙雙鸂鶒游。"]', '诗', 'shi', '', NULL, '獨芙蓉 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6f059a4-bbb7-4ade-a357-43f1b2115ac4', '馮氏書齋小松二首 一', '馮氏书斋小松二首 一', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["孤根生遠岳，移植翠枝添。","自秉雪霜操，任他蜂蝶嫌。","微陰連迥竹，清韻入疎簾。","聳勢即空碧，時人看莫厭。"]', '["孤根生远岳，移植翠枝添。","自秉雪霜操，任他蜂蝶嫌。","微陰連迥竹，清韻入疎簾。","聳勢即空碧，时人看莫厭。"]', '诗', 'shi', '', NULL, '馮氏書齋小松二首 一 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2d5db22-28a2-4cce-997b-21327002f573', '馮氏書齋小松二首 二', '馮氏书斋小松二首 二', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["得地已經歲，清音晝夜聞。","根涵舊山土，葉間近溪雲。","野鶴望長遠，庭花笑不羣。","須知搖落後，衆木始能分。"]', '["得地已經歲，清音晝夜闻。","根涵旧山土，葉间近溪云。","野鹤望长远，庭花笑不羣。","須知搖落後，衆木始能分。"]', '诗', 'shi', '', NULL, '馮氏書齋小松二首 二 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fecbde8f-50e3-463c-9d91-d6d1ad5c6385', '社日村居', '社日村居', '4877a957-dc0d-4443-84f2-e824145f6295', '唐', '["鵝湖山下稻粱肥，㹠穽雞棲對掩扉。","桑柘影斜春社散，家家扶得醉人歸。"]', '["鵝湖山下稻粱肥，㹠穽雞棲对掩扉。","桑柘影斜春社散，家家扶得醉人归。"]', '诗', 'shi', '', NULL, '社日村居 張蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7792bce-f546-495b-95e7-65944f0fe279', '八月十六夜月', '八月十六夜月', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["十六勝三五，中天照大荒。","秪訛些子緣，應號沒多光。","桂老猶全在，蟾深未煞忙。","難期一年事，到曉泥詩章。"]', '["十六勝三五，中天照大荒。","秪訛些子緣，應號沒多光。","桂老猶全在，蟾深未煞忙。","难期一年事，到晓泥诗章。"]', '诗', 'shi', '', NULL, '八月十六夜月 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f03fa4bb-c159-48c2-89cf-f1b232e688fa', '冬除夜書情', '冬除夜书情', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["兀兀坐無味，思量誰與隣。","數星深夜火，一箇遠鄉人。","雁翥天微雪，風號樹欲春。","愁章自難過，不覺苦吟頻。"]', '["兀兀坐無味，思量誰與隣。","數星深夜火，一箇远乡人。","雁翥天微雪，风號樹欲春。","愁章自难過，不覺苦吟頻。"]', '诗', 'shi', '', NULL, '冬除夜書情 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9db0a533-e9f9-4381-8d27-436ae3d4c10f', '觀新歲朝賀', '观新歲朝賀', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["龍墀初立仗，鴛鷺列班行。","元日燕脂色，朝天樺燭香。","表章堆玉案，繒帛滿牙牀。","三百年如此，無因及我唐。"]', '["龙墀初立仗，鴛鷺列班行。","元日燕脂色，朝天樺燭香。","表章堆玉案，繒帛满牙牀。","三百年如此，無因及我唐。"]', '诗', 'shi', '', NULL, '觀新歲朝賀 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ccba4e-0409-4160-b4ed-69adeefd081c', '中秋月', '中秋月', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["九十日秋色，今秋已十分。","孤光吞列宿，四面絕微雲。","衆木排疎影，寒流疊細紋。","遙遙望丹桂，心緒更紛紛。"]', '["九十日秋色，今秋已十分。","孤光吞列宿，四面絕微云。","衆木排疎影，寒流叠細紋。","遙遙望丹桂，心緒更紛紛。"]', '诗', 'shi', '', NULL, '中秋月 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aa527eb-6fdf-4c06-9118-4f50eab6cdd0', '寄方干', '寄方干', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["桐廬江水閑，終日對柴關。","因想別離處，不知多少山。","釣舟春岸闊，庭樹晚煙還。","莫便求棲隱，桂枝堪恨顏。"]', '["桐廬江水闲，終日对柴关。","因想別離处，不知多少山。","釣舟春岸闊，庭樹晚煙還。","莫便求棲隐，桂枝堪恨顏。"]', '诗', 'shi', '', NULL, '寄方干 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6a1cfef-8699-4193-8dbf-f57d688dbd46', '宿山寺', '宿山寺', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["溪山盡日行，方聽遠鐘聲。","入院逢僧定，登樓見月生。","露垂羣木潤，泉落一巖清。","此景關吾事，通宵寐不成。"]', '["溪山尽日行，方听远鐘声。","入院逢僧定，登楼见月生。","露垂羣木潤，泉落一巖清。","此景关吾事，通宵寐不成。"]', '诗', 'shi', '', NULL, '宿山寺 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9852e74-691d-4e2b-b767-2041ac73e722', '冬日登江樓', '冬日登江楼', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["高樓臨古岸，野步晚來登。","江水因寒落，山雲爲雪凝。","遠村雖入望，危檻不堪凭。","親老未歸去，鄉愁徒自興。"]', '["高楼臨古岸，野步晚来登。","江水因寒落，山云爲雪凝。","远村雖入望，危檻不堪凭。","親老未归去，乡愁徒自兴。"]', '诗', 'shi', '', NULL, '冬日登江樓 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af9c79ca-fdd7-402f-9c4a-7053969e2ed6', '寄李處士', '寄李处士', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["僧話磻溪叟，平生重赤松。","夜堂悲蟋蟀，秋水老芙蓉。","吟坐倦垂釣，閑行多倚筇。","聞名來已久，未得一相逢。","塔見移來影，鐘聞過去聲。","一齋唯默坐，應笑我營營。"]', '["僧話磻溪叟，平生重赤松。","夜堂悲蟋蟀，秋水老芙蓉。","吟坐倦垂釣，闲行多倚筇。","闻名来已久，未得一相逢。","塔见移来影，鐘闻過去声。","一斋唯默坐，應笑我營營。"]', '诗', 'shi', '', NULL, '寄李處士 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6166ade-91c8-4f2b-8d7f-907ded6c50ba', '客中立春', '客中立春', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["玉燭傳佳節，陽和應此辰。","土牛呈歲稔，綵燕表年春。","臘盡星回次，寒餘月建寅。","梅花將柳色，偏思越鄉人。"]', '["玉燭傳佳節，陽和應此辰。","土牛呈歲稔，綵燕表年春。","臘尽星回次，寒餘月建寅。","梅花將柳色，偏思越乡人。"]', '诗', 'shi', '', NULL, '客中立春 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dc752f9-1582-45e2-81c1-e4604250e09c', '南塘暝興', '南塘暝兴', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["水色昏猶白，霞光暗漸無。","風荷搖破扇，波月動連珠。","蟋蟀啼相應，鴛鴦宿不孤。","小僮頻報夜，歸步尚踟躕。"]', '["水色昏猶白，霞光暗漸無。","风荷搖破扇，波月动連珠。","蟋蟀啼相應，鴛鴦宿不孤。","小僮頻報夜，归步尚踟躕。"]', '诗', 'shi', '', NULL, '南塘暝興 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e336564-b0c4-4df2-8ba9-efb897cf6d57', '送鄭谷歸宜春', '送鄭谷归宜春', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["無成歸故國，上馬亦高歌。","況是飛鳴後，殊爲喜慶多。","暑消嵩岳雨，涼吹洞庭波。","莫使閑吟去，須期接盛科。"]', '["無成归故国，上马亦高歌。","況是飞鳴後，殊爲喜慶多。","暑消嵩岳雨，涼吹洞庭波。","莫使闲吟去，須期接盛科。"]', '诗', 'shi', '', NULL, '送鄭谷歸宜春 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72072457-9ada-48c4-b9ff-071881f19d49', '送曾德邁歸寧宜春', '送曾德邁归寧宜春', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["湘東山川有清輝，袁水詞人得意歸。","幾府爭馳毛義檄，一鄉看侍老萊衣。","筵開灞岸臨清淺，路去藍關入翠微。","想到宜陽更無事，併將歡慶奉庭闈。"]', '["湘东山川有清輝，袁水词人得意归。","幾府爭驰毛義檄，一乡看侍老萊衣。","筵开灞岸臨清淺，路去藍关入翠微。","想到宜陽更無事，併將歡慶奉庭闈。"]', '诗', 'shi', '', NULL, '送曾德邁歸寧宜春 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db07af25-0475-4859-a002-586d17f54324', '山泉', '山泉', '25aefc8a-cae1-4d01-9ee6-77e500900676', '唐', '["半空飛下水，勢去響如雷。","靜徹啼猨寺，高凌坐客臺。","耳同經劒閣，身若到天台。","濺樹吹成凍，凌祠觸作灰。","深中試楖栗，淺處落莓苔。","半夜重城閉，潺湲枕上來。"]', '["半空飞下水，勢去响如雷。","静徹啼猨寺，高凌坐客台。","耳同經劒閣，身若到天台。","濺樹吹成凍，凌祠觸作灰。","深中試楖栗，淺处落莓苔。","半夜重城閉，潺湲枕上来。"]', '诗', 'shi', '', NULL, '山泉 李洞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8846b596-a357-4c82-852d-330a21c43826', '松', '松', '530991f4-f560-47e7-be37-b98d750da856', '唐', '["雲外千尋好性靈，伴杉陪柏事孤貞。","招呼暑氣終無分，應和涼風別有聲。","細雨灑時花旋落，道人食處葉重生。","如逢郢匠垂搜採，爲棟爲梁力不輕。"]', '["云外千尋好性靈，伴杉陪柏事孤貞。","招呼暑氣終無分，應和涼风別有声。","細雨灑时花旋落，道人食处葉重生。","如逢郢匠垂搜採，爲棟爲梁力不轻。"]', '诗', 'shi', '', NULL, '松 盧士衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('467b61ed-3ea1-4993-a1de-7a50605468e0', '再遊紫陽洞重題小松', '再游紫陽洞重題小松', '530991f4-f560-47e7-be37-b98d750da856', '唐', '["仙家種此充朝食，葉葉枝枝造化力。","去年見時似鶴高，今年蕭騷八九尺。","不同矮檜終委地，定向晴空倚天碧。","好期逸士統貞根，昂枝點破秋苔色。","尋思凡眼重花開，寧知此木超塵埃。","秪是十年五年間，堪作大廈之宏材。"]', '["仙家種此充朝食，葉葉枝枝造化力。","去年见时似鹤高，今年蕭騷八九尺。","不同矮檜終委地，定向晴空倚天碧。","好期逸士統貞根，昂枝点破秋苔色。","尋思凡眼重花开，寧知此木超塵埃。","秪是十年五年间，堪作大廈之宏材。"]', '诗', 'shi', '', NULL, '再遊紫陽洞重題小松 盧士衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc5df054-37f7-4394-b6bf-7f69ab0f4920', '湘江曉望', '湘江晓望', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["笙歌歡罷散離筵，水色朦朧蘸宿煙。","山響疎鐘何處寺，火光收釣下灘船。","微雲過島侵微月，古岸平江浸遠天。","歸夢已闌風色動，孤帆仍要住無緣。"]', '["笙歌歡罷散離筵，水色朦朧蘸宿煙。","山响疎鐘何处寺，火光收釣下灘船。","微云過島侵微月，古岸平江浸远天。","归梦已闌风色动，孤帆仍要住無緣。"]', '诗', 'shi', '', NULL, '湘江曉望 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9266f86-f64d-4b61-b813-87501807f89d', '早行', '早行', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["結束何妨早，將行四顧頻。","山前猶見月，陌上未逢人。","遠樹動宿鳥，危橋怯病身。","漸明恆自慰，應免復迷津。"]', '["結束何妨早，將行四顧頻。","山前猶见月，陌上未逢人。","远樹动宿鸟，危橋怯病身。","漸明恆自慰，應免复迷津。"]', '诗', 'shi', '', NULL, '早行 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e717bb6-ef42-4659-863c-ed1554bf3549', '遊嵩山', '游嵩山', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["獨背焦桐訪洞天，暫攀靈迹棄塵緣。","深逢野草皆疑藥，靜見樵人恐是仙。","翠木入雲空自老，古碑橫水莫知年。","可憐幽景堪長往，一任人間歲月遷。"]', '["独背焦桐訪洞天，暫攀靈迹棄塵緣。","深逢野草皆疑藥，静见樵人恐是仙。","翠木入云空自老，古碑橫水莫知年。","可怜幽景堪长往，一任人间歲月遷。"]', '诗', 'shi', '', NULL, '遊嵩山 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ab710e-616e-4afc-bbf5-8073f973b396', '九華望廬山', '九华望廬山', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["九江山勢盡崢嶸，惟有匡廬最得名。","萬疊影遮殘雪在，數峰嵐帶夕陽明。","冷侵醉榻鋪秋色，高亞吟龍送水聲。","只待丹霄酬志了，白雲深處是歸程。"]', '["九江山勢尽崢嶸，惟有匡廬最得名。","万叠影遮殘雪在，數峰嵐带夕陽明。","冷侵醉榻鋪秋色，高亞吟龙送水声。","只待丹霄酬志了，白云深处是归程。"]', '诗', 'shi', '', NULL, '九華望廬山 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33f6e824-97dd-4fc1-a37d-1b48db29bda8', '道傍松', '道傍松', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["偃蓋當衢莫記年，獨含蒼翠鶴應憐。","垂陰獨向笙歌地，有韻自成風雨天。","塵□路岐分夜月，燒侵根脚起殘煙。","論功只合行人賞，銷得煩蒸古道邊。"]', '["偃蓋當衢莫記年，独含蒼翠鹤應怜。","垂陰独向笙歌地，有韻自成风雨天。","塵□路岐分夜月，燒侵根脚起殘煙。","論功只合行人賞，銷得煩蒸古道邊。"]', '诗', 'shi', '', NULL, '道傍松 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26a5d526-2353-4fc1-9a6d-83df7695debc', '月中桂', '月中桂', '8dc1464c-4985-49d8-97d4-dd4a15232a68', '唐', '["斷破重輪種者誰，銀蟾何事便相隨。","莫言望夜無攀處，却是吟人有得時。","孤影不凋清露滴，異香常在好風吹。","幾回目斷雲霄外，未必姮娥惜一枝。"]', '["斷破重輪種者誰，銀蟾何事便相隨。","莫言望夜無攀处，却是吟人有得时。","孤影不凋清露滴，異香常在好风吹。","幾回目斷云霄外，未必姮娥惜一枝。"]', '诗', 'shi', '', NULL, '月中桂 熊皎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3340b36f-7c4d-412e-a4c0-248cdf5c804d', '湖上望廬山', '湖上望廬山', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["輟櫂南湖首重迴，笑青吟翠向崔嵬。","天應不許人全見，長把雲藏一半來。"]', '["輟櫂南湖首重迴，笑青吟翠向崔嵬。","天應不許人全见，长把云藏一半来。"]', '诗', 'shi', '', NULL, '湖上望廬山 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('178e4bd1-f606-4904-965e-8fe4f2437350', '題梅嶺泉', '題梅嶺泉', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["梅嶺舊聞傳，林亭勢峞然。","登臨真不易，幽勝恐無先。","楚野平千里，吳江曲一邊。","標形都大別，洞府豈知焉。","飛閣橫空去，征帆落面前。","南雄雉堞峻，北壯鳳臺連。","爛熳三春媚，參差百卉妍。","風桃諸處錦，洛竹半溪煙。","燕入晴梁語，鶯從暖谷遷。","石根朝靄碧，簾際晚霞鮮。","逕柳行難約，庭莎醉好眠。","清明時更異，造化意疑偏。","不獨宜韶景，尤須看暑天。","藥苗繁似結，蘿蔓猛如編。","珠亞垂枝果，冰澄汲井泉。","粉牆蜩蛻落，丹檻雀雛顛。","炎氣微茫覺，清飆左右穿。","雲峰從勃起，葵葉豈勞扇。","又見秋天麗，渾將夏日懸。","紅黰著霜樹，香老臥池邊。","菱芡誰鋪繡，莓苔自學錢。","暗蟲依砌響，明月逗簾圓。","小砌滋新菊，高軒噪暮蟬。","雨聲寒颯颯，雁影曉聯聯。","釋此何堪玩，深冬更可憐。","窗中看短景，樹裏見重川。","岡阜分明出，杉松氣概全。","謳成白雪曲，吟是早梅篇。","剏制誰人解，根基太守賢。","或時留皂蓋，盡日簇華筵。","誰詠憂黎庶，狂遊泥管弦。","交加豐玉食，來去迸金船。","侍從非常客，俳諧像列仙。","畫旗張赫奕，妖妓舞嬋娟。","罷宴心猶戀，將歸興尚牽。","秪應愁逼夜，寧厭賞經年。","孤賤今何幸，躋攀奈有緣。","展眉驚豁達，徐步喜周旋。","諷詠雖知苦，推功靡極玄。","聊書四十韻，甘責未精專。"]', '["梅嶺旧闻傳，林亭勢峞然。","登臨真不易，幽勝恐無先。","楚野平千里，吳江曲一邊。","標形都大別，洞府豈知焉。","飞閣橫空去，征帆落面前。","南雄雉堞峻，北壯鳳台連。","爛熳三春媚，參差百卉妍。","风桃諸处錦，洛竹半溪煙。","燕入晴梁語，鶯從暖谷遷。","石根朝靄碧，簾際晚霞鲜。","逕柳行难約，庭莎醉好眠。","清明时更異，造化意疑偏。","不独宜韶景，尤須看暑天。","藥苗繁似結，蘿蔓猛如編。","珠亞垂枝果，冰澄汲井泉。","粉牆蜩蛻落，丹檻雀雛顛。","炎氣微茫覺，清飆左右穿。","云峰從勃起，葵葉豈勞扇。","又见秋天丽，渾將夏日懸。","紅黰著霜樹，香老臥池邊。","菱芡誰鋪繡，莓苔自学錢。","暗蟲依砌响，明月逗簾圓。","小砌滋新菊，高軒噪暮蟬。","雨声寒颯颯，雁影晓聯聯。","釋此何堪玩，深冬更可怜。","窗中看短景，樹裏见重川。","岡阜分明出，杉松氣概全。","謳成白雪曲，吟是早梅篇。","剏制誰人解，根基太守賢。","或时留皂蓋，尽日簇华筵。","誰詠憂黎庶，狂游泥管弦。","交加豐玉食，来去迸金船。","侍從非常客，俳諧像列仙。","畫旗張赫奕，妖妓舞嬋娟。","罷宴心猶戀，將归兴尚牽。","秪應愁逼夜，寧厭賞經年。","孤賤今何幸，躋攀奈有緣。","展眉驚豁達，徐步喜周旋。","諷詠雖知苦，推功靡極玄。","聊书四十韻，甘責未精專。"]', '诗', 'shi', '', NULL, '題梅嶺泉 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('080e1c3d-6f9b-4f0d-9153-913e3eecfc2b', '廬山瀑布', '廬山瀑布', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["有山來便有，萬丈落雲端。","霧噴千巖濕，雷傾九夏寒。","圖中僧寫去，湖上客迴看。","却羨爲猨鶴，飛鳴近碧湍。"]', '["有山来便有，万丈落云端。","霧噴千巖濕，雷傾九夏寒。","圖中僧寫去，湖上客迴看。","却羨爲猨鹤，飞鳴近碧湍。"]', '诗', 'shi', '', NULL, '廬山瀑布 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cec4c388-69ef-4193-9022-8537890625d3', '牡丹', '牡丹', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["意態天生異，轉看看轉新。","百花休放豔，三月始爲春。","蝶死難離檻，鶯狂不避人。","其如豪貴地，清醒復何因。"]', '["意態天生異，轉看看轉新。","百花休放豔，三月始爲春。","蝶死难離檻，鶯狂不避人。","其如豪貴地，清醒复何因。"]', '诗', 'shi', '', NULL, '牡丹 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67db364d-d692-4936-94fe-36b9c2f5aee1', '主人司空後亭牡丹', '主人司空後亭牡丹', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["佳卉挺芳辰，夭容乃絕倫。","望開從隔歲，愁過即無春。","體物真英氣，餘花似庶人。","蜂攢知眷戀，鳥語亦殷勤。","況在豪華地，寧同里巷塵。","酷憐應喪德，多賞奈怡神。","忌穢栽時土，嘗甜折處津。","繞行那識倦，圍坐豈辭頻。","入夢殊巫峽，臨池勝洛濱。","樂喧絲雜竹，露漬卯連寅。","飲興尤思滿，吟情自合新。","怕風惟怯夜，憂雨不經旬。","欄檻爲良援，亭臺是四鄰。","雖非能伐性，爭免礙還淳。","鬬豔何慚蜀，矜繁未讓秦。","私心期一日，許近看逡巡。"]', '["佳卉挺芳辰，夭容乃絕倫。","望开從隔歲，愁過即無春。","體物真英氣，餘花似庶人。","蜂攢知眷戀，鸟語亦殷勤。","況在豪华地，寧同里巷塵。","酷怜應喪德，多賞奈怡神。","忌穢栽时土，嘗甜折处津。","繞行那識倦，圍坐豈辞頻。","入梦殊巫峽，臨池勝洛濱。","乐喧絲杂竹，露漬卯連寅。","饮兴尤思满，吟情自合新。","怕风惟怯夜，憂雨不經旬。","欄檻爲良援，亭台是四鄰。","雖非能伐性，爭免礙還淳。","鬬豔何慚蜀，矜繁未讓秦。","私心期一日，許近看逡巡。"]', '诗', 'shi', '', NULL, '主人司空後亭牡丹 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('686a3a13-87f8-4c84-a44f-6b60a32630ff', '看牡丹二首 一', '看牡丹二首 一', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["莫將紅粉比穠華，紅粉那堪比此花。","隔院聞香誰不惜，出欄呈豔自應誇。","北方有態須傾國，西子能言亦喪家。","輸我一枝和曉露，真珠簾外向人斜。"]', '["莫將紅粉比穠华，紅粉那堪比此花。","隔院闻香誰不惜，出欄呈豔自應誇。","北方有態須傾国，西子能言亦喪家。","輸我一枝和晓露，真珠簾外向人斜。"]', '诗', 'shi', '', NULL, '看牡丹二首 一 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('425cd6a2-01c4-46d1-a27c-fda39aaaaedc', '看牡丹二首 二', '看牡丹二首 二', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["看花長到牡丹月，萬事全忘自不知。","風促乍開方可惜，雨淋將謝可堪悲。","閑年對坐渾成偶，醉後拋眠恐負伊。","也擬便休還改過，迢迢爭奈一年期。"]', '["看花长到牡丹月，万事全忘自不知。","风促乍开方可惜，雨淋將謝可堪悲。","闲年对坐渾成偶，醉後拋眠恐負伊。","也擬便休還改過，迢迢爭奈一年期。"]', '诗', 'shi', '', NULL, '看牡丹二首 二 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5999f252-921a-4ca5-b4d0-eaa26b2fadc9', '題未開牡丹', '題未开牡丹', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["青苞雖小葉雖疎，貴氣高情便有餘。","渾未盛時猶若此，算應開日合何如。","尋芳蝶已棲丹檻，襯落苔先染石渠。","無限風光言不得，一心留在暮春初。"]', '["青苞雖小葉雖疎，貴氣高情便有餘。","渾未盛时猶若此，算應开日合何如。","尋芳蝶已棲丹檻，襯落苔先染石渠。","無限风光言不得，一心留在暮春初。"]', '诗', 'shi', '', NULL, '題未開牡丹 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83883150-06ec-451b-a7c4-e135f2de9b41', '主人司空見和未開牡丹輙却奉和', '主人司空见和未开牡丹輙却奉和', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["把筆臨芳不自怡，首徵章句促妖期。","已驚常調言多鄙，遽捧高吟媿可知。","絕代貞名應愈重，千金方笑更難移。","狂歌狂醉猶堪羨，大拙當時是老時。"]', '["把笔臨芳不自怡，首徵章句促妖期。","已驚常調言多鄙，遽捧高吟媿可知。","絕代貞名應愈重，千金方笑更难移。","狂歌狂醉猶堪羨，大拙當时是老时。"]', '诗', 'shi', '', NULL, '主人司空見和未開牡丹輙却奉和 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caa55241-a4fa-418e-875d-f2bec7e1a0be', '又題牡丹上主人司空', '又題牡丹上主人司空', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["一年芳勝一年芳，愛重賢侯意異常。","手闢紅房看闊狹，自張青幄蓋馨香。","白疑美玉無多潤，紫覺靈芝不是祥。","秪恐夢徵他日去，又須疑向鳳池傍。"]', '["一年芳勝一年芳，愛重賢侯意異常。","手闢紅房看闊狹，自張青幄蓋馨香。","白疑美玉無多潤，紫覺靈芝不是祥。","秪恐梦徵他日去，又須疑向鳳池傍。"]', '诗', 'shi', '', NULL, '又題牡丹上主人司空 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb6ff04c-8734-45f6-836f-313faf26ee7a', '牡丹落後有作', '牡丹落後有作', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["未發先愁有一朝，如今零落更魂銷。","青叢別後無多色，紅線穿來已半焦。","蓄恨綺羅猶眷眷，薄情蜂蝶去飄飄。","明年雖道還期在，爭奈憑欄乍寂寥。"]', '["未發先愁有一朝，如今零落更魂銷。","青叢別後無多色，紅線穿来已半焦。","蓄恨綺羅猶眷眷，薄情蜂蝶去飄飄。","明年雖道還期在，爭奈憑欄乍寂寥。"]', '诗', 'shi', '', NULL, '牡丹落後有作 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75f27f46-9bc8-4ac3-8d25-a03f4d20c580', '柳絮詠', '柳絮詠', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["年年三月裏，隨處自悠揚。","雨過渾疑盡，風來特地狂。","入花蜂有礙，遮水燕無妨。","苦是添離思，青門道路長。"]', '["年年三月裏，隨处自悠揚。","雨過渾疑尽，风来特地狂。","入花蜂有礙，遮水燕無妨。","苦是添離思，青门道路长。"]', '诗', 'shi', '', NULL, '柳絮詠 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a556fd46-65c6-44b5-b189-9641bb118d69', '甘露寺紫薇花', '甘露寺紫薇花', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["蜀葵鄙下兼全落，菡萏清高且未開。","赫日迸光飛蝶去，紫薇擎豔出林來。","聞香不稱從僧舍，見影尤思在酒杯。","誰笑晚芳爲賤劣，便饒春麗已塵埃。","牽吟過夏惟憂盡，立看移時亦忘迴。","惆悵寓居無好地，嬾能分取一枝栽。"]', '["蜀葵鄙下兼全落，菡萏清高且未开。","赫日迸光飞蝶去，紫薇擎豔出林来。","闻香不稱從僧舍，见影尤思在酒杯。","誰笑晚芳爲賤劣，便饒春丽已塵埃。","牽吟過夏惟憂尽，立看移时亦忘迴。","惆悵寓居無好地，嬾能分取一枝栽。"]', '诗', 'shi', '', NULL, '甘露寺紫薇花 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be5ffbdc-cce9-4542-a5b5-3a2fbaab2722', '芳草', '芳草', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["何處不相見，煙苗捧露心。","萋萋綠遠水，苒苒在空林。","野吹閑搖闊，遊人醉臥深。","南朝古城裏，碑石又應沈。"]', '["何处不相见，煙苗捧露心。","萋萋綠远水，苒苒在空林。","野吹闲搖闊，游人醉臥深。","南朝古城裏，碑石又應沈。"]', '诗', 'shi', '', NULL, '芳草 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('245b6fcc-34ac-4348-bc0b-69f2f5aeb4d6', '春苔', '春苔', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["底物最牽吟，秋苔獨自尋。","何時連夜雨，疊翠滿松陰。","湘岸荒祠靜，吳宮古砌深。","侯門還可惜，長被馬蹄侵。"]', '["底物最牽吟，秋苔独自尋。","何时連夜雨，叠翠满松陰。","湘岸荒祠静，吳宮古砌深。","侯门還可惜，长被马蹄侵。"]', '诗', 'shi', '', NULL, '春苔 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('670d3f86-09bf-4d30-9573-1e76f86adcd9', '老松', '老松', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["鬱鬱復蒼蒼，秋風韻更長。","空心應有□，老葉不知霜。","子落生深澗，陰清背夕陽。","如逢東岱雨，猶得覆秦王。"]', '["鬱鬱复蒼蒼，秋风韻更长。","空心應有□，老葉不知霜。","子落生深澗，陰清背夕陽。","如逢东岱雨，猶得覆秦王。"]', '诗', 'shi', '', NULL, '老松 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5968f3f8-a27a-4b5e-98ac-43641a9bbd2b', '柳 一', '柳 一', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["蘢葱二月初，青軟自相紆。","意態花猶少，風流木更無。","影繁晴陌上，煙重古城隅。","煬帝河聲裏，幾番榮又枯。"]', '["蘢葱二月初，青軟自相紆。","意態花猶少，风流木更無。","影繁晴陌上，煙重古城隅。","煬帝河声裏，幾番榮又枯。"]', '诗', 'shi', '', NULL, '柳 一 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21de5487-0944-4b47-b55c-363c57af140f', '柳 二', '柳 二', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["數樹新栽在畫橋，春來猶自長長條。","東風多事剛牽引，已解纖纖學舞腰。"]', '["數樹新栽在畫橋，春来猶自长长條。","东风多事剛牽引，已解纖纖学舞腰。"]', '诗', 'shi', '', NULL, '柳 二 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21422f86-b930-40ba-ba61-ab298568838d', '柳 三', '柳 三', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["金堤堤上一林煙，況近清明二月天。","別有數枝遙望見，畫橋南面拂鞦韆。"]', '["金堤堤上一林煙，況近清明二月天。","別有數枝遙望见，畫橋南面拂鞦韆。"]', '诗', 'shi', '', NULL, '柳 三 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afadd1a9-e0d3-49fd-9fda-04166558563b', '柳 四', '柳 四', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["春物牽情不奈何，就中楊柳態難過。","也知是處無花去，爭奈看時未覺多。"]', '["春物牽情不奈何，就中楊柳態难過。","也知是处無花去，爭奈看时未覺多。"]', '诗', 'shi', '', NULL, '柳 四 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('212b7544-93bb-41ab-9aab-613523bbadf9', '柳 五', '柳 五', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["小眉初展綠條稠，露壓煙濛不自由。","莫是折來偏屬意，依稀相似是風流。"]', '["小眉初展綠條稠，露壓煙濛不自由。","莫是折来偏屬意，依稀相似是风流。"]', '诗', 'shi', '', NULL, '柳 五 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('721e7a46-1838-4854-8723-e90a329b352a', '柳 六', '柳 六', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["九衢春霽濕雲凝，着地𣯶𣯶礙馬行。","擬折無端拋又戀，亂穿來去羨黃鶯。"]', '["九衢春霽濕云凝，着地𣯶𣯶礙马行。","擬折無端拋又戀，亂穿来去羨黄鶯。"]', '诗', 'shi', '', NULL, '柳 六 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2756fbe-a287-4119-8380-9f2b1faaf09d', '柳 七', '柳 七', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["千樹陰陰蓋御溝，雪花金穗思悠悠。","先朝事後應無也，惟是荒根逐碧流。"]', '["千樹陰陰蓋御溝，雪花金穗思悠悠。","先朝事後應無也，惟是荒根逐碧流。"]', '诗', 'shi', '', NULL, '柳 七 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17f502e6-30d2-44e0-88a4-2269be1a29fc', '柳 八', '柳 八', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["搖蕩和風恃賴春，蘸流遮路逐年新。","顛狂絮落還堪恨，分外欺凌寂寞人。"]', '["搖蕩和风恃賴春，蘸流遮路逐年新。","顛狂絮落還堪恨，分外欺凌寂寞人。"]', '诗', 'shi', '', NULL, '柳 八 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d5afa1d-5a0d-48c6-a562-39d85d3ba230', '柳 九', '柳 九', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["暖催春促吐芳芽，伴雨從風處處斜。","莫道玄功無定配，不然爭得見桃花。"]', '["暖催春促吐芳芽，伴雨從风处处斜。","莫道玄功無定配，不然爭得见桃花。"]', '诗', 'shi', '', NULL, '柳 九 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e6fc875-7c4d-48cc-9f1e-aeee70102e91', '柳 十', '柳 十', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["小池前後碧江濱，窣翠拋青爛熳春。","不是和風爲擡舉，可能開眼向行人。"]', '["小池前後碧江濱，窣翠拋青爛熳春。","不是和风爲擡舉，可能开眼向行人。"]', '诗', 'shi', '', NULL, '柳 十 孫魴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f547f640-78a7-4b87-8d8a-e7445d4a1941', '柳 十一', '柳 十一', '8ba4ebe0-220d-43aa-a55b-f81713932659', '唐', '["深綠依依配淺黃，兩般顏色一般香。","到頭嬝娜成何事，秪解年年斷客腸。"]', '["深綠依依配淺黄，兩般顏色一般香。","到头嬝娜成何事，秪解年年斷客腸。"]', '诗', 'shi', '', NULL, '柳 十一 孫魴 shi');
